        (26, 30, '2026-08-05 18:35:57.575094', '2026-08-05 18:35:57.575125', 'I am currently pursuing a degree in Software Engineering at FPT University. As a proactive and passionate learner, I have independently acquired and applied programming skills in various personal projects. Looking forward, I aspire to become an innovative and impactful software developer in the industry.', 'Intern', 'Front-end Developer', '["Data Structures and Algorithms", "OOP with Java Lab", "Software Requirement and Software Testing"]', '["Web Design for Everybody: Basics of Web Development & Coding - University of Michigan (3/2024)", "Software Development Lifecycle - University of Minnesota (8/2024)"]', '[{"gpa": "3.2", "major": "Software Engineering", "degree": null, "school": "FPT UNIVERSITY", "end_date": "Now", "start_date": "10/2022"}]', '[{"name": "KOIFARMSHOP (E-COMMERCE WEBSITE)", "role": "Front-end Developer", "outcome": "Successfully developed both front-end and back-end functionalities, database system, and system documentation (SRS, SDS).", "teamSize": 1, "usedTools": ["Bootstrap", "Java 8", "ReactJS", "MS SQL Server", "Spring Boot", "Sona Lint"], "description": "A system designed to manage the entire process of selling Koi fish at the farm, offering a seamless and efficient experience for showcasing fish, managing sales, customer care, Pay with VNPAY and post-sale services"}, {"name": "CARSHOP (E-COMMERCE WEBSITE)", "role": "Fullstack", "outcome": "Designed and implemented the overall structure of the e-commerce website including backend and frontend functionalities.", "teamSize": 1, "usedTools": ["Bootstrap", "Java 8", "JSP", "Servlet", "MS SQL Server"], "description": "A system for buying and selling vehicles, streamlining the process with detailed listings, secure transactions, and customer management features."}]', '["English (Level 6 FPT University / Approx IELTS 5.0)", "Japanese (Beginner)"]', '["Java", "JavaScript", "C", "MS SQL Server", "MySQL", "NodeJS", "ReactJS"