        (120, null, 9, null, '2026-08-09 05:36:36.077135', '2026-08-09 08:19:34.519159', 'IT', 'CANCELLED', 'STANDARD_MOCK', null, '75766854-ecee-4c01-a550-345c352f6384', null, '{"id": 24, "tools": ["Git", "GitHub", "GitLab", "Maven", "Jira", "Swagger", "Docker", "Postman", "JUnit", "xUnit"], "projects": [{"name": "Movie Theater", "role": "Back-end, Leader", "outcome": "Final score: 9.7", "teamSize": 5, "usedTools": ["ASP.NET Core", "ASP.NET MVC", "PostgreSQL", "SignalR", "GitHub"], "description": "An online movie ticketing system featuring real-time seat map visualization and modules for movie, showtimes, theaters, promotions, and user accounts."}, {"name": "CHILD VACCINE SCHEDULE TRACKING SYSTEM", "role": "Back-end, Leader", "outcome": "Supports individual/group scheduling, automatic reminders, secure payments, and AI-powered customer support.", "teamSize": 3, "usedTools": ["Java", "Spring Boot", "Spring Security", "Spring AI", "MSSQL", "Spring Mail"], "description": "A web application that manages children''s vaccination schedules, allowing parents and health centers to schedule, track, and update vaccination records."}, {"name": "BAMBI KITCHEN", "role": "Back-end, Leader", "outcome": "Implemented JWT/OAuth2 authentication, warehouse management, multi-channel payment (Cash, Momo, VNPAY) and AI integration via Gemini AI.", "teamSize": 6, "usedTools": ["Spring Boot", "Spring Security", "Spring AI", "MSSQL", "Cloudinary", "Firebase Cloud Messaging", "Spring Mail"], "description": "A healthy food chain application where customers can customize dish ingredients step by step with integrated AI for order evaluation."}], "createdAt": [2026, 8, 4, 16, 14, 33, 422891000], "updatedAt": [2026, 8, 4, 16, 14, 33, 422919000], "educations": [{"gpa": "3.2", "major": "Software Engineering", "degree": null, "school": "FPT University", "end_date": "2026", "start_date": "2022"}], "softSkills": ["Technical Reading Proficiency in English", "Fast learner", "adaptability", "problem-solvi