        (9, null, 2, null, '2026-03-15 15:35:55.407087', '2026-03-16 07:31:21.191745', 'IT', 'CANCELLED', 'STANDARD_MOCK', null, 'ca10f286-a37a-4293-82e2-8dda82cc87ea', null, '{"id": 1, "user": {"id": 2, "name": "THU HA NGUYEN PHAM", "role": "USER", "cvUrl": "https://res.cloudinary.com/dimvyno0z/raw/upload/v1772876158/my_app/docs/a17ef5f4-506b-4e14-a9ab-74e2a851af2d.pdf", "email": null, "major": "CNTT", "isActive": true, "password": null, "avatarUrl": "https://res.cloudinary.com/dimvyno0z/image/upload/v1772820944/my_app/images/t6hzjlhcmuj8sq7drhm4.png", "public_id": "my_app/images/t6hzjlhcmuj8sq7drhm4", "university": "fpt", "cv_public_id": "my_app/docs/a17ef5f4-506b-4e14-a9ab-74e2a851af2d.pdf"}, "tools": ["Git/GitHub/GitLab", "Maven", "Jira", "Swagger", "Postman"], "projects": [{"name": "Child Vaccine Schedule Tracking System", "role": "Leader, Back-end", "outcome": null, "teamSize": 3, "usedTools": ["Spring Boot", "React Js", "SQL Server"], "description": "Vaccination scheduling, payments, service reviews, and post-injection reaction updates. Track vaccination progress and view immunization history. Allows medical facilities to record vaccination results into a child''s profile. Dashboard & Reporting. Automated email reminders and notifications. Management of vaccine inventory, users, appointments, etc."}, {"name": "Smart Wallet", "role": "Leader, Back-end", "outcome": null, "teamSize": 3, "usedTools": ["Spring Boot", "React", "SQL Server"], "description": "Manage income and expenditure, helping users track income, expenditure and consumption appropriately. Allow users to classify income and expenditure and create budgets and track income and expenditure according to the budget. The home page is intuitive and easy to observe."}, {"name": "Product Information", "role": null, "outcome": null, "teamSize": null, "usedTools": ["MVC", "JSP", "tomcat", "session", "filterchain", "JDBC", "cookie"], "description": "Manage products by category. Add favorite products. Basic CRUD,Login."}], "createdAt": [2026, 3, 6, 18, 29, 27, 730816000], "updatedAt": [2026, 3, 9, 15, 7, 28, 6663000], "educations": [{"gpa": "3.5", "major": "Software Engineering", "degree": null, "school": "FPT University", "end_date": "2026", "start_date": "2022"}], "softSkills": ["Teamwork", "Problem-solving skills", "Self-study and research", "Presentation skills", "Project management", "English (Fair)"], "targetRole": "Java Developer", "targetLevel": "Fresher", "achievements": ["Good students (2023 - 2025)", "Honor (2023 - 2025)"], "introduction": "With a background in Java development, I am looking for the right opportunity to grow my abilities. I am committed to using my logical thinking and passion to quickly turn theoretical knowledge into real-world skills. My aim is to gain valuable experience with every project and steadily develop into a proficient and effective software developer.", "certifications": ["Web Design for Everybody: Basics of Web Development & Coding (2024)", "Software Development LifeCycle (2024)", "Java FullStack Developer (2024)"], "technicalSkills": ["Java", "C#", "HTML/CSS", "Spring Security", "Spring Data JPA", "Spring MVC", "Validation", "DI/IoC", "MSSQL", "PostgreSQL", "JPA/Hibernate"], "workExperiences": [{"company": "FPT Software Academy", "end_date": "8/2025", "position": ".NET INTERNSHIP", "start_date": "5/2025", "description": "Final Project of the Training Course: Movie Theater. Develop an online movie ticket booking system that displays real-time seat maps. Integrate modules: manage movies, showtimes, screening rooms, promotions, and user accounts, accumulate points. Support user authorization (customers, employees, administrators)."}]}', '{"basic_info": {"job_title": null, "industry_domain": null, "seniority_level": "Fresher"}, "competencies": {"hard_skills": [], "soft_skills": [], "tools_and_platforms": []}, "responsibilities": []}', null, '{"domain": "IT", "language": "VI", "difficulty": "FRESHER_BASIC", "interview_mode": "STANDARD_MOCK", "duration_minutes": 15}', null),
        (11, 4.6875, 2, '2026-03-15 16:47:31.437922', '2026-03-15 16:33:51.145193', '2026-03-15 16:47:31.439824', 'IT', 'COMPLETED', 'STANDARD_MOCK', 'REJECT', 'a7fcd180-fa1b-4e1b-96a5-c01fea5328cc', '{"blueprint": [{"questions": [{"order": 1, "rag_keyword": null, "question_text": "Chào Thu Hà, rất vui được gặp bạn hôm nay. Bạn có thể giới thiệu ngắn gọn về bản thân và chia sẻ điều gì khiến bạn ứng tuyển vào vị trí Java Developer tại công ty chúng tôi không?", "question_type": "CORE"}], "phase_name": "Chào hỏi", "duration_minutes": 1}, {"questions": [{"order": 2, "rag_keyword": null, "question_text": "Trong dự án ''Child Vaccine Schedule Tracking System'', bạn đóng vai trò Leader Back-end. Bạn có thể mô tả chi tiết hơn về những công việc cụ thể mà bạn đã thực hiện trong dự án này được không?", "question_type": "CORE"}, {"order": 3, "rag_keyword": "spring_boot_advantages", "question_text": "Bạn đã sử dụng Spring Boot trong dự án này. Bạn có thể giải thích tại sao bạn chọn Spring Boot thay vì các framework khác không?", "question_type": "CORE"}, {"order": 4, "rag_keyword": "sql_server_data_integrity", "question_text": "Bạn đã sử dụng SQL Server trong dự án này. Bạn có thể cho biết bạn đã sử dụng những tính năng nào của SQL Server để đảm bảo tính toàn vẹn dữ liệu?", "question_type": "CORE"}], "phase_name": "Project Deep-dive (Child Vaccine Schedule Tracking System)", "duration_minutes": 6}, {"questions": [{"order": 5, "rag_keyword": "java_oop_inheritance", "question_text": "Trong Java, bạn hiểu như thế nào về khái niệm ''kế thừa'' (Inheritance)? Hãy cho một ví dụ đơn giản.", "question_type": "CORE"}, {"order": 6, "rag_keyword": "java_equals_vs_double_equals", "question_text": "Bạn có thể giải thích sự khác biệt giữa `==` và `.equals()` trong Java không?", "question_type": "CORE"}, {"order": 7, "rag_keyword": "java_primitive_data_types", "question_text": "Bạn biết những kiểu dữ liệu cơ bản nào trong Java? Hãy kể tên và mô tả ngắn gọn.", "question_type": "CORE"}, {"order": 8, "rag_keyword": "java_exception_handling", "question_text": "Bạn có thể cho biết một vài cách để xử lý ngoại lệ (Exception) trong Java không?", "question_type": "CORE"}], "phase_name": "Technical Core (Java Fresher)", "duration_minutes": 7}], "strategy_analysis": "Chiến thuật phỏng vấn theo mode `STANDARD_MOCK` và độ khó `FRESHER_BASIC`. Tập trung vào hỏi sâu về dự án ''Child Vaccine Schedule Tracking System'' (40%) và các kiến thức Java cơ bản (50%). Thời lượng 15 phút, cần khoảng 6-8 câu hỏi."}', '{"id": 1, "user": {"id": 2, "name": "THU HA NGUYEN PHAM", "role": "USER", "cvUrl": "https://res.cloudinary.com/dimvyno0z/raw/upload/v1772876158/my_app/docs/a17ef5f4-506b-4e14-a9ab-74e2a851af2d.pdf", "email": null, "major": "CNTT", "isActive": true, "password": null, "avatarUrl": "https://res.cloudinary.com/dimvyno0z/image/upload/v1772820944/my_app/images/t6hzjlhcmuj8sq7drhm4.png", "public_id": "my_app/images/t6hzjlhcmuj8sq7drhm4", "university": "fpt", "cv_public_id": "my_app/docs/a17ef5f4-506b-4e14-a9ab-74e2a851af2d.pdf"}, "tools": ["Git/GitHub/GitLab", "Maven", "Jira", "Swagger", "Postman"], "projects": [{"name": "Child Vaccine Schedule Tracking System", "role": "Leader, Back-end", "outcome": null, "teamSize": 3, "usedTools": ["Spring Boot", "React Js", "SQL Server"], "description": "Vaccination scheduling, payments, service reviews, and post-injection reaction updates. Track vaccination progress and view immunization history. Allows medical facilities to record vaccination results into a child''s profile. Dashboard & Reporting. Automated email reminders and notifications. Management of vaccine inventory, users, appointments, etc."}, {"name": "Smart Wallet", "role": "Leader, Back-end", "outcome": null, "teamSize": 3, "usedTools": ["Spring Boot", "React", "SQL Server"], "description": "Manage income and expenditure, helping users track income, expenditure and consumption appropriately. Allow users to classify income and expenditure and create budgets and track income and expenditure according to the budget. The home page is intuitive and easy to observe."}, {"name": "Product Information", "role": null, "outcome": null, "teamSize": null, "usedTools": ["MVC", "JSP", "tomcat", "session", "filterchain", "JDBC", "cookie"], "description": "Manage products by category. Add favorite products. Basic CRUD,Login."}], "createdAt": [2026, 3, 6, 18, 29, 27, 730816000], "updatedAt": [2026, 3, 9, 15, 7, 28, 6663000], "educations": [{"gpa": "3.5", "major": "Software Engineering", "degree": null, "school": "FPT University", "end_date": "2026", "start_date": "2022"}], "softSkills": ["Teamwork", "Problem-solving skills", "Self-study and research", "Presentation skills", "Project management", "English (Fair)"], "targetRole": "Java Developer", "targetLevel": "Fresher", "achievements": ["Good students (2023 - 2025)", "Honor (2023 - 2025)"], "introduction": "With a background in Java development, I am looking for the right opportunity to grow my abilities. I am committed to using my logical thinking and passion to quickly turn theoretical knowledge into real-world skills. My aim is to gain valuable experience with every project and steadily develop into a proficient and effective software developer.", "certifications": ["Web Design for Everybody: Basics of Web Development & Coding (2024)", "Software Development LifeCycle (2024)", "Java FullStack Developer (2024)"], "technicalSkills": ["Java", "C#", "HTML/CSS", "Spring Security", "Spring Data JPA", "Spring MVC", "Validation", "DI/IoC", "MSSQL", "PostgreSQL", "JPA/Hibernate"], "workExperiences": [{"company": "FPT Software Academy", "end_date": "8/2025", "position": ".NET INTERNSHIP", "start_date": "5/2025", "description": "Final Project of the Training Course: Movie Theater. Develop an online movie ticket booking system that displays real-time seat maps. Integrate modules: manage movies, showtimes, screening rooms, promotions, and user accounts, accumulate points. Support user authorization (customers, employees, administrators)."}]}', '{"basic_info": {"job_title": null, "industry_domain": null, "seniority_level": "Fresher"}, "competencies": {"hard_skills": [], "soft_skills": [], "tools_and_platforms": []}, "responsibilities": []}', '{"history": [{"score": 6.0, "feedback": "Câu trả lời thiếu tính cụ thể về kỹ năng và kinh nghiệm thực tế, chỉ tập trung vào dự án tốt nghiệp.", "answerText": "Dạ em chào anh/chị. Em là Thu Hà, sinh viên mới ra trường chuyên ngành Kỹ thuật Phần mềm. Định hướng của em từ lúc đi học đã là làm Backend Developer với ngôn ngữ Java và hệ sinh thái Spring Boot. Em ứng tuyển vào công ty mình vì em thấy công ty có nhiều dự án thực tế rất hay. Trong thời gian làm đồ án tốt nghiệp, em cũng đã dùng Spring Boot và SQL Server để xây dựng một hệ thống quản lý lịch tiêm chủng cho trẻ em (Child Vaccine Schedule Tracking System). Em rất mong hôm nay được trao đổi và học hỏi thêm từ anh/chị ạ.", "suggestion": "Keywords: Spring Boot, RESTful APIs, SQL, Database Design, Scalability\n\nStructure:\n*   **Introduce Core Skills:** Briefly mention Java proficiency, Spring Boot experience, and database knowledge (SQL).\n*   **Project Deep Dive:** Focus on the technical challenges faced and *how* you solved them in the vaccine tracking system.  Mention specific Spring Boot features used (e.g., Spring Data JPA, Spring Security).\n*   **Company Alignment:** Explain *why* the company''s projects align with your skills and career goals. Be specific.\n*   **Learning Aspiration:** Express eagerness to learn and contribute to the team.\n\nSenior Tip: Briefly touch upon potential scalability concerns in your project and how you would address them in a production environment.", "questionText": "Chào Thu Hà, rất vui được gặp bạn hôm nay. Bạn có thể giới thiệu ngắn gọn về bản thân và chia sẻ điều gì khiến bạn ứng tuyển vào vị trí Java Developer tại công ty chúng tôi không?", "questionType": "BLUEPRINT", "questionOrder": 0, "behavioralWarnings": []}, {"score": 5.5, "feedback": "Thiếu tầm nhìn về tối ưu hóa hiệu năng và khả năng mở rộng của hệ thống, tập trung quá nhiều vào giải pháp tạm thời.", "answerText": "Dạ, trong dự án đó em làm Leader Back-end. Công việc chính của em là thiết kế database bằng SQL Server, dựng base project với Spring Boot và chia task cho 2 bạn nữa. Em cũng trực tiếp code các API quan trọng như đăng nhập, đăng ký và lấy danh sách lịch tiêm. Cuối cùng thì em dùng Postman để test các API này xem chạy đúng không rồi giao cho team Front-end ghép code ạ", "suggestion": "Keywords: Database Indexing, Query Optimization, Performance Bottleneck, Caching Strategies, Data Partitioning\n\nStructure:\n*   Bước 1: Phân tích hạn chế của SELECT * (bandwidth, I/O, CPU).\n*   Bước 2: Giải thích cách sử dụng Indexing để tăng tốc độ truy vấn (covering index, composite index).\n*   Bước 3: Đề xuất các kỹ thuật Query Optimization (explain plan, rewrite query).\n*   Bước 4: Thảo luận về các chiến lược Caching (Redis, Memcached) và Data Partitioning (sharding) để mở rộng hệ thống.\n\nSenior Tip: Hãy luôn cân nhắc Trade-off giữa tốc độ phát triển và hiệu năng/khả năng mở rộng của hệ thống. Đừng bỏ qua việc profiling và monitoring để xác định Performance Bottleneck.", "questionText": "Chào Thu Hà, cảm ơn bạn đã chia sẻ những thông tin rất hữu ích về bản thân và dự án tốt nghiệp của bạn. Chúng ta sẽ đi sâu hơn vào kinh nghiệm thực tế của bạn nhé. Trong dự án ''Child Vaccine Schedule Tracking System'', bạn đóng vai trò Leader Back-end. Bạn có thể mô tả chi tiết hơn về những công việc cụ thể mà bạn đã thực hiện trong dự án này được không?", "questionType": "BLUEPRINT", "questionOrder": 1, "behavioralWarnings": []}, {"score": null, "feedback": null, "answerText": "Dạ để đảm bảo toàn vẹn dữ liệu thì em có dùng Khóa chính và Khóa ngoại nối các bảng User, Child và Vaccine lại với nhau ạ. Còn về hiệu năng thì do data đồ án chưa nhiều nên em chưa dùng kỹ thuật gì đặc biệt ở tầng Database như Index cả. Em chủ yếu dùng câu lệnh SELECT * để lấy toàn bộ danh sách lịch tiêm về, sau đó dùng Java Stream API để filter ra các lịch tiêm của ngày hôm nay đưa lên màn hình cho lẹ, vì code Java em rành hơn SQL ạ.", "suggestion": null, "questionText": "Bạn có thể chia sẻ cụ thể hơn về cách bạn thiết kế database cho hệ thống này được không? Ví dụ, bạn đã sử dụng những kỹ thuật nào để đảm bảo tính toàn vẹn dữ liệu và hiệu năng của database?", "questionType": "FOLLOW_UP", "questionOrder": 2, "behavioralWarnings": []}, {"score": null, "feedback": null, "answerText": "Dạ thực ra em cũng có nghe nói là SELECT * thì tốn băng thông hơn, nhưng tại lúc làm đồ án em thấy số lượng cột của em cũng ít nên chắc không sao đâu ạ. Với lại em nghĩ nếu sau này hệ thống chậm thì mình cứ nâng cấp thêm RAM cho server hoặc dùng cache là được mà đúng không anh/chị? Em thấy dùng Java Stream để xử lý data vẫn trực quan và dễ debug hơn là viết mấy câu lệnh SQL phức tạp dưới database ạ", "suggestion": null, "questionText": "Bạn chia sẻ cách tiếp cận của mình khá thực tế. Tuy nhiên, việc sử dụng SELECT * có thể ảnh hưởng đến hiệu năng khi số lượng bản ghi tăng lên. Bạn có thể giải thích rõ hơn về những hạn chế của cách tiếp cận này và bạn đã cân nhắc những giải pháp nào để tối ưu hóa hiệu năng cho việc truy vấn dữ liệu không?", "questionType": "FOLLOW_UP", "questionOrder": 3, "behavioralWarnings": []}, {"score": 5.5, "feedback": "Câu trả lời thiếu chiều sâu về kiến trúc và các trade-off khi lựa chọn framework.", "answerText": "Dạ thực ra lúc làm đồ án thì thầy cô và các bạn đều bảo dùng Spring Boot cho nó phổ biến và dễ tìm tài liệu nên em dùng theo thôi ạ, chứ em cũng chưa tìm hiểu kỹ các Framework khác như Micronaut hay Quarkus để mà so sánh. Anh/chị có thể gợi ý giúp em một vài ưu điểm nổi bật nhất của Spring Boot so với việc dùng Java Servlet thuần được không ạ?", "suggestion": "Keywords: Dependency Injection, Inversion of Control, Convention over Configuration, Microservices, Reactive Programming\n\nStructure:\n*   Bước 1: Nêu bật Spring Boot''s auto-configuration và starter dependencies giúp giảm boilerplate code.\n*   Bước 2: Giải thích Dependency Injection (DI) và Inversion of Control (IoC) là nền tảng của Spring Boot, giúp tăng tính linh hoạt và khả năng kiểm thử.\n*   Bước 3: So sánh với Java Servlet thuần về thời gian phát triển, độ phức tạp, và khả năng mở rộng.\n*   Bước 4: Đề cập đến các use case phù hợp với Spring Boot (ví dụ: Microservices) và các framework khác (ví dụ: Quarkus cho serverless).\n\nSenior Tip: Phân tích trade-off giữa tốc độ phát triển (Spring Boot) và hiệu năng (Quarkus/Micronaut) trong bối cảnh cụ thể của dự án.", "questionText": "Cảm ơn bạn đã chia sẻ những suy nghĩ của mình. Có vẻ bạn đã có những cân nhắc thực tế về hiệu năng. Bây giờ chúng ta sẽ chuyển sang một khía cạnh khác của dự án nhé. Bạn đã sử dụng Spring Boot trong dự án này. Bạn có thể giải thích tại sao bạn chọn Spring Boot thay vì các framework khác không?", "questionType": "BLUEPRINT", "questionOrder": 4, "behavioralWarnings": []}, {"score": null, "feedback": null, "answerText": "Dạ em cũng không rõ nữa, chắc là tốn thời gian hơn nhiều ạ", "suggestion": null, "questionText": "Chào bạn, việc lựa chọn framework dựa trên sự phổ biến và dễ tìm tài liệu là một cách tiếp cận hợp lý khi bắt đầu. Spring Boot nổi bật ở khả năng tự động cấu hình (auto-configuration) và tích hợp nhiều thư viện hỗ trợ, giúp giảm thiểu boilerplate code và tăng tốc độ phát triển. Bạn có thể thử so sánh Spring Boot với Java Servlet thuần bằng cách nghĩ xem, nếu bạn phải tự cấu hình mọi thứ từ đầu (ví dụ: mapping request, quản lý transaction) thì sẽ mất bao nhiêu thời gian và công sức?", "questionType": "FOLLOW_UP", "questionOrder": 5, "behavioralWarnings": []}, {"score": null, "feedback": null, "answerText": "Dạ thú thật là về phần auto-configuration với starter thì em cũng chỉ mới dừng lại ở mức biết dùng thôi ạ. Em cứ thấy trong file pom.xml có sẵn các starter-web hay starter-data-jpa rồi em cứ thế mà code theo các bài hướng dẫn trên mạng thôi, chứ chưa thực sự hiểu sâu bên dưới nó tự cấu hình cái gì ạ. Em nghĩ là dùng Framework thì mình cứ tận dụng những cái nó có sẵn cho nhanh thôi ạ.", "suggestion": null, "questionText": "Bạn đã nhận ra đúng, việc tự cấu hình mọi thứ từ đầu sẽ tốn rất nhiều thời gian và công sức. Vậy theo bạn, Spring Boot giúp chúng ta giải quyết vấn đề đó như thế nào? Hãy tập trung vào những tính năng chính như auto-configuration và starter dependencies nhé.", "questionType": "FOLLOW_UP", "questionOrder": 6, "behavioralWarnings": []}, {"score": 6.5, "feedback": "Câu trả lời chưa đủ chi tiết về cách @Transactional hoạt động dưới lớp trừu tượng, và thiếu các kỹ thuật tối ưu khác.", "answerText": "em dùng ACID", "suggestion": "Keywords: Transaction Isolation Levels, Deadlock, Indexing, Execution Plan, Constraint\n\nStructure:\n*   **ACID Properties & @Transactional:** Explain how @Transactional maps to each ACID property (Atomicity, Consistency, Isolation, Durability).\n*   **Isolation Levels:** Discuss the isolation level used (e.g., READ COMMITTED, REPEATABLE READ) and its implications.\n*   **Constraint Usage:** Detail how constraints (e.g., foreign keys, unique constraints, check constraints) enforce data integrity.\n*   **Error Handling & Rollback:** Elaborate on the rollback mechanism and potential error scenarios.\n\nSenior Tip: Consider discussing how you would monitor and optimize transaction performance, including identifying and resolving potential deadlocks or performance bottlenecks using Execution Plan analysis.", "questionText": "Cảm ơn bạn đã chia sẻ. Việc tận dụng các tính năng có sẵn của framework là một cách tiếp cận thông minh để tăng tốc độ phát triển. Bây giờ chúng ta sẽ chuyển sang một khía cạnh khác của dự án nhé. Bạn đã sử dụng SQL Server trong dự án này. Bạn có thể cho biết bạn đã sử dụng những tính năng nào của SQL Server để đảm bảo tính toàn vẹn dữ liệu?", "questionType": "BLUEPRINT", "questionOrder": 7, "behavioralWarnings": []}, {"score": null, "feedback": null, "answerText": "em đánh cái @Transactional vô ở mỗi giao dịch á, để nếu có fail bước nào thì nó tự rollback sạch lại", "suggestion": null, "questionText": "Bạn nhắc đến ACID, đó là một khởi đầu tốt. Bạn có thể giải thích chi tiết hơn về từng thuộc tính của ACID (Atomicity, Consistency, Isolation, Durability) và cho ví dụ cụ thể về cách bạn đã sử dụng chúng trong dự án này để đảm bảo tính toàn vẹn dữ liệu không?", "questionType": "FOLLOW_UP", "questionOrder": 8, "behavioralWarnings": []}, {"score": null, "feedback": null, "answerText": "nó gắn 1 cái session vô cho cái commit đó, nó chỉ đóng commit khi tất cả các table đều update xong sucess và ko có lỗi, chỉ cần có 1 lỗi ở bảng nào thuộc cái transactional đó thì nó se tự động rollback hết tất cả các bản đã ghi xong, giúp dataabse luôn đảm bảo tính toạn vèn của dữ liệu", "suggestion": null, "questionText": "Việc sử dụng @Transactional là một cách tiếp cận đúng đắn. Tuy nhiên, bạn có thể giải thích rõ hơn về cách @Transactional đảm bảo các thuộc tính của ACID (Atomicity, Consistency, Isolation, Durability) trong giao dịch của bạn không? Ví dụ, nếu một giao dịch cập nhật nhiều bảng, @Transactional sẽ đảm bảo tính nhất quán (Consistency) như thế nào?", "questionType": "FOLLOW_UP", "questionOrder": 9, "behavioralWarnings": []}, {"score": 3.0, "feedback": "Ứng viên hoàn toàn bị động, chưa thể hiện bất kỳ hiểu biết nào về Inheritance.", "answerText": "khó quá, anh giải thích giúp em được ko", "suggestion": "Keywords: Polymorphism, Abstraction, Encapsulation, IS-A relationship, Code Reusability\nStructure:\n- Bước 1: Define Inheritance - Explain the concept of a child class inheriting properties and methods from a parent class.\n- Bước 2: Provide a Concrete Example - Use a clear example (e.g., Vehicle -> Car, Truck) and explain the attributes and methods.\n- Bước 3: Discuss Benefits - Highlight code reusability, maintainability, and extensibility.\n- Bước 4: Mention Types - Briefly touch upon single, multi-level, and hierarchical inheritance.\nSenior Tip: Discuss the potential drawbacks of deep inheritance hierarchies and when composition might be a better alternative.", "questionText": "Cảm ơn bạn, phần giải thích về cách @Transactional đảm bảo tính toàn vẹn dữ liệu rất rõ ràng. Bây giờ chúng ta sẽ chuyển sang một chủ đề khác trong Java nhé. Bạn hiểu như thế nào về khái niệm ''kế thừa'' (Inheritance)? Hãy cho một ví dụ đơn giản.", "questionType": "BLUEPRINT", "questionOrder": 10, "behavioralWarnings": []}, {"score": null, "feedback": null, "answerText": "khó quá em ko hiểu", "suggestion": null, "questionText": "Kế thừa là cơ chế cho phép một lớp (class) kế thừa các thuộc tính và phương thức từ một lớp khác (lớp cha). Ví dụ, bạn có thể tạo một lớp ''ĐộngVật'' với các thuộc tính như ''tên'', ''tuổi'', và phương thức ''ăn()''. Sau đó, bạn có thể tạo một lớp ''Chó'' kế thừa từ ''ĐộngVật'', lớp ''Chó'' sẽ tự động có các thuộc tính và phương thức của ''ĐộngVật'', và bạn có thể thêm các thuộc tính và phương thức riêng cho ''Chó'' như ''giống''. Bạn có thể thử giải thích lại kế thừa bằng ví dụ tương tự không?", "questionType": "FOLLOW_UP", "questionOrder": 11, "behavioralWarnings": []}, {"score": null, "feedback": null, "answerText": "em vẫn ko hiểu", "suggestion": null, "questionText": "Kế thừa đơn giản là việc một lớp con (child class) thừa hưởng các đặc điểm của lớp cha (parent class). Hãy nghĩ về việc bạn có một khuôn mẫu chung cho ''Xe'', và sau đó tạo ra các loại xe cụ thể như ''XeTải'' và ''XeDuLịch'' dựa trên khuôn mẫu đó. Bạn có thể cho biết lớp ''Xe'' sẽ có những thuộc tính gì không?", "questionType": "FOLLOW_UP", "questionOrder": 12, "behavioralWarnings": []}, {"score": 2.0, "feedback": "Câu trả lời quá sơ sài, thể hiện sự thiếu hiểu biết cơ bản về Java.", "answerText": "em ko biết luôn", "suggestion": "Keywords: `==`, `.equals()`, Object, Memory Address, Contract\n\nStructure:\n* Bước 1: Giải thích `==` so sánh gì (reference/memory address).\n* Bước 2: Giải thích `.equals()` so sánh gì (object content/value).\n* Bước 3: Nêu rõ `equals()` có thể được override, còn `==` thì không.\n* Bước 4: Đề cập đến contract của việc override `equals()` (transitive, symmetric, consistent).\n\nSenior Tip: Thảo luận về performance implications của việc sử dụng `==` vs `.equals()` và khi nào nên sử dụng cái nào.", "questionText": "Cảm ơn bạn đã cố gắng. Có vẻ như bạn đang gặp khó khăn với khái niệm kế thừa. Chúng ta sẽ chuyển sang một chủ đề khác nhé. Bạn có thể giải thích sự khác biệt giữa `==` và `.equals()` trong Java không?", "questionType": "BLUEPRINT", "questionOrder": 13, "behavioralWarnings": []}, {"score": 5.0, "feedback": "Câu trả lời còn quá sơ sài, thiếu tính hệ thống và độ sâu về kiến thức kiểu dữ liệu trong Java.", "answerText": "nguyên thủy và tham chiếu", "suggestion": "Keywords: Primitive Data Types, Wrapper Classes, Memory Allocation, Data Range, Type Conversion\n\nStructure:\n*   List all 8 primitive data types in Java (byte, short, int, long, float, double, boolean, char).\n*   For each type, specify its size in bytes and the range of values it can store.\n*   Briefly explain the difference between primitive types and reference types.\n*   Mention the concept of Wrapper Classes (Integer, Float, Boolean, Character, etc.) and their purpose.\n\nSenior Tip: Discuss potential performance implications when choosing between different primitive data types, especially in memory-intensive applications.", "questionText": "Cảm ơn bạn đã chia sẻ. Có vẻ như bạn cần thêm thời gian để làm quen với các khái niệm cơ bản của Java. Chúng ta sẽ chuyển sang một câu hỏi khác nhé. Bạn biết những kiểu dữ liệu cơ bản nào trong Java? Hãy kể tên và mô tả ngắn gọn.", "questionType": "BLUEPRINT", "questionOrder": 14, "behavioralWarnings": []}, {"score": null, "feedback": null, "answerText": "int số nguyên, float số thực boolean true false", "suggestion": null, "questionText": "Bạn đã đề cập đến kiểu dữ liệu nguyên thủy và tham chiếu. Bạn có thể kể tên một vài kiểu dữ liệu nguyên thủy cụ thể trong Java không? Ví dụ như int, float, boolean,... và mô tả ngắn gọn về cách chúng được sử dụng?", "questionType": "FOLLOW_UP", "questionOrder": 15, "behavioralWarnings": []}, {"score": null, "feedback": null, "answerText": "char nữa", "suggestion": null, "questionText": "Bạn đã liệt kê một vài kiểu dữ liệu nguyên thủy đúng. Ngoài int, float và boolean, còn những kiểu dữ liệu nguyên thủy nào khác trong Java nữa không? Bạn có thể cho biết kích thước (số byte) của mỗi kiểu dữ liệu đó là bao nhiêu không?", "questionType": "FOLLOW_UP", "questionOrder": 16, "behavioralWarnings": []}, {"score": 4.0, "feedback": "Câu trả lời thiếu kiến thức nền tảng về xử lý exception trong Java, quá tập trung vào một thư viện cụ thể.", "answerText": "ko biết bình thường em dùng sneakythrow của lombok cho clean code", "suggestion": "Keywords: Exception Hierarchy, Try-Catch Block, Checked vs. Unchecked Exceptions, Exception Propagation, Error Handling Strategy\n\nStructure:\n*   Explain the Java Exception Hierarchy (Throwable, Exception, RuntimeException).\n*   Describe the use of `try-catch` blocks for handling specific exceptions.\n*   Explain the `throws` keyword for propagating exceptions to the calling method.\n*   Discuss the difference between checked and unchecked exceptions and when to use each.\n*   Briefly mention the concept of custom exceptions.\n\nSenior Tip: Discuss the trade-offs between catching specific exceptions vs. catching a more general exception type, and the importance of logging exceptions for debugging and monitoring.", "questionText": "Cảm ơn bạn, bạn đã liệt kê được một vài kiểu dữ liệu nguyên thủy cơ bản. Bây giờ chúng ta sẽ chuyển sang một chủ đề khác. Bạn có thể cho biết một vài cách để xử lý ngoại lệ (Exception) trong Java không?", "questionType": "BLUEPRINT", "questionOrder": 17, "behavioralWarnings": []}, {"score": null, "feedback": null, "answerText": "ko biết cứ sneakythrow rồi global exception handler ở ngoài cùng thôi để nó tự bắt lỗi cho mình", "suggestion": null, "questionText": "SneakyThrow là một cách tiếp cận khá thú vị để làm code sạch hơn. Tuy nhiên, nó chỉ là một giải pháp cụ thể. Bạn có thể cho biết các cách xử lý exception phổ biến hơn trong Java, ví dụ như sử dụng `try-catch` hoặc `throws` không?", "questionType": "FOLLOW_UP", "questionOrder": 18, "behavioralWarnings": []}, {"score": null, "feedback": null, "answerText": "hạn chế là quá đẹp trai", "suggestion": null, "questionText": "Bạn nói sử dụng `sneakythrow` và `global exception handler`. Vậy bạn có thể giải thích ngắn gọn về cách thức hoạt động của `global exception handler` này không? Nó sẽ bắt các exception như thế nào và có những hạn chế gì?", "questionType": "FOLLOW_UP", "questionOrder": 19, "behavioralWarnings": []}], "improvementPlan": null, "aiOverviewFeedback": "Đã chấm điểm xong."}', '{"domain": "IT", "language": "VI", "difficulty": "FRESHER_BASIC", "interview_mode": "STANDARD_MOCK", "duration_minutes": 15}', null),
        (18, null, 8, null, '2026-04-14 02:58:41.141476', '2026-04-15 13:17:46.184652', 'IT', 'CANCELLED', 'STANDARD_MOCK', null, '4aa57afa-ff05-4ea0-acfa-e8a5c78549a7', null, '{"id": 5, "user": {"id": 8, "name": "Nguyễn Văn A", "role": "USER", "cvUrl": "https://res.cloudinary.com/dimvyno0z/image/upload/v1775654226/my_app/docs/36c87fe5-e72a-49d1-ac92-7848c99a8101.pdf", "email": "a@gmail.com", "isActive": true, "password": "12345", "avatarUrl": "https://res.cloudinary.com/dimvyno0z/image/upload/v1772823543/my_app/images/blo6nm4yd92pacugomsk.jpg", "public_id": "my_app/images/blo6nm4yd92pacugomsk", "university": "FPT", "cv_public_id": "my_app/docs/36c87fe5-e72a-49d1-ac92-7848c99a8101"}, "tools": ["Git/GitHub/GitLab", "Maven", "Jira", "Swagger", "Postman", "Tomcat"], "projects": [{"name": "Movie Theater", "role": "Leader, Back-end", "outcome": null, "teamSize": 5, "usedTools": ["ASP.NET Core", "ASP.NET MVC", "PostgreSQL"], "description": "Phát triển hệ thống đặt vé xem phim trực tuyến có hiển thị sơ đồ ghế theo thời gian thực. Tích hợp các module: quản lý phim, suất chiếu, phòng chiếu, khuyến mãi, và tài khoản người dùng, tích điểm. Hỗ trợ phân quyền người dùng (khách hàng, nhân viên, quản trị)."}, {"name": "CHILD VACCINE SCHEDULE TRACKING SYSTEM", "role": "Leader, Back-end", "outcome": null, "teamSize": 3, "usedTools": ["Spring Boot", "React Js", "SQL Server"], "description": "Đặt lịch tiêm chủng, thanh toán, đánh giá, cập nhật phản ứng sau tiêm. Theo dõi quá trình tiêm & lịch sử tiêm chủng. Cơ sở ghi nhận kết quả tiêm chủng vào hồ sơ của trẻ. Dashboard & Report. Hệ thống tự gửi mail nhắc nhở, thông báo. Quản lí vaccine trong kho, người dùng, lịch đặt,..."}, {"name": "SMART WALLET", "role": "Leader, Back-end", "outcome": null, "teamSize": 3, "usedTools": ["Spring Boot", "React", "SQL Server"], "description": "Quản lí thu, chi, giúp người dùng theo dõi thu, chi và tiêu dùng cho hợp lí. Cho phép người dùng phân loại thu, chi. Cho phép người dùng tạo ngân sách và theo dõi thu chi theo ngân sách. Trang chủ hiện trực quan, dễ quan sát."}, {"name": "PRODUCT INFORMATION", "role": null, "outcome": null, "teamSize": null, "usedTools": ["MVC", "JSP", "tomcat", "session", "lterchain", "JDBC", "cookie"], "description": "Quản lý các sản phẩm theo phân loại. Thêm sản phầm yêu thích. CRUD cơ bản. Đăng nhập."}], "createdAt": [2026, 4, 8, 13, 17, 3, 1543000], "updatedAt": [2026, 4, 8, 13, 17, 3, 1609000], "educations": [{"gpa": "3.2", "major": "Kỹ thuật phần mềm", "degree": null, "school": "Đại học FPT", "end_date": "dự kiến tốt nghiệp 2026", "start_date": "2022"}], "softSkills": ["Teamwork", "English (Khá - đọc hiểu tài liệu)", "Presentation", "Problem Solving", "Self-learning", "Project Management"], "targetRole": "Java Backend Developer", "targetLevel": "Junior", "achievements": ["Sinh viên giỏi (Kì 1,3,4,5)"], "introduction": "Là một lập trình viên với nền tảng ngôn ngữ Java, tôi mong muốn tìm kiếm một môi trường lý tưởng để phát triển năng lực bản thân. Tôi sẽ vận dụng tư duy logic và niềm đam mê sẵn có để nhanh chóng chuyển hóa kiến thức thành kỹ năng thực tế. Mục tiêu của tôi là tích lũy kinh nghiệm có giá trị qua từng dự án, không ngừng tiến bộ để trở thành một chuyên viên phát triển phần mềm vững vàng và hiệu quả.", "certifications": ["Web Design for Everybody: Basics of Web Development & Coding - Coursera", "Software Development Lifecycle - Coursera", "Java FullStack Developer - Coursera"], "technicalSkills": ["Java", "C#", "HTML/CSS", "ASP.NET Core", "ASP.NET MVC", "PostgreSQL", "Spring Boot", "React Js", "SQL Server", "Spring Security", "Spring Data JPA", "Spring MVC", "Validation", "DI/IoC", "JPA/Hibernate", "MVC", "JSP", "JDBC"], "workExperiences": [{"company": "FPT Software Academy", "end_date": "8-2025", "position": "THỰC TẬP SINH .NET", "start_date": "5-2025", "description": "Java Developer"}]}', '{"basic_info": {"job_title": "Backend Developer", "industry_domain": "Information Technology", "seniority_level": "Senior"}, "competencies": {"hard_skills": ["Java", "Java EE", "Hibernate", "Spring MVC", "Spring Boot", "Oracle", "PostgreSQL", "store procedure", "view", "index"], "soft_skills": [], "tools_and_platforms": ["Docker", "Message Queue"]}, "responsibilities": ["Tham gia vào quá trình phân tích, thiết kế và xây dựng hệ thống thông tin in-house.", "Đảm bảo tất cả tài liệu đặc tả kỹ thuật TS, unit test, script tuân thủ quy tắc.", "Xây dựng hệ thống thông tin in-house.", "Điều tra (debug) và giải quyết các lỗi phát sinh trong quá trình vận hành hệ thống.", "Làm việc onsite: Phú Mỹ Hưng Tower, quận 7, HCM."]}', null, '{"domain": "IT", "language": "VI", "difficulty": "FRESHER_BASIC", "interview_mode": "STANDARD_MOCK", "duration_minutes": 15}', null),
        (35, null, 5, null, '2026-04-19 13:13:09.745868', '2026-04-19 22:24:26.359379', 'IT', 'CANCELLED', 'STANDARD_MOCK', null, '982eb69a-8c8d-4807-88fd-7ab9a2d5c48b', null, '{"id": 6, "user": {"id": 5, "name": "Trần Bình An", "role": "USER", "cvUrl": "https://res.cloudinary.com/dimvyno0z/image/upload/v1775745501/my_app/docs/5cbc1648-7684-468b-a546-3719047a22bc.pdf", "email": "binhan@gmail.com", "major": "CNTT", "isActive": true, "password": "123", "avatarUrl": "https://res.cloudinary.com/dimvyno0z/image/upload/v1773564900/my_app/images/koljabyfgesxt5ptp8u5.jpg", "public_id": "my_app/images/koljabyfgesxt5ptp8u5", "university": "ĐH Bách Khoa TPHCM", "cv_public_id": "my_app/docs/5cbc1648-7684-468b-a546-3719047a22bc"}, "tools": ["Git/GitHub/GitLab", "Maven", "Jira", "Swagger", "Docker", "Postman", "JUnit", "xUnit", "Cloudinary", "Firebase Cloud Messaging"], "projects": [{"name": "CHILD VACCINE SCHEDULE TRACKING SYSTEM", "role": "Back-end, Leader", "outcome": "Schedule vaccination, payment, evaluation, update post-vaccination reactions. Track vaccination progress & vaccination history. The facility records vaccination results in the child''s records. The system automatically sends reminder and notification emails. Manage vaccines in stock, users, booking schedules, ...", "teamSize": 3, "usedTools": ["Java", "Spring Boot", "Spring Security", "Spring AI", "MSSQL", "Spring Mail"], "description": "A web application that manages children''s vaccination schedules, allowing parents and health centers to schedule, track, and update vaccination records. Supports individual/group scheduling, automatic reminders, secure payments, and AI-powered customer support."}, {"name": "BAMBI KITCHEN", "role": "Back-end, Leader", "outcome": "Authorization & Authentication ( JW, OAuth2 Google ). Manage menus & recipes. Raw material warehouse management (Inventory, Import/Export, Warning). Order (Custom dishes & available dishes) with ingredient reservation system. Multi-channel payment (Cash, Momo, VNPAY). AI intergration ( Gemini AI - Nutrition & Recommend ).", "teamSize": 6, "usedTools": ["Spring Boot", "Spring Security", "Spring AI", "MSSQL", "Cloudinary", "Firebase Cloud Messaging", "Spring Mail"], "description": "Bambi kitchen is a food chain that specializes in providing healthy dishes and customers can customize and choose personalized dish ingredients step by step, with integrated AI to evaluate orders."}], "createdAt": [2026, 4, 9, 14, 38, 18, 734762000], "updatedAt": [2026, 4, 9, 14, 38, 22, 582891000], "educations": [{"gpa": "3.2", "major": "Software Engineering", "degree": null, "school": "FPT University", "end_date": "2026", "start_date": "2022"}], "softSkills": ["Teamwork", "English", "Fast learner", "Adaptability", "Problem-solving", "Technical Reading"], "targetRole": "Java Developer", "targetLevel": "Junior", "achievements": ["HONORABLE STUDENT OF TRIMESTER Semester 1, 3, 4, 5", "Admissions Collaborator -FPT University"], "introduction": "As a Java Developer, I am eager to work in a challenging environment to develop my skills and gain practical experience. I leverage my logical thinking and passion for programming to quickly transform knowledge into practical solutions, aiming to become an effective and well-grounded software development specialist.", "certifications": ["Web Design for Everybody: Basics of Web Development & Coding", "Software Development Lifecycle", "Java FullStack Developer"], "technicalSkills": ["Java", "C#", "HTML/CSS", "Spring Security", "Spring Data JPA", "Spring MVC", "MSSQL", "PostgreSQL", "JPA/Hibernate", "MongoDB", "ASP .NET", "SignalR", "Spring Boot", "Spring AI"], "workExperiences": [{"company": "FPT Software Academy", "end_date": "08/2025", "position": ".NET Developer Intern", "start_date": "05/2025", "description": "Final Training Project: Movie Theater. Role: Back-end, Leader. Developed an online movie ticketing system featuring real-time seat map visualization. Developed modules: movie management, showtimes, theaters, promotions, user accounts, and points accumulation. Authorization & Authentication (Cookie Authentication). Designed the entire database and processing flow architecture for the modules. Actively learned and mastered all modules, acted as a connection point between sections, divided tasks and guided the team to implement code according to the design. Performed work under the supervision of the mentor, ensuring project progress and quality."}]}', '{"basic_info": {"job_title": "Java Backend Developer", "industry_domain": "Công nghệ thông tin", "seniority_level": "Junior"}, "competencies": {"hard_skills": ["Java", "Spring Boot", "REST API", "SQL"], "soft_skills": ["Tư duy giải quyết vấn đề", "Làm việc nhóm"], "tools_and_platforms": ["Git"]}, "responsibilities": []}', null, '{"domain": "IT", "language": "VI", "difficulty": "FRESHER_BASIC", "interview_mode": "STANDARD_MOCK", "duration_minutes": 30}', null),
        (13, null, 2, null, '2026-03-26 14:33:47.772495', '2026-04-14 03:03:18.489246', 'IT', 'CANCELLED', 'STANDARD_MOCK', null, 'fcad53ad-cbb0-45f2-b2ce-e24987093e62', null, '{"id": 1, "user": {"id": 2, "name": "THU HA NGUYEN PHAM", "role": "USER", "cvUrl": "https://res.cloudinary.com/dimvyno0z/image/upload/v1774535288/my_app/docs/e117e3a8-f539-4746-bb01-17729f031d61.pdf", "email": null, "major": "CNTT", "isActive": true, "password": null, "avatarUrl": "https://res.cloudinary.com/dimvyno0z/image/upload/v1772820944/my_app/images/t6hzjlhcmuj8sq7drhm4.png", "public_id": "my_app/images/t6hzjlhcmuj8sq7drhm4", "university": "fpt", "cv_public_id": "my_app/docs/e117e3a8-f539-4746-bb01-17729f031d61"}, "tools": ["Git/GitHub/GitLab", "Maven", "Jira", "Swagger", "Postman", "Tomcat"], "projects": [{"name": "Movie Theater", "role": "Leader, Back-end", "outcome": null, "teamSize": 5, "usedTools": ["ASP.NET Core", "ASP.NET MVC", "PostgreSQL"], "description": "Phát triển hệ thống đặt vé xem phim trực tuyến có hiển thị sơ đồ ghế theo thời gian thực. Tích hợp các module: quản lý phim, suất chiếu, phòng chiếu, khuyến mãi, và tài khoản người dùng, tích điểm. Hỗ trợ phân quyền người dùng (khách hàng, nhân viên, quản trị)."}, {"name": "CHILD VACCINE SCHEDULE TRACKING SYSTEM", "role": "Leader, Back-end", "outcome": null, "teamSize": 3, "usedTools": ["Spring Boot", "React Js", "SQL Server"], "description": "Đặt lịch tiêm chủng, thanh toán, đánh giá, cập nhật phản ứng sau tiêm. Theo dõi quá trình tiêm & lịch sử tiêm chủng. Cơ sở ghi nhận kết quả tiêm chủng vào hồ sơ của trẻ. Dashboard & Report. Hệ thống tự gửi mail nhắc nhở, thông báo. Quản lí vaccine trong kho, người dùng, lịch đặt,..."}, {"name": "SMART WALLET", "role": "Leader, Back-end", "outcome": null, "teamSize": 3, "usedTools": ["Spring Boot", "React", "SQL Server"], "description": "Quản lí thu, chi, giúp người dùng theo dõi thu, chi và tiêu dùng cho hợp lí. Cho phép người dùng phân loại thu, chi. Cho phép người dùng tạo ngân sách và theo dõi thu chi theo ngân sách. Trang chủ hiện trực quan, dễ quan sát."}, {"name": "PRODUCT INFORMATION", "role": null, "outcome": null, "teamSize": null, "usedTools": ["MVC", "JSP", "tomcat", "session", "lterchain", "JDBC", "cookie"], "description": "Quản lý các sản phẩm theo phân loại. Thêm sản phầm yêu thích. CRUD cơ bản. Đăng nhập."}], "createdAt": [2026, 3, 6, 18, 29, 27, 730816000], "updatedAt": [2026, 3, 26, 14, 29, 54, 560768000], "educations": [{"gpa": "3.2", "major": "Kỹ thuật phần mềm", "degree": null, "school": "Đại học FPT", "end_date": "dự kiến tốt nghiệp 2026", "start_date": "2022"}], "softSkills": ["Teamwork", "English (Khá - đọc hiểu tài liệu)", "Presentation", "Problem Solving", "Self-learning", "Project Management"], "targetRole": "Java Backend Developer", "targetLevel": "Junior", "achievements": ["Sinh viên giỏi (Kì 1,3,4,5)"], "introduction": "Là một lập trình viên với nền tảng ngôn ngữ Java, tôi mong muốn tìm kiếm một môi trường lý tưởng để phát triển năng lực bản thân. Tôi sẽ vận dụng tư duy logic và niềm đam mê sẵn có để nhanh chóng chuyển hóa kiến thức thành kỹ năng thực tế. Mục tiêu của tôi là tích lũy kinh nghiệm có giá trị qua từng dự án, không ngừng tiến bộ để trở thành một chuyên viên phát triển phần mềm vững vàng và hiệu quả.", "certifications": ["Web Design for Everybody: Basics of Web Development & Coding - Coursera", "Software Development Lifecycle - Coursera", "Java FullStack Developer - Coursera"], "technicalSkills": ["Java", "C#", "HTML/CSS", "ASP.NET Core", "ASP.NET MVC", "PostgreSQL", "Spring Boot", "React Js", "SQL Server", "Spring Security", "Spring Data JPA", "Spring MVC", "Validation", "DI/IoC", "JPA/Hibernate", "MVC", "JSP"], "workExperiences": [{"company": "FPT Software Academy", "end_date": "8-2025", "position": "THỰC TẬP SINH .NET", "start_date": "5-2025", "description": "Java Developer"}]}', '{"basic_info": {"job_title": "Backend Engineer", "industry_domain": "Software/SaaS", "seniority_level": "Senior"}, "competencies": {"hard_skills": ["Java development", "System design", "SQL", "Data structures", "Algorithms", "Design patterns", "Functional design"], "soft_skills": ["Communication skills", "Problem-solving", "Team spirit", "Logical thinking", "Self-motivated", "Responsibility", "Comprehension"], "tools_and_platforms": ["SpringMVC", "Spring Boot", "Tomcat", "Maven", "MySQL", "PostgreSQL", "Memcached", "Redis", "Linux", "Nginx", "AWS", "Kafka", "Fabio", "Consul"]}, "responsibilities": ["Design and development of backend service systems.", "Analyze business requirements and design system interfaces.", "Develop, code, and test backend system modules.", "Refactor and optimize system architecture and performance."]}', null, '{"domain": "IT", "language": "VI", "difficulty": "FRESHER_BASIC", "interview_mode": "STANDARD_MOCK", "duration_minutes": 15}', null),
        (90, 2.611111111111111, 9, '2026-08-07 10:53:26.510347', '2026-08-07 10:10:00.545198', '2026-08-07 10:53:26.520761', 'IT', 'COMPLETED', 'STANDARD_MOCK', 'REJECT', 'f7d64570-4620-4732-b233-1b33511869b6', '{"blueprint": [{"questions": [{"order": 1, "rag_keyword": null, "question_text": "Chào bạn, mình đã xem qua CV rất ấn tượng của bạn với nhiều dự án thực tế. Trước khi bắt đầu đi sâu vào chuyên môn, bạn hãy giới thiệu ngắn gọn về bản thân và những công nghệ Backend mà bạn tự tin nhất hiện nay nhé?", "question_type": "CORE"}], "phase_name": "Giới thiệu & Khởi động", "duration_minutes": 1}, {"questions": [{"order": 2, "rag_keyword": null, "question_text": "Trong dự án ''Bambi Kitchen'', mình thấy bạn có tích hợp JWT và OAuth2 để xác thực. Bạn có thể giải thích quy trình khi một user đăng nhập và nhận được Token để truy cập các tài nguyên bảo mật không?", "question_type": "CORE"}, {"order": 3, "rag_keyword": null, "question_text": "Với dự án ''Movie Theater'', bạn đóng vai trò Leader và dùng SignalR để làm Seat Map thời gian thực. Thách thức lớn nhất khi quản lý trạng thái ghế ngồi để tránh việc hai người cùng đặt một lúc là gì?", "question_type": "FOLLOW_UP"}, {"order": 4, "rag_keyword": null, "question_text": "Tại dự án ''Child Vaccine Schedule'', bạn có sử dụng Spring AI. Bạn đã áp dụng AI vào những tính năng cụ thể nào để hỗ trợ người dùng?", "question_type": "CORE"}], "phase_name": "Project Deep-dive", "duration_minutes": 8}, {"questions": [{"order": 5, "rag_keyword": "java_oop_interface_vs_abstract_class", "question_text": "Vì bạn ứng tuyển vị trí Java Backend, bạn hãy cho biết sự khác biệt cơ bản giữa ''Interface'' và ''Abstract Class'' trong lập trình hướng đối tượng là gì?", "question_type": "CORE"}, {"order": 6, "rag_keyword": "spring_boot_dependency_injection_autowired", "question_text": "Trong Spring Data JPA mà bạn đã dùng, Annotation @Autowired dùng để làm gì và tại sao chúng ta cần Dependency Injection (DI)?", "question_type": "CORE"}, {"order": 7, "rag_keyword": "rest_api_http_methods_basics", "question_text": "JD của chúng mình yêu cầu xây dựng RESTful APIs. Bạn hãy liệt kê các HTTP Methods phổ biến (như GET, POST, PUT, DELETE) và mục đích sử dụng của từng loại được không?", "question_type": "CORE"}, {"order": 8, "rag_keyword": "db_indexing_fundamentals", "question_text": "Để tối ưu hóa truy vấn Database như trong mô tả công việc, theo bạn việc tạo ''Index'' (chỉ mục) trong MSSQL hay PostgreSQL có tác dụng gì và nó có nhược điểm nào không?", "question_type": "CORE"}, {"order": 9, "rag_keyword": "microservices_vs_monolith_basics", "question_text": "Một câu hỏi nhỏ về Microservices (có trong JD): Bạn hiểu thế nào là kiến trúc Microservices và nó khác gì so với kiến trúc Monolith (nguyên khối)?", "question_type": "FOLLOW_UP"}], "phase_name": "Technical Core (Java & Backend)", "duration_minutes": 11}], "strategy_analysis": "Chiến thuật STANDARD_MOCK cho ứng viên Intern lên Junior. Tập trung 5% chào hỏi, 40% khai thác sâu vai trò Leader trong 3 dự án đa dạng công nghệ (Java, .NET, AI) và 50% kiểm tra kiến thức nền tảng (Technical Core) theo JD về REST API, Database và Java OOP ở mức độ cơ bản (FRESHER_BASIC)."}', '{"id": 24, "tools": ["Git", "GitHub", "GitLab", "Maven", "Jira", "Swagger", "Docker", "Postman", "JUnit", "xUnit"], "projects": [{"name": "Movie Theater", "role": "Back-end, Leader", "outcome": "Final score: 9.7", "teamSize": 5, "usedTools": ["ASP.NET Core", "ASP.NET MVC", "PostgreSQL", "SignalR", "GitHub"], "description": "An online movie ticketing system featuring real-time seat map visualization and modules for movie, showtimes, theaters, promotions, and user accounts."}, {"name": "CHILD VACCINE SCHEDULE TRACKING SYSTEM", "role": "Back-end, Leader", "outcome": "Supports individual/group scheduling, automatic reminders, secure payments, and AI-powered customer support.", "teamSize": 3, "usedTools": ["Java", "Spring Boot", "Spring Security", "Spring AI", "MSSQL", "Spring Mail"], "description": "A web application that manages children''s vaccination schedules, allowing parents and health centers to schedule, track, and update vaccination records."}, {"name": "BAMBI KITCHEN", "role": "Back-end, Leader", "outcome": "Implemented JWT/OAuth2 authentication, warehouse management, multi-channel payment (Cash, Momo, VNPAY) and AI integration via Gemini AI.", "teamSize": 6, "usedTools": ["Spring Boot", "Spring Security", "Spring AI", "MSSQL", "Cloudinary", "Firebase Cloud Messaging", "Spring Mail"], "description": "A healthy food chain application where customers can customize dish ingredients step by step with integrated AI for order evaluation."}], "createdAt": [2026, 8, 4, 16, 14, 33, 422891000], "updatedAt": [2026, 8, 4, 16, 14, 33, 422919000], "educations": [{"gpa": "3.2", "major": "Software Engineering", "degree": null, "school": "FPT University", "end_date": "2026", "start_date": "2022"}], "softSkills": ["Technical Reading Proficiency in English", "Fast learner", "adaptability", "problem-solving", "teamwork"], "targetRole": "Java Developer", "targetLevel": "Intern", "achievements": ["Honorable Student of Trimester (Semester 1, 3, 4, 5)", "Admissions Collaborator - FPT University"], "introduction": "As a Java Developer, I am eager to work in a challenging environment to develop my skills and gain practical experience. I leverage my logical thinking and passion for programming to quickly transform knowledge into practical solutions, aiming to become an effective and well-grounded software development specialist.", "applicationId": 115, "certifications": ["Web Design for Everybody: Basics of Web Development & Coding", "Software Development Lifecycle", "Java FullStack Developer"], "technicalSkills": ["Java", "C#", "HTML/CSS", "Spring Security", "Spring Data JPA", "Spring MVC", "Validation", "DI/IoC", "ASP .NET", "MSSQL", "PostgreSQL", "JPA/Hibernate", "MongoDB"], "workExperiences": [{"company": "FPT Software Academy", "end_date": "08/2025", "position": ".NET Developer Intern", "start_date": "05/2025", "description": "Worked as a Back-end Leader for the Movie Theater project. Developed an online movie ticketing system with real-time seat map visualization and various management modules. Designed database and processing flow architecture."}]}', '{"basic_info": {"job_title": "Junior Java Backend Developer", "industry_domain": "AI / Software Development", "seniority_level": "Junior"}, "competencies": {"hard_skills": ["Java", "Backend Development", "RESTful APIs", "Database queries optimization", "Microservices"], "soft_skills": ["Passionate"], "tools_and_platforms": []}, "responsibilities": ["Building scalable RESTful APIs", "Optimizing database queries", "Integrating microservices for an AI-driven platform"]}', '{"history": [{"score": 0.0, "feedback": "Diễn đạt hoàn toàn không rõ ràng, thiếu chuyên nghiệp và không cung cấp được thông tin kỹ thuật hữu ích.", "answerText": "Mình ờ ờ biết các công nghệ như nó create ra va bai thần và database thì bóp bóp mông vô đi.", "suggestion": "Keywords: Tech Stack, Scalability, Distributed Systems, High Availability.\n\nStructure:\n- Professional Intro: Họ tên, vai trò, số năm kinh nghiệm.\n- Core Tech Stack: Ngôn ngữ -> Framework -> Database/Cache/Message Broker.\n- Proven Impact: Nêu một thành tựu định lượng (ví dụ: Handle X requests/sec, reduce latency Y%).\n- Specialization: Lĩnh vực chuyên sâu (ví dụ: Microservices, Event-driven Architecture).\n\nSenior Tip: Đừng liệt kê công nghệ, hãy nói về lý do chọn công nghệ đó và trade-off đi kèm.", "questionText": "Chào bạn, mình đã xem qua CV rất ấn tượng của bạn với nhiều dự án thực tế. Trước khi bắt đầu đi sâu vào chuyên môn, bạn hãy giới thiệu ngắn gọn về bản thân và những công nghệ Backend mà bạn tự tin nhất hiện nay nhé?", "questionType": "BLUEPRINT", "questionOrder": 0, "behavioralWarnings": []}, {"score": null, "feedback": null, "answerText": "Mình tên là Nguyễn Ngọc tuấn. Mình cực kì nhông da va springwood nó chip. Not rip chứ không phải là. Not j hết ngôn ngữ lập trình node gyp và sriphum.", "suggestion": null, "questionText": "Có vẻ như bạn đang hơi căng thẳng hoặc gặp chút trục trặc trong việc diễn đạt. Đừng quá áp lực nhé, buổi phỏng vấn này là để chúng ta cùng trao đổi. Bạn hãy thử hít thở sâu và chia sẻ lại giúp mình: Bạn tên là gì và những ngôn ngữ hay framework Backend nào (ví dụ như Java, Spring Boot, Node.js, MySQL...) mà bạn tự tin nhất?", "questionType": "FOLLOW_UP", "questionOrder": 1, "behavioralWarnings": []}, {"score": 2.0, "feedback": "Thiếu hoàn toàn tư duy quy trình hệ thống và không mô tả được cơ chế xác thực phía Server.", "answerText": "Thì giúp tớ đăng nhập thành công rồi bằng form hoặc là o 2 phát hành zwt mang www.này đánh vào hết orient. Em dùng chiêu trò để va li đây trước khi cho phép truy cập tài nguyên bảo mật.", "suggestion": "Keywords: Authorization: Bearer, JWT Structure (Header/Payload/Signature), Refresh Token, RS256 (Asymmetric Encryption), CSRF vs XSS Trade-off.\n\nStructure:\n- Step 1: Authentication Flow (Client -> Auth Server -> Validation -> Token Generation).\n- Step 2: Token Issuance (Signing process using Secret/Private Key -> Return Access Token & Refresh Token).\n- Step 3: Resource Access (Client attaches token in Authorization Header -> Server validates Signature/Expiration/Claims).\n- Step 4: Token Lifecycle (Handling expiration via Refresh Token).\n\nSenior Tip: Phân tích sự đánh đổi giữa Stateless (JWT) và Stateful (Session) trong việc thu hồi token (Token Revocation) và chiến lược Token Rotation để tăng cường bảo mật.", "questionText": "Cảm ơn Tuấn đã chia sẻ, mình đã nắm được các công nghệ bạn tự tin là Java, Spring Boot và Node.js. Bây giờ chúng ta sẽ cùng đi sâu hơn vào chuyên môn thông qua các dự án bạn đã làm nhé. Trong dự án ''Bambi Kitchen'', mình thấy bạn có tích hợp JWT và OAuth2 để xác thực. Bạn có thể giải thích quy trình khi một user đăng nhập và nhận được Token để truy cập các tài nguyên bảo mật không?", "questionType": "BLUEPRINT", "questionOrder": 2, "behavioralWarnings": []}, {"score": null, "feedback": null, "answerText": "Nh đăng nhập. Providers bắt anh nhận được thông tin giúp cho từ veneers đắt để tạo kiểu đấy, giúp girl trong cuộc sống sau đó vẫn phát hành duy nhất tôi assetto phần giống hệt như trên và trả về cho file từ thời điểm này trở đi ra sự việc wp để gọi các giai đoạn hoàn toàn giống luồng thông thường.", "suggestion": null, "questionText": "Câu trả lời của bạn hiện tại hơi ngắn và chưa rõ ràng về mặt quy trình. Để mình hiểu rõ hơn, bạn có thể mô tả chi tiết từng bước được không? Ví dụ: Khi user gửi thông tin đăng nhập lên, Server sẽ xử lý ra sao, Token được tạo và trả về như thế nào, và sau đó Token đó được sử dụng như thế nào trong các request tiếp theo để truy cập tài nguyên bảo mật?", "questionType": "FOLLOW_UP", "questionOrder": 3, "behavioralWarnings": []}, {"score": null, "feedback": null, "answerText": "Sau khi goodger đăng nhập thành công và sẽ được trả về token phía thượng lưu token ở một trong các chính sau local store hoặc là session store luôn biến trong bộ nhớ để bảo mật hơn trong một số trường hợp tốt hơn thì lưu vào trong http only kookie tránh dịch tấn công bởi is.", "suggestion": null, "questionText": "Có vẻ như phần trả lời của bạn đang bị rời rạc nên mình chưa nắm bắt được ý chính bạn muốn truyền đạt. Bạn đừng quá căng thẳng nhé! Để đơn giản hóa vấn đề, bạn hãy thử trả lời câu hỏi nhỏ này trước: Sau khi User nhập đúng thông tin đăng nhập, Server sẽ trả về một Token. Vậy theo bạn, Token này thường được Client lưu trữ ở đâu và gửi kèm vào phần nào của HTTP Request trong các lần gọi API tiếp theo để Server xác thực?", "questionType": "FOLLOW_UP", "questionOrder": 4, "behavioralWarnings": []}, {"score": 5.5, "feedback": "Thiếu chi tiết triển khai kỹ thuật, phân tích trade-off và xử lý edge cases đặc thù của hệ thống phân tán.", "answerText": "Thách thức lớn nhất trong dự án mobifone khi làm sigma thời gian thực bằng xích nearer chính là xử lý risc conditions, tức là tránh tình trạng 2 người cùng chọn người giữ một ghế trong cùng một thời điểm.", "suggestion": "Keywords: Redlock / Lua Scripting, Idempotency, Atomic Operations, Optimistic Concurrency Control (OCC), Eventual Consistency.\n\nStructure:\n- Step 1: Distributed Locking (Sử dụng Redis với Lua Script để đảm bảo tính Atomic khi check-and-set ghế, thiết lập TTL cho Temporary Hold).\n- Step 2: State Transition (Luồng chuyển đổi trạng thái: Available -> Pending -> Booked).\n- Step 3: Final Consistency (DB Transaction kết hợp Versioning/OCC để chốt booking, xử lý trường hợp Lock ở Redis hết hạn trước khi DB cập nhật).\n- Step 4: Real-time Sync (SignalR broadcast trạng thái ghế cho toàn bộ client để giảm thiểu tỷ lệ collision ngay từ UI).\n\nSenior Tip: Phân tích bài toán ''Hot Seat'' (ghế hot) và cách áp dụng Request Queue hoặc Virtual Waiting Room để bảo vệ Database khỏi tình trạng Thundering Herd.", "questionText": "Cảm ơn bạn, bạn đã nêu được các phương án lưu trữ Token và lưu ý về bảo mật XSS, đây là một điểm cộng. Bây giờ chúng ta hãy cùng chuyển sang một dự án khác trong CV của bạn nhé. Với dự án ''Movie Theater'', bạn đóng vai trò Leader và dùng SignalR để làm Seat Map thời gian thực. Thách thức lớn nhất khi quản lý trạng thái ghế ngồi để tránh việc hai người cùng đặt một lúc là gì?", "questionType": "BLUEPRINT", "questionOrder": 5, "behavioralWarnings": []}, {"score": null, "feedback": null, "answerText": "Dùng reddit để tạm giữ ghế với ttl như một dạng distress lóc kết hợp sức mạnh RIO để cập nhật real time. Khi xác nhận đặt vé thì dùng data base transaction với optimistic locking version để đảm bảo chỉ một phép được chấp nhận hay không.", "suggestion": null, "questionText": "Bạn đã xác định đúng vấn đề cốt lõi là Race Condition. Vậy cụ thể trong dự án này, bạn đã áp dụng giải pháp kỹ thuật nào để xử lý tình trạng này? Bạn sử dụng cơ chế locking (Optimistic hay Pessimistic) ở tầng Database, hay dùng một giải pháp Distributed Lock như Redis để đảm bảo chỉ một yêu cầu đặt ghế được chấp nhận?", "questionType": "FOLLOW_UP", "questionOrder": 6, "behavioralWarnings": []}, {"score": 2.5, "feedback": "Thiếu hụt trầm trọng kiến thức kỹ thuật, sai thuật ngữ cơ bản, không mô tả được luồng dữ liệu chi tiết.", "answerText": "Em sử dụng spring rx chủ yếu trong 3 nhóm tính năng chatbot 4. Vấn va xin gợi ý lịch tiêm cá nhân hóa và chuyển đổi thông tin y tế thành ngữ dễ hiểu cho phụ huynh.", "suggestion": "Keywords: Vector Database, Embeddings, Prompt Template, Grounding, Hallucination.\n\nStructure:\n- Bước 1: Retrieval (Truy xuất): Lấy User Profile/Medical History từ Relational DB và dùng Embedding để tìm kiến thức y tế tương ứng trong Vector DB.\n- Bước 2: Augmentation (Hợp nhất): Xây dựng Prompt Template bao gồm: System Role + Medical Context + Child''s Data + User Query.\n- Bước 3: Generation (Sinh kết quả): Sử dụng Spring AI gọi LLM API để generate phản hồi.\n- Bước 4: Validation (Kiểm chứng): Áp dụng cơ chế lọc hoặc kiểm tra chéo để đảm bảo thông tin y tế chính xác.\n\nSenior Tip: Phải phân tích cách xử lý ''Hallucination'' (ảo giác AI) vì đây là ứng dụng y tế, sai sót sẽ gây hậu quả nghiêm trọng.", "questionText": "Cảm ơn bạn. Việc kết hợp giữa Distributed Lock (Redis) để quản lý trạng thái tạm thời và Optimistic Locking để chốt giao dịch trong Database là một giải pháp rất chặt chẽ và thực tế để xử lý bài toán tranh chấp ghế ngồi. Bây giờ, chúng ta hãy cùng chuyển sang một dự án khác nhé. Tại dự án ''Child Vaccine Schedule'', bạn có sử dụng Spring AI. Bạn đã áp dụng AI vào những tính năng cụ thể nào để hỗ trợ người dùng?", "questionType": "BLUEPRINT", "questionOrder": 7, "behavioralWarnings": []}, {"score": null, "feedback": null, "answerText": "Mình có sử dụng kỹ thuật gram pin. Tức là với cơ sở dữ liệu RAD.", "suggestion": null, "questionText": "Bạn liệt kê được 3 nhóm tính năng khá thực tế. Tuy nhiên, mình muốn đi sâu hơn vào phần kỹ thuật: Với tính năng ''gợi ý lịch tiêm cá nhân hóa'', bạn đã triển khai Spring AI như thế nào để AI hiểu được dữ liệu riêng biệt của từng đứa trẻ và đưa ra gợi ý chính xác? Bạn có sử dụng kỹ thuật Prompt Engineering hay kết hợp với cơ sở dữ liệu (RAG) không?", "questionType": "FOLLOW_UP", "questionOrder": 8, "behavioralWarnings": []}, {"score": null, "feedback": null, "answerText": "Khi phụ huynh yêu cầu gợi ý lịch tiêm hệ thống lấy thông tin thẻ cộng lịch sử tiêm từ dharavi dùng RA dê lấy trí thức y tế liên quan hết tất cả và một bơm có cấu trúc rồi gọi là lờ mờ qua spring rx để sinh ra được tiêm cá nhân hóa.", "suggestion": null, "questionText": "Có lẽ bạn đang muốn nhắc đến Prompt Engineering và RAG (Retrieval-Augmented Generation). Để mình hiểu rõ hơn về năng lực triển khai của bạn, bạn có thể mô tả chi tiết luồng dữ liệu chạy như thế nào không? Ví dụ: Khi một phụ huynh yêu cầu gợi ý lịch tiêm, hệ thống sẽ truy xuất thông tin gì từ cơ sở dữ liệu và kết hợp với Prompt ra sao để AI trả về kết quả cá nhân hóa cho đứa trẻ đó?", "questionType": "FOLLOW_UP", "questionOrder": 9, "behavioralWarnings": []}, {"score": 3.5, "feedback": "Câu trả lời rời rạc, sai thuật ngữ nghiêm trọng và thiếu tư duy thiết kế hệ thống (Architectural Intent).", "answerText": "interfaces định nghĩa hoặc đồng hành vi và hỗ trợ đa kế thừa và chia sẻ save cộng logic chung và chị hỗ trợ cho đơn kế thừa interface thiên về có thể làm gì khác các lát thêm về là", "suggestion": "Keywords: Is-a vs Can-do, Default/Static Methods, State Management, Interface Segregation Principle, Loose Coupling.\n\nStructure:\n- Step 1: Phân biệt về mặt ngữ nghĩa (Semantic): Abstract Class là quan hệ ''Is-a'' (định nghĩa bản chất), Interface là quan hệ ''Can-do'' (định nghĩa khả năng).\n- Step 2: So sánh kỹ thuật chi tiết: State (Fields/Instance variables), Access Modifiers, Multiple Inheritance.\n- Step 3: Cập nhật Java hiện đại: Phân tích Default methods, Static methods (Java 8) và Private methods (Java 9) trong Interface để xóa nhòa khoảng cách với Abstract Class.\n- Step 4: Trade-off: Khi nào dùng Abstract Class để tránh duplicate code, khi nào dùng Interface để đạt được sự linh hoạt (Decoupling).\n\nSenior Tip: Đề cập đến nguyên lý ''Composition over Inheritance'' và cách Interface hỗ trợ việc triển khai Design Patterns như Strategy hoặc Adapter để tăng khả năng mở rộng.", "questionText": "Cảm ơn bạn, mình đã nắm được luồng vận hành cơ bản của tính năng này: kết hợp dữ liệu người dùng, kiến thức y tế qua RAG và Prompt để LLM sinh ra lịch tiêm cá nhân hóa thông qua Spring AI. Bây giờ, để quay lại với các kiến thức nền tảng của Java Backend, bạn hãy cho mình biết sự khác biệt cơ bản giữa ''Interface'' và ''Abstract Class'' trong lập trình hướng đối tượng là gì?", "questionType": "BLUEPRINT", "questionOrder": 10, "behavioralWarnings": []}, {"score": null, "feedback": null, "answerText": "Interfaces gần như không có trạng thái, chỉ có hằng số và tập trung vào việc định nghĩa hành vi dùng từ java 8 đã cho phép một phần placenta sân astronauts vừa có thể có trạng thái vừa có thể cung cấp sản phẩm triển khai cho các phương thức lây phù hợp. Khi các pastorie có điểm chung về dữ liệu với lauric.", "suggestion": null, "questionText": "Bạn có nhắc đến điểm đúng là Interface hỗ trợ đa kế thừa còn Abstract Class chỉ hỗ trợ đơn kế thừa. Tuy nhiên, câu trả lời của bạn đang bị ngắt quãng và chưa đầy đủ. Bạn hãy giải thích rõ hơn: Về mặt kỹ thuật, Interface và Abstract Class khác nhau như thế nào trong việc định nghĩa các biến (fields) và cách triển khai (implementation) các phương thức?", "questionType": "FOLLOW_UP", "questionOrder": 11, "behavioralWarnings": []}, {"score": 2.0, "feedback": "Diễn đạt không chuyên nghiệp, sai thuật ngữ cơ bản, thiếu chiều sâu về IoC và các loại Injection.", "answerText": "Hầu to wait dùng để spring tự động thêm tiêm vào bin. Chúng ta cần bị band vì nó giúp giảm cấp cho link dễ tết, dễ thay thế impermanent và tuân thủ nguyên tắc đioxi.", "suggestion": "Keywords: Inversion of Control (IoC), Loose Coupling, Constructor Injection, Dependency Inversion Principle (DIP), Bean Lifecycle.\n\nStructure:\n- Định nghĩa @Autowired là cơ chế thực thi IoC để container tự động tiêm dependency.\n- Phân tích DI thông qua 3 lợi ích: Loose Coupling -> Testability (Mocking) -> Maintainability.\n- So sánh Field Injection vs Constructor Injection (Tại sao Senior chọn Constructor Injection).\n\nSenior Tip: Phân tích rủi ro của Field Injection đối với Unit Test (phụ thuộc Spring Context) và lợi ích của Immutability khi dùng final fields với Constructor Injection.", "questionText": "Cảm ơn bạn, mình đã nắm được các ý chính bạn trình bày về sự khác biệt giữa Interface và Abstract Class, đặc biệt là về khả năng kế thừa và việc quản lý trạng thái. Bây giờ, chúng ta sẽ chuyển sang phần Framework nhé. Trong Spring Data JPA mà bạn đã dùng, Annotation @Autowired dùng để làm gì và tại sao chúng ta cần Dependency Injection (DI)?", "questionType": "BLUEPRINT", "questionOrder": 12, "behavioralWarnings": []}, {"score": 1.5, "feedback": "Trả lời cực kỳ thiếu chuyên nghiệp, sai thuật ngữ và hoàn toàn thiếu các đặc tính cốt lõi của RESTful.", "answerText": "Dép là để lấy dữ liệu pos là tặng mới bug là cập nhật toàn bộ delete là xóa.", "suggestion": "Keywords: Idempotency, Safety, PUT vs PATCH, Resource-oriented, HTTP Status Codes\n\nStructure:\n- Bước 1: Khẳng định nguyên lý thiết kế dựa trên Resource (Tài nguyên).\n- Bước 2: Liệt kê các Method kèm đặc tính kỹ thuật: GET (Safe/Idempotent), POST (Non-idempotent), PUT (Idempotent), DELETE (Idempotent).\n- Bước 3: Phân biệt rõ ràng giữa PUT (Replace toàn bộ resource) và PATCH (Partial update).\n- Bước 4: Đi kèm các HTTP Status Code chuẩn (200 OK, 201 Created, 204 No Content, 404 Not Found, v.v.).\n\nSenior Tip: Phải nhấn mạnh tính Idempotency khi thiết kế API để đảm bảo tính nhất quán dữ liệu trong hệ thống phân tán (distributed systems).", "questionText": "Cảm ơn bạn, mình đã nắm được ý bạn về việc sử dụng @Autowired để Spring tự động inject bean và lợi ích của DI trong việc giảm sự phụ thuộc (loose coupling), giúp hệ thống dễ test và linh hoạt hơn. Bây giờ, chúng ta sẽ chuyển sang phần xây dựng API nhé. JD của chúng mình yêu cầu xây dựng RESTful APIs. Bạn hãy liệt kê các HTTP Methods phổ biến (như GET, POST, PUT, DELETE) và mục đích sử dụng của từng loại được không?", "questionType": "BLUEPRINT", "questionOrder": 13, "behavioralWarnings": []}, {"score": 4.5, "feedback": "Trả lời hời hợt, thiếu thuật ngữ kỹ thuật và không phân tích được cơ chế vận hành thực tế của Index.", "answerText": "Indec giúp tăng tốc truy vấn bằng cách trắng full stay buscal nhưng đánh đổi bằng việc làm chậm thao tác j tốn thêm dung lượng và cần được thiết kế cẩn thận.", "suggestion": "Keywords: B-Tree, Clustered/Non-Clustered Index, Page Split, Write Amplification, Execution Plan.\n\nStructure:\n- Cơ chế: Giải thích cấu trúc B-Tree và độ phức tạp O(log n) để thay thế cụm từ \"tăng tốc\".\n- Phân loại: Phân tích sự khác biệt giữa Clustered Index (sắp xếp vật lý) và Non-Clustered Index (con trỏ).\n- Phân tích Write Overhead: Giải thích hiện tượng Page Split khi cập nhật dữ liệu khiến I/O tăng cao.\n- Kiểm chứng: Đề cập việc đọc Execution Plan để phân biệt Index Seek và Index Scan.\n\nSenior Tip: Phân tích về Covering Index để loại bỏ Key Lookup, tối ưu hóa triệt để tốc độ truy vấn.", "questionText": "Cảm ơn bạn, bạn đã nắm rõ các phương thức cơ bản của RESTful API. Bây giờ, chúng ta sẽ chuyển sang phần tối ưu hóa Database nhé. Để tối ưu hóa truy vấn Database như trong mô tả công việc, theo bạn việc tạo ''Index'' (chỉ mục) trong MSSQL hay PostgreSQL có tác dụng gì và nó có nhược điểm nào không?", "questionType": "BLUEPRINT", "questionOrder": 14, "behavioralWarnings": []}, {"score": null, "feedback": null, "answerText": "Index giúp tăng tốc đọc dữ liệu select nhưng phải trả giá bằng việc làm chậm các thao tác ghi insert update delete đi mối thay đổi dữ liệu đều phải được phản ánh vào cấu trúc index.", "suggestion": null, "questionText": "Bạn đã nắm được ý chính là Index giúp tránh việc quét toàn bộ bảng (full table scan) để tăng tốc truy vấn và đánh đổi bằng dung lượng lưu trữ. Tuy nhiên, bạn có nhắc đến việc làm chậm một số ''thao tác''. Bạn có thể nói rõ hơn đó là những thao tác cụ thể nào và tại sao khi có Index thì các thao tác đó lại bị chậm đi không?", "questionType": "FOLLOW_UP", "questionOrder": 15, "behavioralWarnings": []}, {"score": 2.0, "feedback": "Sai lệch nghiêm trọng thuật ngữ kỹ thuật, thiếu tư duy hệ thống và không đạt chuẩn giao tiếp Senior.", "answerText": "Monolith là một toàn bộ ứng dụng nằm trong một khối duy nhất đơn giản nhưng khó mở rộng. Microsoft services chia thành nhiều xe buýt nhỏ, độc lập, dễ dàng và linh hoạt hơn phương nhưng phức tạp về vận hành.", "suggestion": "Keywords: Eventual Consistency, Saga Pattern, Service Mesh, CAP Theorem, Distributed Tracing.\n\nStructure:\n- Phân loại thách thức: Chia thành 3 nhóm chính: Network (Latency/Partial Failure), Data (Consistency/Distributed Transactions), và Observability (Tracing/Logging).\n- Giải pháp tương ứng: Map cụ thể từng thách thức với Pattern (Ví dụ: Data Consistency -> Saga Pattern/Transactional Outbox; Network Failure -> Circuit Breaker/Retry).\n- Trade-off: Phân tích chi phí vận hành (Operational Overhead) đối với quy mô team và hệ thống.\n\nSenior Tip: Đề cập đến chiến lược chuyển đổi từ Monolith sang Microservices bằng Strangler Fig Pattern để giảm thiểu rủi ro.", "questionText": "Câu trả lời của bạn rất chính xác và đầy đủ. Bạn đã nêu rõ được lợi ích về tốc độ truy vấn cũng như sự đánh đổi về hiệu suất ghi và dung lượng lưu trữ khi sử dụng Index. Bây giờ, chúng ta sẽ chuyển sang một chủ đề khác có trong JD nhé. Bạn hiểu thế nào là kiến trúc Microservices và nó khác gì so với kiến trúc Monolith (nguyên khối)?", "questionType": "BLUEPRINT", "questionOrder": 16, "behavioralWarnings": []}, {"score": null, "feedback": null, "answerText": "Microsoft services mai nặng nhiều thách thức về server giao tiếp mạng quan sát hệ thống tính nhất của anh dữ liệu và triển khai để kiểm soát sự phức tạp này. Chúng ta thường dùng ab i gave way, cervinalis rcovery, schuylkill breaker, istri tracing hoặc là trên. Cái blogging Messenger. Cuber cái.", "suggestion": null, "questionText": "Bạn đã nắm được sự khác biệt cơ bản giữa Monolith và Microservices. Bạn có đề cập rằng Microservices ''phức tạp về vận hành'', vậy bạn có thể nói rõ hơn những thách thức cụ thể trong vận hành mà Microservices mang lại là gì, và chúng ta thường dùng giải pháp nào để quản lý sự phức tạp đó không?", "questionType": "FOLLOW_UP", "questionOrder": 17, "behavioralWarnings": []}], "improvementPlan": null, "aiOverviewFeedback": "Đã chấm điểm xong."}', '{"domain": "IT", "language": "VI", "difficulty": "FRESHER_BASIC", "interview_mode": "STANDARD_MOCK", "duration_minutes": 20}', 287),
        (32, null, 5, null, '2026-04-19 08:17:53.278159', '2026-04-19 10:28:03.301942', 'IT', 'CANCELLED', 'STANDARD_MOCK', null, '4f1b4ffe-3143-4a13-92a9-6844c8619fda', null, '{"id": 6, "user": {"id": 5, "name": "Trần Bình An", "role": "USER", "cvUrl": "https://res.cloudinary.com/dimvyno0z/image/upload/v1775745501/my_app/docs/5cbc1648-7684-468b-a546-3719047a22bc.pdf", "email": "binhan@gmail.com", "major": "CNTT", "isActive": true, "password": "123", "avatarUrl": "https://res.cloudinary.com/dimvyno0z/image/upload/v1773564900/my_app/images/koljabyfgesxt5ptp8u5.jpg", "public_id": "my_app/images/koljabyfgesxt5ptp8u5", "university": "ĐH Bách Khoa TPHCM", "cv_public_id": "my_app/docs/5cbc1648-7684-468b-a546-3719047a22bc"}, "tools": ["Git/GitHub/GitLab", "Maven", "Jira", "Swagger", "Docker", "Postman", "JUnit", "xUnit", "Cloudinary", "Firebase Cloud Messaging"], "projects": [{"name": "CHILD VACCINE SCHEDULE TRACKING SYSTEM", "role": "Back-end, Leader", "outcome": "Schedule vaccination, payment, evaluation, update post-vaccination reactions. Track vaccination progress & vaccination history. The facility records vaccination results in the child''s records. The system automatically sends reminder and notification emails. Manage vaccines in stock, users, booking schedules, ...", "teamSize": 3, "usedTools": ["Java", "Spring Boot", "Spring Security", "Spring AI", "MSSQL", "Spring Mail"], "description": "A web application that manages children''s vaccination schedules, allowing parents and health centers to schedule, track, and update vaccination records. Supports individual/group scheduling, automatic reminders, secure payments, and AI-powered customer support."}, {"name": "BAMBI KITCHEN", "role": "Back-end, Leader", "outcome": "Authorization & Authentication ( JW, OAuth2 Google ). Manage menus & recipes. Raw material warehouse management (Inventory, Import/Export, Warning). Order (Custom dishes & available dishes) with ingredient reservation system. Multi-channel payment (Cash, Momo, VNPAY). AI intergration ( Gemini AI - Nutrition & Recommend ).", "teamSize": 6, "usedTools": ["Spring Boot", "Spring Security", "Spring AI", "MSSQL", "Cloudinary", "Firebase Cloud Messaging", "Spring Mail"], "description": "Bambi kitchen is a food chain that specializes in providing healthy dishes and customers can customize and choose personalized dish ingredients step by step, with integrated AI to evaluate orders."}], "createdAt": [2026, 4, 9, 14, 38, 18, 734762000], "updatedAt": [2026, 4, 9, 14, 38, 22, 582891000], "educations": [{"gpa": "3.2", "major": "Software Engineering", "degree": null, "school": "FPT University", "end_date": "2026", "start_date": "2022"}], "softSkills": ["Teamwork", "English", "Fast learner", "Adaptability", "Problem-solving", "Technical Reading"], "targetRole": "Java Developer", "targetLevel": "Junior", "achievements": ["HONORABLE STUDENT OF TRIMESTER Semester 1, 3, 4, 5", "Admissions Collaborator -FPT University"], "introduction": "As a Java Developer, I am eager to work in a challenging environment to develop my skills and gain practical experience. I leverage my logical thinking and passion for programming to quickly transform knowledge into practical solutions, aiming to become an effective and well-grounded software development specialist.", "certifications": ["Web Design for Everybody: Basics of Web Development & Coding", "Software Development Lifecycle", "Java FullStack Developer"], "technicalSkills": ["Java", "C#", "HTML/CSS", "Spring Security", "Spring Data JPA", "Spring MVC", "MSSQL", "PostgreSQL", "JPA/Hibernate", "MongoDB", "ASP .NET", "SignalR", "Spring Boot", "Spring AI"], "workExperiences": [{"company": "FPT Software Academy", "end_date": "08/2025", "position": ".NET Developer Intern", "start_date": "05/2025", "description": "Final Training Project: Movie Theater. Role: Back-end, Leader. Developed an online movie ticketing system featuring real-time seat map visualization. Developed modules: movie management, showtimes, theaters, promotions, user accounts, and points accumulation. Authorization & Authentication (Cookie Authentication). Designed the entire database and processing flow architecture for the modules. Actively learned and mastered all modules, acted as a connection point between sections, divided tasks and guided the team to implement code according to the design. Performed work under the supervision of the mentor, ensuring project progress and quality."}]}', '{"basic_info": {"job_title": "Java Backend Developer", "industry_domain": "Công nghệ thông tin", "seniority_level": "Junior"}, "competencies": {"hard_skills": ["Spring Boot", "REST API", "SQL", "Giai quyet van de"], "soft_skills": ["Giao tiep tot"], "tools_and_platforms": []}, "responsibilities": []}', null, '{"domain": "IT", "language": "VI", "difficulty": "FRESHER_BASIC", "interview_mode": "STANDARD_MOCK", "duration_minutes": 30}', null),
        (108, null, 9, null, '2026-08-09 04:52:28.775638', '2026-08-09 08:19:34.721583', 'IT', 'CANCELLED', 'STANDARD_MOCK', null, '0e4a757d-97a1-4f8f-a40d-5c395b3a37bd', null, '{"id": 24, "tools": ["Git", "GitHub", "GitLab", "Maven", "Jira", "Swagger", "Docker", "Postman", "JUnit", "xUnit"], "projects": [{"name": "Movie Theater", "role": "Back-end, Leader", "outcome": "Final score: 9.7", "teamSize": 5, "usedTools": ["ASP.NET Core", "ASP.NET MVC", "PostgreSQL", "SignalR", "GitHub"], "description": "An online movie ticketing system featuring real-time seat map visualization and modules for movie, showtimes, theaters, promotions, and user accounts."}, {"name": "CHILD VACCINE SCHEDULE TRACKING SYSTEM", "role": "Back-end, Leader", "outcome": "Supports individual/group scheduling, automatic reminders, secure payments, and AI-powered customer support.", "teamSize": 3, "usedTools": ["Java", "Spring Boot", "Spring Security", "Spring AI", "MSSQL", "Spring Mail"], "description": "A web application that manages children''s vaccination schedules, allowing parents and health centers to schedule, track, and update vaccination records."}, {"name": "BAMBI KITCHEN", "role": "Back-end, Leader", "outcome": "Implemented JWT/OAuth2 authentication, warehouse management, multi-channel payment (Cash, Momo, VNPAY) and AI integration via Gemini AI.", "teamSize": 6, "usedTools": ["Spring Boot", "Spring Security", "Spring AI", "MSSQL", "Cloudinary", "Firebase Cloud Messaging", "Spring Mail"], "description": "A healthy food chain application where customers can customize dish ingredients step by step with integrated AI for order evaluation."}], "createdAt": [2026, 8, 4, 16, 14, 33, 422891000], "updatedAt": [2026, 8, 4, 16, 14, 33, 422919000], "educations": [{"gpa": "3.2", "major": "Software Engineering", "degree": null, "school": "FPT University", "end_date": "2026", "start_date": "2022"}], "softSkills": ["Technical Reading Proficiency in English", "Fast learner", "adaptability", "problem-solving", "teamwork"], "targetRole": "Java Developer", "targetLevel": "Intern", "achievements": ["Honorable Student of Trimester (Semester 1, 3, 4, 5)", "Admissions Collaborator - FPT University"], "introduction": "As a Java Developer, I am eager to work in a challenging environment to develop my skills and gain practical experience. I leverage my logical thinking and passion for programming to quickly transform knowledge into practical solutions, aiming to become an effective and well-grounded software development specialist.", "applicationId": 114, "certifications": ["Web Design for Everybody: Basics of Web Development & Coding", "Software Development Lifecycle", "Java FullStack Developer"], "technicalSkills": ["Java", "C#", "HTML/CSS", "Spring Security", "Spring Data JPA", "Spring MVC", "Validation", "DI/IoC", "ASP .NET", "MSSQL", "PostgreSQL", "JPA/Hibernate", "MongoDB"], "workExperiences": [{"company": "FPT Software Academy", "end_date": "08/2025", "position": ".NET Developer Intern", "start_date": "05/2025", "description": "Worked as a Back-end Leader for the Movie Theater project. Developed an online movie ticketing system with real-time seat map visualization and various management modules. Designed database and processing flow architecture."}]}', '{"basic_info": {"job_title": "Junior Java Backend Developer", "industry_domain": "Software Development / AI Technology", "seniority_level": "Junior"}, "competencies": {"hard_skills": ["Java", "Backend Development", "Building scalable RESTful APIs", "Database query optimization", "Microservices integration"], "soft_skills": ["Passionate"], "tools_and_platforms": []}, "responsibilities": ["Participate in building scalable RESTful APIs", "Optimize database queries", "Integrate microservices for AI-driven platform"]}', null, '{"domain": "IT", "language": "VI", "difficulty": "FRESHER_BASIC", "interview_mode": "STANDARD_MOCK", "duration_minutes": 20}', 276),
