        (20, null, 2, null, '2026-04-15 06:39:34.737592', '2026-04-19 14:54:14.708236', 'NON_IT', 'CANCELLED', 'STANDARD_MOCK', null, '6a7071a0-fc3d-447d-94ed-ff2363537b2e', null, '{"id": 1, "user": {"id": 2, "name": "THU HA NGUYEN PHAM", "role": "USER", "cvUrl": "https://res.cloudinary.com/dimvyno0z/image/upload/v1774535502/my_app/docs/20f7e1be-1171-40e6-850c-b952525340ad.pdf", "email": "ha@gmail.com", "major": "CNTT", "isActive": true, "password": "12345", "avatarUrl": "https://res.cloudinary.com/dimvyno0z/image/upload/v1772820944/my_app/images/t6hzjlhcmuj8sq7drhm4.png", "public_id": "my_app/images/t6hzjlhcmuj8sq7drhm4", "university": "fpt", "cv_public_id": "my_app/docs/20f7e1be-1171-40e6-850c-b952525340ad"}, "tools": ["Git", "GitHub", "GitLab", "Maven", "Jira", "Swagger", "Docker", "Postman", "JUnit", "xUnit"], "projects": [{"name": "CHILD VACCINE SCHEDULE TRACKING SYSTEM", "role": "Back-end, Leader", "outcome": null, "teamSize": 3, "usedTools": ["Java", "Spring Boot", "Spring Security", "Spring AI", "MSSQL", "Spring Mail"], "description": "Đặt lịch tiêm chủng, thanh toán, đánh giá, cập nhật phản ứng sau tiêm. Theo dõi quá trình tiêm & lịch sử tiêm chủng. Cơ sở ghi nhận kết quả tiêm chủng vào hồ sơ của trẻ. Dashboard & Report. Hệ thống tự gửi mail nhắc nhở, thông báo. Quản lí vaccine trong kho, người dùng, lịch đặt,..."}, {"name": "BAMBI KITCHEN", "role": "Back-end, Leader", "outcome": null, "teamSize": 6, "usedTools": ["Spring Boot", "Spring Security", "Spring AI", "MSSQL", "Cloudinary", "Firebase Cloud Messaging", "Spring Mail"], "description": "Xác thực & phân quyền ( JW, OAuth2 Google ). Quản lý thực đơn & công thức nấu ăn. Quản lý kho nguyên liệu ( Tồn kho, Nhập/Xuất, Cảnh báo ). Đặt hàng ( Custom món & món có sẵn ) với hệ thống giữ chỗ nguyên liệu. Thanh toán đa kênh ( Cash, Momo, VNPAY ). AI intergration ( Gemini AI - Dinh dưỡng & Tư vấn )."}, {"name": "Movie Theater", "role": "Back-end, Leader", "outcome": "Điểm cuối khóa: 9.7", "teamSize": 5, "usedTools": ["ASP.NET Core", "ASP.NET MVC", "PostgreSQL"], "description": "Phát triển hệ thống đặt vé xem phim trực tuyến có hiển thị sơ đồ ghế theo thời gian thực"}], "createdAt": [2026, 3, 6, 18, 29, 27, 730816000], "updatedAt": [2026, 3, 26, 14, 31, 40, 365838000], "educations": [{"gpa": "3.2", "major": "Kỹ thuật phần mềm", "degree": null, "school": "Đại học FPT", "end_date": "2026", "start_date": "2022"}], "softSkills": ["Teamwork", "Problem Solving", "Adaptability", "Fast Learner", "Communication"], "targetRole": "Java Developer", "targetLevel": "Fresher", "achievements": ["Sinh viên giỏi", "Cộng tác viên tuyển sinh - Đại học FPT"], "introduction": "Là một lập trình viên với nền tảng ngôn ngữ Java, tôi mong muốn tìm kiếm một môi trường lý tưởng để phát triển năng lực bản thân. Tôi sẽ vận dụng tư duy logic và niềm đam mê sẵn có để nhanh chóng chuyển hóa kiến thức thành kỹ năng thực tế. Mục tiêu của tôi là tích lũy kinh nghiệm có giá trị qua từng dự án, không ngừng tiến bộ để trở thành một chuyên viên phát triển phần mềm vững vàng và hiệu quả.", "certifications": ["Web Design for Everybody: Basics of Web Software Development Lifecycle", "Java FullStack Developer - Coursera"], "technicalSkills": ["Java", "C#", "HTML/CSS", "Spring Security", "Spring Data JPA", "Spring MVC", "MSSQL", "PostgreSQL", "JPA/Hibernate", "MongoDB", "ASP.NET Core", "ASP.NET MVC", "Spring Boot", "Spring AI"], "workExperiences": [{"company": "FPT Software Academy", "end_date": "08/2025", "position": "Thực tập sinh .NET", "start_date": "05/2025", "description": "Dự án Cuối khóa Đào tạo: Movie Theater. Phát triển hệ thống đặt vé xem phim trực tuyến có hiển thị sơ đồ ghế theo thời gian thực, tích hợp các module quản lý phim, suất chiếu, phòng chiếu, khuyến mãi, và tài khoản người dùng, tích điểm. Hỗ trợ phân quyền người dùng (khách hàng, nhân viên, quản trị)."}]}', '{"basic_info": {"job_title": "marketing intern", "industry_domain": "Marketing", "seniority_level": "Intern"}, "competencies": {"hard_skills"