        (2, null, 2, null, '2026-03-07 09:36:58.672009', '2026-03-09 14:16:44.164082', 'IT', 'CANCELLED', 'STANDARD_MOCK', null, '410f3a1f-b522-414e-89cd-3aaaf725477a', null, '{"id": 1, "user": {"id": 2, "name": "THU HA NGUYEN PHAM", "role": "USER", "cvUrl": "https://res.cloudinary.com/dimvyno0z/raw/upload/v1772876158/my_app/docs/a17ef5f4-506b-4e14-a9ab-74e2a851af2d.pdf", "email": null, "major": "CNTT", "isActive": true, "password": null, "avatarUrl": "https://res.cloudinary.com/dimvyno0z/image/upload/v1772820944/my_app/images/t6hzjlhcmuj8sq7drhm4.png", "public_id": "my_app/images/t6hzjlhcmuj8sq7drhm4", "university": "fpt", "cv_public_id": "my_app/docs/a17ef5f4-506b-4e14-a9ab-74e2a851af2d.pdf"}, "tools": ["Git/GitHub/GitLab", "Maven", "Jira", "Swagger", "Postman"], "projects": [{"name": "Child Vaccine Schedule Tracking System", "role": "Leader, Back-end", "outcome": null, "teamSize": 3, "usedTools": ["Spring Boot", "React Js", "SQL Server"], "description": "Vaccination scheduling, payments, service reviews, and post-injection reaction updates. Track vaccination progress and view immunization history. Allows medical facilities to record vaccination results into a child''s profile. Dashboard & Reporting. Automated email reminders and notifications. Management of vaccine inventory, users, appointments, etc."}, {"name": "Smart Wallet", "role": "Leader, Back-end", "outcome": null, "teamSize": 3, "usedTools": ["Spring Boot", "React", "SQL Server"], "description": "Manage income and expenditure, helping users track income, expenditure and consumption appropriately. Allow users to classify income and expenditure and create budgets and track income and expenditure according to the budget. The home page is intuitive and easy to observe."}, {"name": "Product Information", "role": null, "outcome": null, "teamSize": null, "usedTools": ["MVC", "JSP", "tomcat", "session", "filterchain", "JDBC", "cookie"], "description": "Manage products by category. Add favorite products. Basic CRUD,Login."}], "createdAt": [2026, 3, 6, 18, 29, 27, 730816000], "updatedAt": [2026, 3, 7, 9, 36, 1, 219122000], "educations": [{"gpa": "3.2", "major": "Software Engineering", "degree": null, "school": "FPT University", "end_date": "2026", "start_date": "2022"}], "softSkills": ["Teamwork", "Problem-solving skills", "Self-study and research", "Presentation skills", "Project management", "English (Fair)"], "targetRole": "Java Developer", "targetLevel": "Fresher", "achievements": ["Good students (2023 - 2025)", "Honor (2023 - 2025)"], "introduction": "With a background in Java development, I am looking for the right opportunity to grow my abilities. I am committed to using my logical thinking and passion to quickly turn theoretical knowledge into real-world skills. My aim is to gain valuable experience with every project and steadily develop into a proficient and effective software developer.", "certifications": ["Web Design for Everybody: Basics of Web Development & Coding (2024)", "Software Development LifeCycle (2024)", "Java FullStack Developer (2024)"], "technicalSkills": ["Java", "C#", "HTML/CSS", "Spring Security", "Spring Data JPA", "Spring MVC", "Validation", "DI/IoC", "MSSQL", "PostgreSQL", "JPA/Hibernate"], "workExperiences": [{"company": "FPT Software Academy", "end_date": "8/2025", "position": ".NET INTERNSHIP", "start_date": "5/2025", "description": "Final Project of the Training Course: Movie Theater. Develop an online movie ticket booking system that displays real-time seat maps. Integrate modules: manage movies, showtimes, screening rooms, promotions, and user accounts, accumulate points. Support user authorization (customers, employees, administrators)."}]}', '{"basic_info": {"job_title": "Nhà phát triển ứng dụng", "industry_domain": "Ngân hàng, Tài chính, Công nghệ thông tin", "seniority_level": "Junior"}, "competencies": {"hard_skills": ["Java", "Java Spring", "Java Spring boot", "Restful API", "HTML", "CSS", "JavaScript", "SQL", "Phát triển ứng dụng web", "Phát triển API"], "soft_skills": [], "tools_and_platforms": ["Oracle", "httpd"]}, "responsibilities": ["Làm việc onsite ngân hàng, công ty đa quốc gia, tập đoàn với nhiều dự án và công nghệ khác nhau", "Tham gia thiết kế ứng dụng, phân tích requirements, thiết kế hệ thống", "Nghiên cứu và áp dụng các công nghệ mới", "Thiết kế và phát triển giải pháp nền tảng mới", "Hỗ trợ và duy trì các ứng dụng web hiện có"]}', null, '{"domain": "IT", "language": "VI", "difficulty": "FRESHER_BASIC", "interview_mode": "STANDARD_MOCK", "duration_minutes": 15}', null),
        (6, null, 14, null, '2026-03-15 10:12:39.726679', '2026-03-15 12:51:00.313317', 'IT', 'CANCELLED', 'STANDARD_MOCK', null, '276fe0fa-51e7-4b4b-b432-b937e552c805', null, '{"id": 3, "user": {"id": 14, "name": "Thu Hồng", "role": "USER", "cvUrl": "https://res.cloudinary.com/dimvyno0z/raw/upload/v1773567119/my_app/docs/c81a07f2-f16a-453b-ba50-fc3a2067b85d.pdf", "email": "hong4@gmail.com", "major": "CNTT", "isActive": true, "password": "12345", "avatarUrl": null, "public_id": null, "university": "UIT", "cv_public_id": "my_app/docs/c81a07f2-f16a-453b-ba50-fc3a2067b85d.pdf"}, "tools": ["Git/GitHub", "Maven", "Trello", "Jira", "Swagger", "Postman", "JUnit", "Selenium", "k6", "Vercel", "Ngrok", "Render", "Cloudflare", "Spring Boot Actuator", "Prometheus", "Grafana", "API Gateway", "Eureka", "Config Server", "Load Balancing", "FeignClient", "RestTemplate", "WebClient"], "projects": [{"name": "Online Food Ordering App", "role": "Backend Developer & Architecture Contributor", "outcome": "Reduced email notification latency by ~40% through asynchronous processing. Delivered full-feature MVP ahead of schedule, improving booking usability and reducing internal test errors by over 25%.", "teamSize": 4, "usedTools": ["Java", "Spring Boot", "Spring Security", "Spring AI", "MSSQL", "Maven"], "description": "A microservices-based food ordering platform supporting order, payment, and inventory management with real-time communication and event-driven scalability."}, {"name": "Child Vaccine Schedule Tracking System", "role": "Backend Lead & Developer, UI Designer", "outcome": "Developed 15+ RESTful APIs with flexible booking options and asynchronous email notifications to reduce response time. Implemented OAuth2 authentication, payment workflows, cancellation tracking, and booking data validation. Integrated GPT-3.5 chatbot via Spring AI for automated customer support.", "teamSize": 3, "usedTools": ["Java", "Spring Boot", "Spring Security", "Spring AI", "MSSQL"], "description": "A web app for managing child vaccination schedules, allowing parents and health centers to book, track, and update vaccination records. Supports individual/group bookings, automated reminders, secure payments, and AI-powered customer support."}, {"name": "Development of an aviation data pipeline on AWS", "role": null, "outcome": "Successfully worked in a real-world project environment for an international client. Contributed to the release of a complex pipeline processing 4 schemas & 200+ tables on AWS. Strengthened understanding of cloud-based data processing workflows. Enhanced skills in integration testing and cross-functional team collaboration.", "teamSize": null, "usedTools": ["AWS (S3, Glue, Airflow, DynamoDB, Redshift)", "Snowflake", "JIRA"], "description": "Participated in testing a large-scale cloud-based data pipeline system for a Japanese aviation client, ensuring data integrity, reliability, and compliance with business requirements."}], "createdAt": [2026, 3, 15, 9, 31, 56, 958837000], "updatedAt": [2026, 3, 15, 9, 32, 50, 967844000], "educations": [{"gpa": "3.0", "major": "Software Engineer", "degree": null, "school": "FPT University", "end_date": "2026", "start_date": "2022"}], "softSkills": ["Fast learner", "Collaboration", "Problem-solving", "Adaptability", "English (Fluent in technical reading, conversational)"], "targetRole": "Java Backend Developer", "targetLevel": "Fresher", "achievements": [], "introduction": "Proactive and adaptable Software Engineering student passionate about Java backend development, with hands-on experience in Spring Framework, microservices architecture, and cloud deployment through academic projects and internships. Skilled in designing and deploying scalable systems using Spring Boot, RESTful APIs, and Microservices. Short-term, I aim to excel as a Junior Java Developer; long-term, to become a Software Architect. I''m committed to staying updated on emerging technologies like AI integration and cloud-native solutions to bring fresh ideas to collaborative teams.", "certifications": ["Coursera - Software Development, Java Full Stack Developer, Java Testing", "FPT Software Academy - Azure Cloud Fundamentals, Software Testing"], "technicalSkills": ["Java", "Spring Boot", "Spring Security", "Spring AI", "Spring MVC", "Spring Data JPA", "RESTful API", "Microservices Architecture", "Event-Driven Architecture (EDA)", "Saga Pattern", "RabbitMQ", "MSSQL", "PostgreSQL", "JPA/Hibernate", "Redshift", "Snowflake", "DynamoDB", "MongoDB", "Docker", "AWS", "Azure", "OAuth2", "JWT"], "workExperiences": [{"company": "FPT Software", "end_date": "08/2025", "position": "Data Quality Assurance Intern", "start_date": "05/2025", "description": "Participated in testing a large-scale cloud-based data pipeline system for a Japanese aviation client, ensuring data integrity, reliability, and compliance with business requirements."}]}', '{"basic_info": {"job_title": null, "industry_domain": null, "seniority_level": null}, "competencies": {"hard_skills": [], "soft_skills": [], "tools_and_platforms": []}, "responsibilities": []}', null, '{"domain": "IT", "language": "VI", "difficulty": "FRESHER_BASIC", "interview_mode": "STANDARD_MOCK", "duration_minutes": 15}', null),
        (34, null, 5, null, '2026-04-19 11:02:18.853516', '2026-04-19 13:55:41.471127', 'IT', 'CANCELLED', 'STANDARD_MOCK', null, '7d12e40d-de09-4c5c-877f-67c30986b914', null, '{"id": 6, "user": {"id": 5, "name": "Trần Bình An", "role": "USER", "cvUrl": "https://res.cloudinary.com/dimvyno0z/image/upload/v1775745501/my_app/docs/5cbc1648-7684-468b-a546-3719047a22bc.pdf", "email": "binhan@gmail.com", "major": "CNTT", "isActive": true, "password": "123", "avatarUrl": "https://res.cloudinary.com/dimvyno0z/image/upload/v1773564900/my_app/images/koljabyfgesxt5ptp8u5.jpg", "public_id": "my_app/images/koljabyfgesxt5ptp8u5", "university": "ĐH Bách Khoa TPHCM", "cv_public_id": "my_app/docs/5cbc1648-7684-468b-a546-3719047a22bc"}, "tools": ["Git/GitHub/GitLab", "Maven", "Jira", "Swagger", "Docker", "Postman", "JUnit", "xUnit", "Cloudinary", "Firebase Cloud Messaging"], "projects": [{"name": "CHILD VACCINE SCHEDULE TRACKING SYSTEM", "role": "Back-end, Leader", "outcome": "Schedule vaccination, payment, evaluation, update post-vaccination reactions. Track vaccination progress & vaccination history. The facility records vaccination results in the child''s records. The system automatically sends reminder and notification emails. Manage vaccines in stock, users, booking schedules, ...", "teamSize": 3, "usedTools": ["Java", "Spring Boot", "Spring Security", "Spring AI", "MSSQL", "Spring Mail"], "description": "A web application that manages children''s vaccination schedules, allowing parents and health centers to schedule, track, and update vaccination records. Supports individual/group scheduling, automatic reminders, secure payments, and AI-powered customer support."}, {"name": "BAMBI KITCHEN", "role": "Back-end, Leader", "outcome": "Authorization & Authentication ( JW, OAuth2 Google ). Manage menus & recipes. Raw material warehouse management (Inventory, Import/Export, Warning). Order (Custom dishes & available dishes) with ingredient reservation system. Multi-channel payment (Cash, Momo, VNPAY). AI intergration ( Gemini AI - Nutrition & Recommend ).", "teamSize": 6, "usedTools": ["Spring Boot", "Spring Security", "Spring AI", "MSSQL", "Cloudinary", "Firebase Cloud Messaging", "Spring Mail"], "description": "Bambi kitchen is a food chain that specializes in providing healthy dishes and customers can customize and choose personalized dish ingredients step by step, with integrated AI to evaluate orders."}], "createdAt": [2026, 4, 9, 14, 38, 18, 734762000], "updatedAt": [2026, 4, 9, 14, 38, 22, 582891000], "educations": [{"gpa": "3.2", "major": "Software Engineering", "degree": null, "school": "FPT University", "end_date": "2026", "start_date": "2022"}], "softSkills": ["Teamwork", "English", "Fast learner", "Adaptability", "Problem-solving", "Technical Reading"], "targetRole": "Java Developer", "targetLevel": "Junior", "achievements": ["HONORABLE STUDENT OF TRIMESTER Semester 1, 3, 4, 5", "Admissions Collaborator -FPT University"], "introduction": "As a Java Developer, I am eager to work in a challenging environment to develop my skills and gain practical experience. I leverage my logical thinking and passion for programming to quickly transform knowledge into practical solutions, aiming to become an effective and well-grounded software development specialist.", "certifications": ["Web Design for Everybody: Basics of Web Development & Coding", "Software Development Lifecycle", "Java FullStack Developer"], "technicalSkills": ["Java", "C#", "HTML/CSS", "Spring Security", "Spring Data JPA", "Spring MVC", "MSSQL", "PostgreSQL", "JPA/Hibernate", "MongoDB", "ASP .NET", "SignalR", "Spring Boot", "Spring AI"], "workExperiences": [{"company": "FPT Software Academy", "end_date": "08/2025", "position": ".NET Developer Intern", "start_date": "05/2025", "description": "Final Training Project: Movie Theater. Role: Back-end, Leader. Developed an online movie ticketing system featuring real-time seat map visualization. Developed modules: movie management, showtimes, theaters, promotions, user accounts, and points accumulation. Authorization & Authentication (Cookie Authentication). Designed the entire database and processing flow architecture for the modules. Actively learned and mastered all modules, acted as a connection point between sections, divided tasks and guided the team to implement code according to the design. Performed work under the supervision of the mentor, ensuring project progress and quality."}]}', '{"basic_info": {"job_title": "Frontend developer", "industry_domain": "IT", "seniority_level": "Junior"}, "competencies": {"hard_skills": ["React", "TypeScript", "Tối ưu hiệu năng"], "soft_skills": [], "tools_and_platforms": []}, "responsibilities": []}', null, '{"domain": "IT", "language": "VI", "difficulty": "FRESHER_BASIC", "interview_mode": "STANDARD_MOCK", "duration_minutes": 30}', null),
