        (41, 4.1499999999999995, 21, '2026-05-17 04:36:28.796056', '2026-05-17 03:43:16.287280', '2026-05-17 04:36:28.797166', 'IT', 'COMPLETED', 'STANDARD_MOCK', 'REJECT', '79480578-55a6-4c68-a07a-1f8bd686641e', '{"blueprint": [{"questions": [{"order": 1, "rag_keyword": null, "question_text": "Chào Khang, mình đã xem qua CV của bạn với rất nhiều dự án thú vị về Microservices và AI. Bạn có thể giới thiệu ngắn gọn về bản thân và định hướng phát triển của bạn với vị trí Java Backend không?", "question_type": "CORE"}], "phase_name": "Giới thiệu & Khởi động", "duration_minutes": 2}, {"questions": [{"order": 2, "rag_keyword": null, "question_text": "Trong dự án Electronics E-Commerce Platform, bạn có sử dụng kiến trúc Microservices. Bạn có thể liệt kê các service chính mà bạn đã xây dựng trong hệ thống này không?", "question_type": "CORE"}, {"order": 3, "rag_keyword": null, "question_text": "Mình thấy bạn có sử dụng RabbitMQ trong dự án E-Commerce. Bạn có thể chia sẻ RabbitMQ đóng vai trò gì trong việc truyền tin giữa các service không?", "question_type": "FOLLOW_UP"}, {"order": 4, "rag_keyword": null, "question_text": "Với dự án BAMBI KITCHEN, bạn có tích hợp Spring AI. Chức năng cụ thể của AI trong việc đánh giá đơn hàng (evaluate orders) được triển khai như thế nào?", "question_type": "CORE"}, {"order": 5, "rag_keyword": null, "question_text": "Trong dự án Inblue, bạn sử dụng Spring Security kết hợp OAuth2. Bạn có thể giải thích luồng đăng nhập cơ bản mà bạn đã cài đặt không?", "question_type": "CORE"}], "phase_name": "Khai thác dự án (Project Deep-dive)", "duration_minutes": 12}, {"questions": [{"order": 6, "rag_keyword": "java_oop_principles", "question_text": "Về ngôn ngữ Java, bạn hãy nêu và giải thích ngắn gọn 4 tính chất cơ bản của lập trình hướng đối tượng (OOP).", "question_type": "CORE"}, {"order": 7, "rag_keyword": "spring_boot_dependency_injection", "question_text": "Trong Spring Boot, Annotation @Autowired dùng để làm gì và nó liên quan như thế nào đến khái niệm Dependency Injection?", "question_type": "CORE"}, {"order": 8, "rag_keyword": "spring_mvc_controller_vs_restcontroller", "question_text": "Bạn có thể phân biệt sự khác nhau cơ bản giữa @Controller và @RestController trong Spring MVC không?", "question_type": "CORE"}, {"order": 9, "rag_keyword": "jpa_hibernate_entity_relationship", "question_text": "Về Hibernate/JPA, bạn thường dùng @OneToMany và @ManyToOne trong trường hợp nào khi thiết kế quan hệ giữa các bảng?", "question_type": "CORE"}, {"order": 10, "rag_keyword": "db_sql_indexing_basics", "question_text": "Trong SQL (PostgreSQL/MSSQL), Index là gì và tại sao chúng ta lại cần sử dụng Index cho các bảng có dữ liệu lớn?", "question_type": "CORE"}, {"order": 11, "rag_keyword": "docker_image_vs_container", "question_text": "JD có yêu cầu về Docker, bạn có thể giải thích Docker Image và Docker Container khác nhau như thế nào không?", "question_type": "CORE"}], "phase_name": "Kiến thức nền tảng (Technical Core)", "duration_minutes": 15}, {"questions": [{"order": 12, "rag_keyword": null, "question_text": "Cảm ơn Khang, buổi phỏng vấn hôm nay đến đây là hết. Bạn có câu hỏi nào dành cho mình về vị trí công việc hoặc dự án của công ty không?", "question_type": "CORE"}], "phase_name": "Kết thúc", "duration_minutes": 1}], "strategy_analysis": "Chiến thuật STANDARD_MOCK tập trung vào việc cân bằng giữa trải nghiệm dự án thực tế của ứng viên và kiến thức nền tảng. Với độ khó FRESHER_BASIC, các câu hỏi sẽ tập trung vào định nghĩa, liệt kê và phân biệt các khái niệm cơ bản trong Java, Spring Boot và Database để kiểm tra độ vững của kiến thức gốc (Foundational Knowledge) trước khi đối chiếu với yêu cầu Senior của JD."}', '{"id": 8, "user": {"id": 21, "name": "Quach Huu Khang (K18 HCM)", "role": "USER", "cvUrl": "https://res.cloudinary.com/dimvyno0z/image/upload/v1776181315/my_app/docs/6bf8aa78-69fd-4ff5-8214-ec991663a6b1.pdf", "email": "khangqhse184031@fpt.edu.vn", "major": null, "isActive": true, "password": null, "avatarUrl": null, "public_id": null, "university": null, "cv_public_id": "my_app/docs/6bf8aa78-69fd-4ff5-8214-ec991663a6b1"}, "tools": ["Git/GitHub/GitLab", "Maven", "Jira", "Swagger", "IntelliJ"], "projects": [{"name": "Movie Theater", "role": "Back-end, Leader", "outcome": "Final score: 9.7", "teamSize": 5, "usedTools": ["ASP.NET Core", "ASP.NET MVC", "PostgreSQL", "SignalR"], "description": "Developed an online movie ticketing system featuring real-time seat map visualization."}, {"name": "BAMBI KITCHEN", "role": "Back-end, Leader", "outcome": null, "teamSize": 6, "usedTools": ["Spring Boot", "Spring Security", "Spring AI", "MSSQL", "Cloudinary", "Firebase Cloud Messaging", "Spring Mail"], "description": "Bambi kitchen is a food chain that specializes in providing healthy dishes and customers can customize and choose personalized dish ingredients step by step, with integrated AI to evaluate orders."}, {"name": "Electronics E-Commerce Platform", "role": "Back-end, Leader", "outcome": null, "teamSize": 5, "usedTools": ["Spring Boot", "Spring Cloud", "PostgreSQL", "RabbitMQ", "PayOS", "Cloudinary", "Feign Client"], "description": "This project involves building an e-commerce platform specializing in accessories. The project utilizes Microservices, Monorepo, CI/CD processes, and a fully automated self-hosted infrastructure."}, {"name": "Inblue - AI Mock Interview & Mentor Platform", "role": "Back-end, Leader", "outcome": null, "teamSize": 5, "usedTools": ["Spring Boot", "Spring Cloud (OpenFeign)", "Spring Security + Oauth2", "PostgreSQL", "PayOS", "Cloudinary", "WebSocket", "Spring Mail", "Dailyco"], "description": "A mock interview platform and expert mentoring connection for IT/Marketing freshers, using AI to optimize interview skills through realistic scenarios and personalized learning paths."}], "createdAt": [2026, 4, 14, 15, 35, 54, 25100000], "updatedAt": [2026, 4, 14, 15, 41, 51, 712183000], "educations": [{"gpa": "3.2", "major": "Software Engineering", "degree": null, "school": "FPT University", "end_date": "2026", "start_date": "2022"}], "softSkills": ["Fast learner", "Adaptability", "Problem-solving", "Teamwork", "Technical Reading", "English Proficiency"], "targetRole": "Java Backend Developer", "targetLevel": "Junior", "achievements": ["HONORABLE STUDENT OF TRIMESTER Semester 1, 3, 4, 5", "Admissions Collaborator - FPT University"], "introduction": "As a Java Developer, I am eager to work in a challenging environment to develop my skills and gain practical experience. I leverage my logical thinking and passion for programming to quickly transform knowledge into practical solutions, aiming to become an effective and well-grounded software development specialist.", "certifications": ["Web Design for Everybody: Basics of Web Development & Coding", "Software Development Lifecycle", "Java FullStack Developer"], "technicalSkills": ["Java", "C#", "HTML/CSS", "Spring Security", "Spring Data JPA", "Spring AI", "Spring API Gateway", "Spring Cloud", "DI/IoC", "ASP .NET", "MSSQL", "PostgreSQL", "JPA/Hibernate", "MongoDB", "RabbitMQ", "Postman", "JUnit", "xUnit", "Docker"], "workExperiences": [{"company": "FPT Software Academy", "end_date": "08/2025", "position": ".NET Developer Intern", "start_date": "05/2025", "description": "Developed an online movie ticketing system featuring real-time seat map visualization."}]}', '{"basic_info": {"job_title": "Backend Developer", "industry_domain": "Information Technology / Software Development", "seniority_level": "Senior"}, "competencies": {"hard_skills": ["Java", "Java EE", "Hibernate", "Spring MVC", "Spring Boot", "Message Queue", "Oracle", "PostgreSQL", "store procedure", "view", "index", "Phân tích và thiết kế hệ thống"], "soft_skills": [], "tools_and_platforms": ["Docker"]}, "responsibilities": ["Tham gia vào quá trình phân tích, thiết kế và xây dựng hệ thống thông tin in-house để đáp ứng nhu cầu của các phòng ban", "Đảm bảo tất cả tài liệu đặc tả kỹ thuật TS, unit test, script phải tuân thủ qui tắc để hệ thống vận hành xuyên suốt và chính xác", "Điều tra (debug) và giải quyết các lỗi phát sinh trong qua trình vận hành hệ thống ngay lập tức nếu có sự cố"]}', '{"history": [{"score": 0.0, "feedback": "Lỗi hệ thống chấm điểm", "answerText": "Phẩy.", "suggestion": "", "questionText": "Chào Khang, mình đã xem qua CV của bạn với rất nhiều dự án thú vị về Microservices và AI. Bạn có thể giới thiệu ngắn gọn về bản thân và định hướng phát triển của bạn với vị trí Java Backend không?", "questionType": "BLUEPRINT", "questionOrder": 0, "behavioralWarnings": []}, {"score": null, "feedback": null, "answerText": "Mình xin giới thiệu ngắn gọn: mình là Khang, có nền tảng vững chắc về **Java Backend** với nhiều kinh nghiệm triển khai **Microservices** và tích hợp các giải pháp **AI** vào hệ thống. Các dự án trước đây của mình tập trung vào việc xây dựng kiến trúc dịch vụ phân tán, tối ưu hiệu năng, và đảm bảo khả năng mở rộng cho hệ thống lớn.  \n\n🎯 **Định hướng phát triển** của mình với vị trí Java Backend:\n- Microservices: Tiếp tục khai thác kiến trúc microservices để xây dựng hệ thống linh hoạt, dễ mở rộng.  \n- Cloud-native: Hướng đến triển khai trên môi trường cloud-native (Docker, Kubernetes) để tận dụng khả năng tự động scale và CI/CD.  \n- AI_integration: Kết hợp AI/ML vào backend nhằm nâng cao trải nghiệm người dùng, ví dụ như gợi ý thông minh hoặc phân tích dữ liệu thời gian thực.  \n- Performance_optimization: Tập trung vào tối ưu hiệu năng, giảm độ trễ và tăng throughput của hệ thống.  \n- Security: Đảm bảo bảo mật dữ liệu và tuân thủ các chuẩn an toàn thông tin.  \n\nMục tiêu dài hạn của mình là trở thành một **Senior Backend Engineer** có khả năng thiết kế kiến trúc hệ thống phức tạp, đồng thời dẫn dắt đội ngũ trong việc áp dụng công nghệ mới để giải quyết các bài toán thực tế.  \n\nBạn có muốn mình chia sẻ thêm chi tiết về các dự án AI hay kinh nghiệm triển khai Microservices không?", "suggestion": null, "questionText": "Có vẻ như bạn vừa gửi nhầm một ký tự hoặc gặp sự cố nhỏ khi nhập liệu. Đừng quá lo lắng nhé, bạn hãy thử giới thiệu lại ngắn gọn về bản thân và chia sẻ về định hướng phát triển của mình với vị trí Java Backend để chúng ta bắt đầu buổi phỏng vấn nhé!", "questionType": "FOLLOW_UP", "questionOrder": 1, "behavioralWarnings": []}, {"score": 0.0, "feedback": "Lỗi hệ thống chấm điểm", "answerText": "Trong dự án Electronics E-Commerce Platform, mình đã thiết kế hệ thống theo kiến trúc Microservices để đảm bảo khả năng mở rộng và dễ dàng bảo trì. Các service chính mà mình đã xây dựng bao gồm:\n\nUser Service: Quản lý thông tin người dùng, đăng ký, đăng nhập, phân quyền và xác thực.\n\nProduct Service: Quản lý danh mục sản phẩm, chi tiết sản phẩm, tồn kho và cập nhật dữ liệu sản phẩm.\n\nOrder Service: Xử lý đơn hàng, trạng thái đơn hàng, lịch sử mua hàng.\n\nPayment Service: Tích hợp cổng thanh toán (PayPal, Stripe, VNPay…), xử lý giao dịch và bảo mật thanh toán.\n\nCart Service: Quản lý giỏ hàng của người dùng, thêm/xóa sản phẩm, tính toán tổng tiền.\n\nRecommendation Service: Áp dụng AI/ML để gợi ý sản phẩm dựa trên hành vi người dùng và lịch sử mua hàng.\n\nNotification Service: Gửi email, SMS hoặc push notification về đơn hàng, khuyến mãi.\n\nReview Service: Quản lý đánh giá, bình luận sản phẩm, giúp cải thiện trải nghiệm người dùng.\n\nAnalytics Service: Thu thập dữ liệu, phân tích hành vi người dùng và hiệu suất hệ thống.\n\nCác service này giao tiếp với nhau thông qua API Gateway và sử dụng Message Queue (Kafka/RabbitMQ) để xử lý bất đồng bộ, đảm bảo hệ thống hoạt động ổn định ngay cả khi lưu lượng tăng cao.", "suggestion": "", "questionText": "Cảm ơn Khang, phần giới thiệu của bạn rất chi tiết và cho thấy một lộ trình phát triển rõ ràng, đặc biệt là tư duy kết hợp AI vào hệ thống Backend để tối ưu trải nghiệm người dùng. Bây giờ, chúng ta hãy cùng đi sâu hơn vào kinh nghiệm thực tế của bạn nhé. Trong dự án Electronics E-Commerce Platform, bạn có sử dụng kiến trúc Microservices. Bạn có thể liệt kê các service chính mà bạn đã xây dựng trong hệ thống này không?", "questionType": "BLUEPRINT", "questionOrder": 2, "behavioralWarnings": []}, {"score": 6.5, "feedback": "Câu trả lời mang tính lý thuyết sách giáo khoa, thiếu các kịch bản xử lý lỗi thực tế và tính nhất quán dữ liệu.", "answerText": "Trong dự án Electronics E-Commerce Platform, RabbitMQ đóng vai trò như một Message Broker trung gian để truyền tin bất đồng bộ giữa các service. Cụ thể:\n\nEvent-driven communication: Khi một service phát sinh sự kiện (ví dụ Order Service tạo đơn hàng mới), sự kiện này sẽ được publish lên RabbitMQ. Các service khác (như Payment Service, Notification Service) sẽ subscribe và xử lý theo nhu cầu.\n\nDecoupling services: RabbitMQ giúp tách biệt logic giữa các service. Order Service không cần biết chi tiết Payment Service xử lý thế nào, chỉ cần gửi thông điệp. Điều này giảm sự phụ thuộc và tăng khả năng mở rộng.\n\nReliability: RabbitMQ hỗ trợ cơ chế xác nhận (acknowledgement) để đảm bảo thông điệp không bị mất. Nếu một consumer gặp lỗi, message có thể được re-queue để xử lý lại.\n\nScalability: Với RabbitMQ, có thể dễ dàng scale các consumer để xử lý khối lượng lớn thông điệp, đặc biệt trong các giai đoạn cao điểm mua sắm.\n\nAsync processing: Các tác vụ nặng như gửi email xác nhận đơn hàng, cập nhật analytics, hoặc gợi ý sản phẩm được xử lý bất đồng bộ qua RabbitMQ, giúp hệ thống phản hồi nhanh hơn cho người dùng.\n\nVí dụ thực tế: Khi người dùng đặt hàng, Order Service publish sự kiện OrderCreated. RabbitMQ sẽ phân phối sự kiện này đến Payment Service để xử lý thanh toán, Notification Service để gửi email xác nhận, và Analytics Service để ghi nhận dữ liệu. Tất cả diễn ra song song mà không làm chậm trải nghiệm của người dùng.", "suggestion": "Keywords:\n- Idempotency\n- Dead Letter Queue (DLQ)\n- Exchange Types (Topic/Fanout)\n- Message Durability\n- Eventual Consistency\n\nStructure:\n- Bước 1: Giải thích cơ chế Routing cụ thể (sử dụng Topic Exchange để phân phối event dựa trên routing key thay vì chỉ nói chung chung).\n- Bước 2: Xử lý Failure Scenarios (Sử dụng Acknowledgement kết hợp với Dead Letter Queue để xử lý các message không thể tiêu thụ, tránh mất dữ liệu).\n- Bước 3: Đảm bảo Data Integrity (Giải quyết vấn đề Duplicate Message bằng Idempotency tại Consumer và quản lý tính nhất quán thông qua Eventual Consistency).\n- Bước 4: Tối ưu Performance (Đề cập đến Message Durability và cách xử lý Backpressure khi Consumer không theo kịp tốc độ của Producer).\n\nSenior Tip: Hãy luôn chuẩn bị để giải thích Trade-off: Tại sao chọn RabbitMQ (phù hợp routing phức tạp, latency thấp) thay vì Kafka (phù hợp throughput cực lớn, log-based) cho bài toán này.", "questionText": "Cảm ơn Khang, bạn đã liệt kê rất chi tiết và bao quát được hầu hết các thành phần cần thiết của một hệ thống E-commerce quy mô lớn. Mình thấy bạn có nhắc đến việc sử dụng Message Queue để xử lý bất đồng bộ. Vậy cụ thể, RabbitMQ đóng vai trò gì trong việc truyền tin giữa các service trong dự án này của bạn?", "questionType": "BLUEPRINT", "questionOrder": 3, "behavioralWarnings": []}, {"score": 4.0, "feedback": "Câu trả lời quá hời hợt, liệt kê tính năng như Product Manager thay vì giải thích kỹ thuật như Senior Engineer.", "answerText": "Trong dự án BAMBI KITCHEN, việc tích hợp Spring AI được sử dụng để hỗ trợ chức năng evaluate orders (đánh giá đơn hàng) nhằm nâng cao trải nghiệm và tối ưu quy trình xử lý. Cụ thể:\n\nOrder validation: AI kiểm tra dữ liệu đơn hàng (số lượng, giá trị, thông tin khách hàng) để phát hiện bất thường như số lượng quá lớn, giá trị bất hợp lý hoặc thông tin thiếu.\n\nFraud detection: Hệ thống AI phân tích hành vi đặt hàng, so sánh với lịch sử giao dịch để phát hiện dấu hiệu gian lận (ví dụ: nhiều đơn hàng từ cùng một IP nhưng khác thông tin khách hàng).\n\nCustomer preference analysis: AI đánh giá đơn hàng dựa trên thói quen mua sắm, từ đó gợi ý các sản phẩm bổ sung hoặc combo phù hợp.\n\nOrder prioritization: AI phân loại đơn hàng theo mức độ ưu tiên (VIP khách hàng, đơn hàng giá trị cao, đơn hàng cần giao gấp) để hỗ trợ hệ thống logistics xử lý nhanh hơn.\n\nFeedback loop: Sau khi đơn hàng được giao, AI phân tích phản hồi của khách hàng để cải thiện mô hình đánh giá, giúp hệ thống ngày càng chính xác hơn.\n\nVề mặt kỹ thuật, Spring AI được tích hợp như một service layer trong hệ thống backend. Khi đơn hàng được tạo, dữ liệu sẽ được gửi đến AI Evaluation Service. Service này sử dụng mô hình ML/AI đã huấn luyện để đưa ra đánh giá (ví dụ: hợp lệ, nghi ngờ gian lận, cần xác minh thêm). Kết quả đánh giá sau đó được trả về cho Order Service để quyết định bước xử lý tiếp theo.", "suggestion": "Keywords: Prompt Engineering, RAG (Retrieval-Augmented Generation), Asynchronous Processing, Token Optimization, LLM Orchestration.\n\nStructure:\n- Technical Stack: Chỉ rõ Spring AI components sử dụng (ChatClient, PromptTemplate, Advisor).\n- Data Pipeline: Cách tiền xử lý dữ liệu đơn hàng và context (Customer History) trước khi đưa vào Prompt.\n- Prompt Strategy: Kỹ thuật thiết kế prompt (Few-shot, Chain-of-Thought) để AI đánh giá chính xác, tránh hallucination.\n- Execution Flow: Luồng xử lý bất đồng bộ (Async/Message Queue) để tránh block Order Service do latency của LLM.\n- Evaluation & Guardrails: Cách kiểm soát output của AI (JSON schema validation) và cơ chế fallback khi AI lỗi.\n\nSenior Tip: Phân tích trade-off giữa độ chính xác của LLM và chi phí/latency, đề xuất giải pháp Hybrid (Rule-based cho validation cơ bản + AI cho fraud/preference).", "questionText": "Cảm ơn Khang, bạn giải thích rất rõ ràng và bao quát được những giá trị cốt lõi mà RabbitMQ mang lại cho hệ thống, đặc biệt là ví dụ về luồng OrderCreated giúp mình dễ hình dung hơn. Bây giờ, chúng ta hãy cùng chuyển sang một dự án khác nhé. Với dự án BAMBI KITCHEN, mình thấy bạn có tích hợp Spring AI. Bạn có thể chia sẻ cụ thể chức năng của AI trong việc đánh giá đơn hàng (evaluate orders) được triển khai như thế nào không?", "questionType": "BLUEPRINT", "questionOrder": 4, "behavioralWarnings": []}, {"score": 5.8, "feedback": "Trả lời quá lý thuyết, thiếu chi tiết triển khai thực tế và các cơ chế bảo mật nâng cao.", "answerText": "Trong dự án Inblue, mình đã triển khai Spring Security kết hợp với OAuth2 để xây dựng luồng đăng nhập an toàn và chuẩn hóa. Luồng cơ bản hoạt động như sau:\n\nUser request login: Người dùng truy cập ứng dụng và chọn đăng nhập bằng một nhà cung cấp (ví dụ Google, Facebook, hoặc Identity Provider nội bộ).\n\nAuthorization request: Ứng dụng chuyển hướng người dùng đến Authorization Server (nhà cung cấp OAuth2) để yêu cầu quyền truy cập.\n\nUser authentication: Người dùng nhập thông tin đăng nhập tại Authorization Server. Nếu hợp lệ, server sẽ cấp Authorization Code.\n\nToken exchange: Ứng dụng backend (Spring Security) gửi Authorization Code đến Authorization Server để đổi lấy Access Token (và có thể kèm Refresh Token).\n\nAccess granted: Với Access Token, ứng dụng có thể gọi các API bảo vệ, đồng thời Spring Security sẽ quản lý session và phân quyền dựa trên token.\n\nResource access: Người dùng được phép truy cập vào các tài nguyên backend (ví dụ: thông tin đơn hàng, dữ liệu cá nhân) theo đúng quyền hạn.\n\nĐiểm quan trọng là Spring Security đảm nhận việc filter request, kiểm tra token trong mỗi lần gọi API, và tự động từ chối nếu token không hợp lệ hoặc hết hạn. Ngoài ra, mình cũng cấu hình role-based access control để phân quyền chi tiết cho từng nhóm người dùng (admin, staff, customer).", "suggestion": "Keywords: PKCE (Proof Key for Code Exchange), JWT (JSON Web Token), State Parameter, SecurityFilterChain, Token Introspection.\n\nStructure:\n- Bước 1: Xác định Grant Type (Authorization Code Grant) và lý do chọn PKCE để chống Authorization Code Interception.\n- Bước 2: Chi tiết cấu hình Spring Security (SecurityFilterChain, OAuth2Client) và cách xử lý Redirect URI.\n- Bước 3: Cơ chế validate Token (Local validation via Public Key vs Remote Introspection) và quản lý Token Lifecycle (Refresh Token rotation).\n- Bước 4: Ánh xạ OAuth2 Scopes sang Spring Security GrantedAuthorities để thực hiện RBAC.\n\nSenior Tip: Phân tích trade-off giữa Stateful (Session-based) và Stateless (JWT-based) và giải pháp xử lý Token Revocation (Blacklisting/Redis).", "questionText": "Cảm ơn Khang, phần giải thích về cách bạn ứng dụng Spring AI để tối ưu hóa quy trình đánh giá đơn hàng rất chi tiết và có tính hệ thống. Bây giờ, chúng ta hãy chuyển sang một khía cạnh khác về bảo mật nhé. Trong dự án Inblue, mình thấy bạn có sử dụng Spring Security kết hợp với OAuth2. Bạn có thể giải thích luồng đăng nhập cơ bản mà bạn đã cài đặt trong dự án đó không?", "questionType": "BLUEPRINT", "questionOrder": 5, "behavioralWarnings": []}, {"score": 4.5, "feedback": "Câu trả lời dừng ở mức định nghĩa sách giáo khoa, thiếu tư duy thiết kế hệ thống và nguyên lý SOLID.", "answerText": "🧩 4 Tính chất OOP trong Java\nEncapsulation\n\nĐóng gói dữ liệu và phương thức liên quan vào cùng một class.\n\nBiến thường được khai báo private, truy cập qua getter/setter.\n\nGiúp ẩn dữ liệu, kiểm soát truy cập và tăng tính bảo mật.\n\nVí dụ: Class BankAccount có biến balance private, chỉ thay đổi qua phương thức deposit().\n\nInheritance\n\nCho phép một class kế thừa thuộc tính và phương thức từ class khác.\n\nGiúp tái sử dụng mã nguồn và xây dựng quan hệ phân cấp.\n\nVí dụ: Class Dog kế thừa từ Animal, có thể dùng lại phương thức eat().\n\nPolymorphism\n\nMột phương thức có thể có nhiều cách thực hiện khác nhau.\n\nCó 2 loại:\n\nCompile-time (Overloading): cùng tên phương thức nhưng khác tham số.\n\nRuntime (Overriding): class con ghi đè phương thức của class cha.\n\nVí dụ: add(int a, int b) và add(double a, double b) cùng tên nhưng khác kiểu dữ liệu.\n\nAbstraction\n\nẨn chi tiết cài đặt, chỉ hiển thị chức năng cần thiết.\n\nThực hiện qua abstract class hoặc interface.\n\nGiúp tập trung vào “cái gì” thay vì “làm thế nào”.\n\nVí dụ: Interface Vehicle có phương thức start(), class Car triển khai chi tiết cách khởi động.", "suggestion": "Keywords: SOLID Principles, Composition over Inheritance, Loose Coupling, Liskov Substitution Principle, Interface-driven Development.\n\nStructure:\n- Liên kết 4 tính chất với mục tiêu cuối cùng: Maintainability và Scalability của hệ thống.\n- Phân tích mỗi tính chất gắn liền với một nguyên lý thiết kế (Ví dụ: Encapsulation -> Single Responsibility).\n- Phân tích Trade-off: Khi nào dùng Inheritance, khi nào dùng Composition.\n- Minh họa bằng Design Pattern thực tế (Ví dụ: Polymorphism trong Strategy Pattern).\n\nSenior Tip: Nhấn mạnh việc ưu tiên ''Composition over Inheritance'' để tránh vấn đề Fragile Base Class trong các hệ thống lớn.", "questionText": "Cảm ơn Khang, bạn giải thích luồng OAuth2 rất rõ ràng và nắm chắc quy trình vận hành của hệ thống bảo mật trong dự án. Bây giờ, chúng ta hãy tạm gác lại phần dự án để kiểm tra một chút về kiến thức nền tảng nhé. Về ngôn ngữ Java, bạn hãy nêu và giải thích ngắn gọn 4 tính chất cơ bản của lập trình hướng đối tượng (OOP) cho mình.", "questionType": "BLUEPRINT", "questionOrder": 6, "behavioralWarnings": []}, {"score": 6.0, "feedback": "Câu trả lời dừng ở mức mô tả tính năng, thiếu phân tích trade-off và xử lý các edge cases thực tế.", "answerText": "Trong Spring Boot, annotation @Autowired được dùng để tự động tiêm (inject) dependency vào một class. Nó liên quan trực tiếp đến khái niệm Dependency Injection trong Spring Framework.\n\n🔑 Cách hoạt động của @Autowired\nAutomatic wiring: Spring sẽ tìm và khởi tạo bean phù hợp trong ApplicationContext, sau đó gán (inject) vào biến hoặc constructor được đánh dấu bằng @Autowired.\n\nDependency Injection: Thay vì developer phải tự tạo đối tượng bằng new, Spring quản lý vòng đời bean và cung cấp đối tượng cần thiết.\n\nFlexibility: Có thể dùng @Autowired trên:\n\nConstructor → đảm bảo dependency luôn được cung cấp khi khởi tạo.\n\nSetter method → cho phép thay đổi dependency sau khi khởi tạo.\n\nField → inject trực tiếp vào biến.\n\n📌 Ví dụ ngắn\njava\n@Service\npublic class OrderService {\n    @Autowired\n    private PaymentService paymentService;\n\n    public void processOrder() {\n        paymentService.pay();\n    }\n}\nỞ đây, Spring sẽ tự động tạo và inject một instance của PaymentService vào OrderService mà không cần new PaymentService().\n\n🎯 Ý nghĩa\nGiúp giảm sự phụ thuộc cứng giữa các class.\n\nTăng khả năng tái sử dụng và kiểm thử (có thể dễ dàng thay thế dependency bằng mock trong unit test).\n\nLà hiện thân của nguyên tắc Inversion of Control (IoC) trong Spring.", "suggestion": "Keywords: Constructor Injection, @Qualifier, Circular Dependency, Immutability, Bean Post-Processor.\n\nStructure:\n- Định nghĩa ngắn gọn @Autowired là cơ chế thực thi IoC/DI.\n- So sánh 3 kiểu Injection: Phân tích tại sao Constructor Injection là best practice (Immutability, tránh NullPointerException, dễ Unit Test) so với Field Injection.\n- Giải quyết xung đột: Cách xử lý khi có nhiều Bean cùng type (@Qualifier, @Primary).\n- Xử lý nâng cao: Đề cập Circular Dependency và cách giải quyết (@Lazy).\n\nSenior Tip: Nhấn mạnh việc Field Injection gây khó khăn cho Unit Test vì phụ thuộc vào Spring Context (Reflection), trong khi Constructor Injection cho phép khởi tạo POJO thuần túy.", "questionText": "Cảm ơn Khang, phần giải thích về 4 tính chất OOP của bạn rất đầy đủ, chính xác và có ví dụ minh họa rất rõ ràng. Có vẻ như bạn nắm rất chắc nền tảng Java. Bây giờ, chúng ta sẽ chuyển sang một chút về Framework nhé. Trong Spring Boot, bạn có biết Annotation @Autowired dùng để làm gì và nó liên quan như thế nào đến khái niệm Dependency Injection không?", "questionType": "BLUEPRINT", "questionOrder": 7, "behavioralWarnings": []}, {"score": 6.0, "feedback": "Câu trả lời dừng ở mức mô tả, thiếu phân tích cơ chế vận hành (under-the-hood) và luồng xử lý dữ liệu.", "answerText": "Trong Spring MVC, cả @Controller và @RestController đều được dùng để định nghĩa lớp xử lý request, nhưng chúng có sự khác biệt cơ bản về cách trả dữ liệu:\n\n@Controller\n\nDùng cho các ứng dụng web truyền thống, nơi response thường là View (HTML, JSP, Thymeleaf).\n\nKhi một phương thức trong @Controller trả về String, Spring sẽ hiểu đó là tên của view để render.\n\nNếu muốn trả về dữ liệu JSON/XML, cần kết hợp với @ResponseBody trên phương thức hoặc cấu hình thêm.\n\n@RestController\n\nLà một biến thể của @Controller, được thiết kế cho RESTful API.\n\nBản chất là @Controller + @ResponseBody.\n\nMọi phương thức trong @RestController mặc định trả về dữ liệu (JSON/XML) trực tiếp cho client, thay vì tìm view để render.\n\nThường dùng trong các ứng dụng backend cung cấp API cho frontend hoặc mobile app.", "suggestion": "Keywords: HttpMessageConverter, ViewResolver, DispatcherServlet, Content-Negotiation, SSR vs CSR.\n\nStructure:\n- Cơ chế @Controller: DispatcherServlet -> HandlerAdapter -> ViewResolver -> Render HTML (SSR).\n- Cơ chế @RestController: DispatcherServlet -> HandlerAdapter -> HttpMessageConverter -> Write directly to Response Body (CSR).\n- So sánh luồng đi của dữ liệu: View-based vs Data-based.\n- Ngữ cảnh áp dụng: Monolithic (SSR) vs Microservices/Decoupled Architecture (API).\n\nSenior Tip: Đề cập đến Content-Negotiation để giải thích cách Spring chọn Converter dựa trên header ''Accept'' của request.", "questionText": "Cảm ơn Khang, câu trả lời của bạn rất xuất sắc và chi tiết. Bạn không chỉ nắm vững khái niệm mà còn hiểu rõ các cách áp dụng thực tế cũng như vai trò của nó trong kiến trúc Spring. Tiếp theo, chúng ta sẽ đi sâu hơn một chút vào phần Web. Bạn có thể phân biệt sự khác nhau cơ bản giữa @Controller và @RestController trong Spring MVC không?", "questionType": "BLUEPRINT", "questionOrder": 8, "behavioralWarnings": []}, {"score": 4.5, "feedback": "Câu trả lời dừng ở mức Junior; thiếu phân tích về hiệu năng, N+1 và quản lý vòng đời entity.", "answerText": "Trong Hibernate/JPA, hai annotation @OneToMany và @ManyToOne được dùng để mô tả quan hệ giữa các bảng (entity) trong cơ sở dữ liệu. Chúng thường đi đôi với nhau để thể hiện mối quan hệ cha–con:\n\n@OneToMany\n\nDùng khi một entity có thể liên kết với nhiều entity khác.\n\nVí dụ: Một Customer có thể có nhiều Order.\n\nTrong class Customer, ta khai báo:\n\njava\n@OneToMany(mappedBy = \"customer\")\nprivate List<Order> orders;\n@ManyToOne\n\nDùng khi một entity thuộc về một entity khác.\n\nVí dụ: Một Order chỉ thuộc về một Customer.\n\nTrong class Order, ta khai báo:\n\njava\n@ManyToOne\n@JoinColumn(name = \"customer_id\")\nprivate Customer customer;\n📌 Ý nghĩa trong thiết kế\n@OneToMany → thể hiện quan hệ \"một-nhiều\" từ phía cha (Customer → Orders).\n\n@ManyToOne → thể hiện quan hệ \"nhiều-một\" từ phía con (Order → Customer).\n\nKhi kết hợp, chúng giúp Hibernate/JPA hiểu rõ cấu trúc quan hệ và tự động quản lý foreign key trong database.\n\n👉 Tóm lại:\n\nDùng @OneToMany ở entity cha để quản lý danh sách con.\n\nDùng @ManyToOne ở entity con để tham chiếu về cha.\n\nHai annotation này thường đi cùng nhau để mô tả đầy đủ quan hệ hai chiều.\n\nBạn có muốn mình minh họa chi tiết hơn bằng một ví dụ thực tế với bảng Customer và Order, bao gồm cả cấu trúc bảng SQL và entity mapping trong Java không?", "suggestion": "Keywords: N+1 Problem, FetchType (LAZY/EAGER), CascadeType, Owning Side, Orphan Removal.\n\nStructure:\n- Xác định Owning Side (@ManyToOne) và Inverse Side (@OneToMany với mappedBy) để tối ưu hóa câu lệnh SQL.\n- Phân tích Fetch Strategy: Giải thích tại sao dùng LAZY mặc định và cách xử lý N+1 Problem (JOIN FETCH, EntityGraph).\n- Quản lý vòng đời: Áp dụng CascadeType và orphanRemoval để đồng bộ trạng thái giữa cha và con.\n- Trade-off: So sánh Bidirectional vs Unidirectional (vấn đề circular reference khi serialize JSON).\n\nSenior Tip: Đề cập đến việc tránh dùng List cho collection lớn trong @OneToMany để ngăn chặn việc load toàn bộ dữ liệu vào memory, thay thế bằng Pagination hoặc Query riêng.", "questionText": "Câu trả lời của bạn rất chính xác và đầy đủ, bạn đã phân biệt rõ ràng về cơ chế trả về dữ liệu cũng như mục đích sử dụng của hai annotation này. Bây giờ, chúng ta hãy chuyển sang phần làm việc với cơ sở dữ liệu nhé. Về Hibernate/JPA, bạn thường dùng @OneToMany và @ManyToOne trong trường hợp nào khi thiết kế quan hệ giữa các bảng?", "questionType": "BLUEPRINT", "questionOrder": 9, "behavioralWarnings": []}, {"score": 6.0, "feedback": "Câu trả lời dừng ở mức cơ bản, thiếu tư duy tối ưu hóa thực tế và phân tích sâu về Execution Plan.", "answerText": "Trong SQL (PostgreSQL/MSSQL), Index là một cấu trúc dữ liệu đặc biệt (thường dựa trên B-Tree, hoặc các dạng khác như Hash, GiST, GIN) được tạo ra để tăng tốc độ truy vấn dữ liệu trên bảng. Nó hoạt động giống như mục lục trong sách: thay vì phải đọc toàn bộ bảng (table scan), hệ quản trị cơ sở dữ liệu có thể dùng index để tìm nhanh đến vị trí dữ liệu cần thiết.\n\n🔑 Vai trò của Index\nTăng tốc truy vấn: Giúp các câu lệnh SELECT, JOIN, WHERE, ORDER BY chạy nhanh hơn trên bảng lớn.\n\nGiảm chi phí I/O: Hạn chế việc đọc toàn bộ dữ liệu từ disk, chỉ truy cập phần cần thiết.\n\nHỗ trợ tìm kiếm nhanh: Đặc biệt hữu ích với các cột thường xuyên được lọc (WHERE) hoặc sắp xếp (ORDER BY).\n\nTối ưu join: Khi join nhiều bảng, index trên khóa ngoại giúp hệ thống tìm và ghép dữ liệu nhanh hơn.\n\n📌 Ví dụ thực tế\nBảng Orders có hàng triệu bản ghi. Nếu thường xuyên truy vấn theo customer_id, ta tạo index:\n\nsql\nCREATE INDEX idx_orders_customer_id ON Orders(customer_id);\n→ Khi chạy SELECT * FROM Orders WHERE customer_id = 123;, hệ thống sẽ dùng index thay vì quét toàn bộ bảng.\n\n⚠️ Lưu ý khi dùng Index\nChi phí ghi dữ liệu: Mỗi lần INSERT, UPDATE, DELETE, index cũng phải cập nhật → làm chậm thao tác ghi.\n\nDung lượng lưu trữ: Index chiếm thêm không gian trên disk.\n\nChọn lọc hợp lý: Không nên tạo quá nhiều index, chỉ nên đặt ở các cột thường xuyên dùng trong truy vấn.\n\n👉 Tóm lại: Index là công cụ tăng tốc truy vấn trên bảng dữ liệu lớn, nhưng cần cân nhắc giữa tốc độ đọc và chi phí ghi.\n\nBạn có muốn mình phân tích chi tiết hơn về các loại index trong PostgreSQL (B-Tree, Hash, GiST, GIN, BRIN) và khi nào nên dùng từng loại không?", "suggestion": "Keywords: Execution Plan (EXPLAIN ANALYZE), Cardinality/Selectivity, Composite Index (Leftmost Prefix), Covering Index, Index-Only Scan.\n\nStructure:\n- Cơ chế vận hành: B-Tree/LSM-Tree và cách Query Optimizer quyết định dùng Index dựa trên Statistics.\n- Chiến lược tối ưu: Phân tích Selectivity (độ chọn lọc) để chọn cột đánh index; sử dụng Composite Index cho đa điều kiện.\n- Kỹ thuật nâng cao: Covering Index để đạt Index-Only Scan (loại bỏ Heap fetch).\n- Trade-off & Maintenance: Write Amplification, Index Bloat và chiến lược Reindex/Vacuum.\n\nSenior Tip: Phải đề cập đến ''Leftmost Prefix Rule'' khi dùng Composite Index và giải thích tại sao Index trên cột có Cardinality thấp (ví dụ: Gender) thường bị Optimizer bỏ qua.", "questionText": "Cảm ơn bạn, câu trả lời của bạn rất chi tiết và chính xác, đặc biệt là việc bạn nêu rõ được vai trò của mappedBy và JoinColumn nên mình không cần minh họa thêm nữa. Bây giờ, chúng ta hãy cùng chuyển sang một chủ đề khác về cơ sở dữ liệu nhé. Trong SQL (PostgreSQL/MSSQL), Index là gì và tại sao chúng ta lại cần sử dụng Index cho các bảng có dữ liệu lớn?", "questionType": "BLUEPRINT", "questionOrder": 10, "behavioralWarnings": []}, {"score": 5.5, "feedback": "Câu trả lời dừng ở mức định nghĩa cơ bản, thiếu hoàn toàn cơ chế vận hành kỹ thuật bên dưới.", "answerText": "Trong hệ sinh thái Docker, khái niệm Image và Container là hai thành phần cốt lõi nhưng khác nhau về bản chất:\n\nDocker Image\n\nLà một mẫu (blueprint) bất biến, chứa toàn bộ ứng dụng, thư viện, dependencies và cấu hình cần thiết để chạy.\n\nĐược xây dựng từ Dockerfile.\n\nImage chỉ là read-only, không thay đổi trong quá trình chạy.\n\nVí dụ: Một image có thể chứa ứng dụng Spring Boot cùng với JDK và Tomcat.\n\nDocker Container\n\nLà một instance đang chạy được tạo ra từ Docker Image.\n\nContainer có thể thay đổi trạng thái (ghi dữ liệu, log, file tạm thời).\n\nNhiều container có thể được tạo từ cùng một image, mỗi container hoạt động độc lập.\n\nVí dụ: Từ image Spring Boot, ta có thể chạy nhiều container phục vụ các môi trường khác nhau (dev, test, prod).\n\n📌 Điểm khác biệt chính\nKhía cạnh\tDocker Image\tDocker Container\nBản chất\tMẫu (template), read-only\tInstance đang chạy, có trạng thái\nTạo ra từ\tDockerfile\tDocker Image\nKhả năng thay đổi\tKhông thay đổi\tCó thể thay đổi trong runtime\nVai trò\tĐịnh nghĩa ứng dụng\tThực thi ứng dụng\n\n\n👉 Tóm lại: Image là công thức, Container là sản phẩm được nấu ra từ công thức đó.  \nImage định nghĩa ứng dụng, còn Container chính là môi trường thực thi ứng dụng đó.", "suggestion": "Keywords: Union File System (UnionFS), Copy-on-Write (CoW), Ephemeral Storage, Multi-stage Build, Container Runtime.\n\nStructure:\n- High-level: Phân biệt Blueprint (Image) vs Runtime Instance (Container).\n- Deep Dive Storage: Giải thích cơ chế Layering của Image và cách Container thêm một ''Writable Layer'' thông qua Copy-on-Write (CoW).\n- State Management: Phân tích tính chất Ephemeral (tạm thời) của Container và giải pháp Persistent Volume để lưu trữ dữ liệu.\n- Production Optimization: Đề cập đến việc tối ưu Image size (Multi-stage build) để tăng tốc độ deployment.\n\nSenior Tip: Mở rộng về bảo mật bằng cách đề cập đến Distroless Images để giảm attack surface.", "questionText": "Câu trả lời của bạn rất xuất sắc và toàn diện, bạn không chỉ nắm vững lý thuyết mà còn hiểu rõ những đánh đổi (trade-off) về hiệu năng ghi và dung lượng lưu trữ khi dùng Index. Mình sẽ không đi sâu thêm vào các loại Index nữa để dành thời gian cho các phần tiếp theo. Bây giờ, chúng ta hãy chuyển sang một yêu cầu khác trong JD nhé: Bạn có thể giải thích Docker Image và Docker Container khác nhau như thế nào không?", "questionType": "BLUEPRINT", "questionOrder": 11, "behavioralWarnings": []}, {"score": 1.0, "feedback": "Thất bại hoàn toàn trong việc thể hiện sự chủ động và tư duy chiến lược để đánh giá sự phù hợp.", "answerText": "mình ko", "suggestion": "Keywords:\nEngineering Culture, Technical Roadmap, Scalability Challenges, Team Topology, Success Metrics\n\nStructure:\n- Bước 1: Hỏi về thách thức kỹ thuật (Ví dụ: ''Thách thức lớn nhất về scalability mà team đang đối mặt là gì?'').\n- Bước 2: Hỏi về quy trình và văn hóa kỹ thuật (Ví dụ: ''Quy trình CI/CD và Code Review tại đây được thực hiện như thế nào?'').\n- Bước 3: Hỏi về kỳ vọng và tác động (Ví dụ: ''KPI hoặc thước đo thành công cho vị trí này trong 6 tháng đầu là gì?'').\n\nSenior Tip: Hãy coi đây là cơ hội ''reverse interview'' để đánh giá xem tiêu chuẩn kỹ thuật của công ty có xứng tầm với bạn hay không.", "questionText": "Câu trả lời của bạn rất chi tiết và dễ hiểu, đặc biệt là ví dụ về ''công thức'' và ''món ăn'' giúp làm rõ bản chất của Image và Container. Cảm ơn Khang, buổi phỏng vấn hôm nay đến đây là hết. Bạn có câu hỏi nào dành cho mình về vị trí công việc hoặc dự án của công ty không?", "questionType": "BLUEPRINT", "questionOrder": 12, "behavioralWarnings": []}], "improvementPlan": null, "aiOverviewFeedback": "Đã chấm điểm xong."}', '{"domain": "IT", "language": "VI", "difficulty": "FRESHER_BASIC", "interview_mode": "STANDARD_MOCK", "duration_minutes": 30}', null),
        (92, null, 9, null, '2026-08-07 10:50:38.135536', '2026-08-08 10:09:49.931347', 'IT', 'CANCELLED', 'STANDARD_MOCK', null, '0a30eee9-b1de-46f4-9369-1f9fc3f7f7c1', null, '{"id": 24, "tools": ["Git", "GitHub", "GitLab", "Maven", "Jira", "Swagger", "Docker", "Postman", "JUnit", "xUnit"], "projects": [{"name": "Movie Theater", "role": "Back-end, Leader", "outcome": "Final score: 9.7", "teamSize": 5, "usedTools": ["ASP.NET Core", "ASP.NET MVC", "PostgreSQL", "SignalR", "GitHub"], "description": "An online movie ticketing system featuring real-time seat map visualization and modules for movie, showtimes, theaters, promotions, and user accounts."}, {"name": "CHILD VACCINE SCHEDULE TRACKING SYSTEM", "role": "Back-end, Leader", "outcome": "Supports individual/group scheduling, automatic reminders, secure payments, and AI-powered customer support.", "teamSize": 3, "usedTools": ["Java", "Spring Boot", "Spring Security", "Spring AI", "MSSQL", "Spring Mail"], "description": "A web application that manages children''s vaccination schedules, allowing parents and health centers to schedule, track, and update vaccination records."}, {"name": "BAMBI KITCHEN", "role": "Back-end, Leader", "outcome": "Implemented JWT/OAuth2 authentication, warehouse management, multi-channel payment (Cash, Momo, VNPAY) and AI integration via Gemini AI.", "teamSize": 6, "usedTools": ["Spring Boot", "Spring Security", "Spring AI", "MSSQL", "Cloudinary", "Firebase Cloud Messaging", "Spring Mail"], "description": "A healthy food chain application where customers can customize dish ingredients step by step with integrated AI for order evaluation."}], "createdAt": [2026, 8, 4, 16, 14, 33, 422891000], "updatedAt": [2026, 8, 4, 16, 14, 33, 422919000], "educations": [{"gpa": "3.2", "major": "Software Engineering", "degree": null, "school": "FPT University", "end_date": "2026", "start_date": "2022"}], "softSkills": ["Technical Reading Proficiency in English", "Fast learner", "adaptability", "problem-solving", "teamwork"], "targetRole": "Java Developer", "targetLevel": "Intern", "achievements": ["Honorable Student of Trimester (Semester 1, 3, 4, 5)", "Admissions Collaborator - FPT University"], "introduction": "As a Java Developer, I am eager to work in a challenging environment to develop my skills and gain practical experience. I leverage my logical thinking and passion for programming to quickly transform knowledge into practical solutions, aiming to become an effective and well-grounded software development specialist.", "applicationId": 115, "certifications": ["Web Design for Everybody: Basics of Web Development & Coding", "Software Development Lifecycle", "Java FullStack Developer"], "technicalSkills": ["Java", "C#", "HTML/CSS", "Spring Security", "Spring Data JPA", "Spring MVC", "Validation", "DI/IoC", "ASP .NET", "MSSQL", "PostgreSQL", "JPA/Hibernate", "MongoDB"], "workExperiences": [{"company": "FPT Software Academy", "end_date": "08/2025", "position": ".NET Developer Intern", "start_date": "05/2025", "description": "Worked as a Back-end Leader for the Movie Theater project. Developed an online movie ticketing system with real-time seat map visualization and various management modules. Designed database and processing flow architecture."}]}', '{"basic_info": {"job_title": "Junior Java Backend Developer", "industry_domain": "AI / Software Development", "seniority_level": "Junior"}, "competencies": {"hard_skills": ["Java", "Backend Development", "RESTful APIs", "Database query optimization", "Microservices"], "soft_skills": ["passionate"], "tools_and_platforms": []}, "responsibilities": ["Building scalable RESTful APIs", "Optimizing database queries", "Integrating microservices for an AI-driven platform"]}', null, '{"domain": "IT", "language": "VI", "difficulty": "FRESHER_BASIC", "interview_mode": "STANDARD_MOCK", "duration_minutes": 20}', 287),
        (17, null, 5, null, '2026-04-12 16:00:11.394809', '2026-04-13 01:54:25.448364', 'IT', 'CANCELLED', 'STANDARD_MOCK', null, '509332bf-6210-466a-8df7-ceffce7a39e6', null, '{"id": 6, "user": {"id": 5, "name": "Trần Bình An", "role": "USER", "cvUrl": "https://res.cloudinary.com/dimvyno0z/image/upload/v1775745501/my_app/docs/5cbc1648-7684-468b-a546-3719047a22bc.pdf", "email": "binhan@gmail.com", "major": "CNTT", "isActive": true, "password": "123", "avatarUrl": "https://res.cloudinary.com/dimvyno0z/image/upload/v1773564900/my_app/images/koljabyfgesxt5ptp8u5.jpg", "public_id": "my_app/images/koljabyfgesxt5ptp8u5", "university": "ĐH Bách Khoa TPHCM", "cv_public_id": "my_app/docs/5cbc1648-7684-468b-a546-3719047a22bc"}, "tools": ["Git/GitHub/GitLab", "Maven", "Jira", "Swagger", "Docker", "Postman", "JUnit", "xUnit", "Cloudinary", "Firebase Cloud Messaging"], "projects": [{"name": "CHILD VACCINE SCHEDULE TRACKING SYSTEM", "role": "Back-end, Leader", "outcome": "Schedule vaccination, payment, evaluation, update post-vaccination reactions. Track vaccination progress & vaccination history. The facility records vaccination results in the child''s records. The system automatically sends reminder and notification emails. Manage vaccines in stock, users, booking schedules, ...", "teamSize": 3, "usedTools": ["Java", "Spring Boot", "Spring Security", "Spring AI", "MSSQL", "Spring Mail"], "description": "A web application that manages children''s vaccination schedules, allowing parents and health centers to schedule, track, and update vaccination records. Supports individual/group scheduling, automatic reminders, secure payments, and AI-powered customer support."}, {"name": "BAMBI KITCHEN", "role": "Back-end, Leader", "outcome": "Authorization & Authentication ( JW, OAuth2 Google ). Manage menus & recipes. Raw material warehouse management (Inventory, Import/Export, Warning). Order (Custom dishes & available dishes) with ingredient reservation system. Multi-channel payment (Cash, Momo, VNPAY). AI intergration ( Gemini AI - Nutrition & Recommend ).", "teamSize": 6, "usedTools": ["Spring Boot", "Spring Security", "Spring AI", "MSSQL", "Cloudinary", "Firebase Cloud Messaging", "Spring Mail"], "description": "Bambi kitchen is a food chain that specializes in providing healthy dishes and customers can customize and choose personalized dish ingredients step by step, with integrated AI to evaluate orders."}], "createdAt": [2026, 4, 9, 14, 38, 18, 734762000], "updatedAt": [2026, 4, 9, 14, 38, 22, 582891000], "educations": [{"gpa": "3.2", "major": "Software Engineering", "degree": null, "school": "FPT University", "end_date": "2026", "start_date": "2022"}], "softSkills": ["Teamwork", "English", "Fast learner", "Adaptability", "Problem-solving", "Technical Reading"], "targetRole": "Java Developer", "targetLevel": "Junior", "achievements": ["HONORABLE STUDENT OF TRIMESTER Semester 1, 3, 4, 5", "Admissions Collaborator -FPT University"], "introduction": "As a Java Developer, I am eager to work in a challenging environment to develop my skills and gain practical experience. I leverage my logical thinking and passion for programming to quickly transform knowledge into practical solutions, aiming to become an effective and well-grounded software development specialist.", "certifications": ["Web Design for Everybody: Basics of Web Development & Coding", "Software Development Lifecycle", "Java FullStack Developer"], "technicalSkills": ["Java", "C#", "HTML/CSS", "Spring Security", "Spring Data JPA", "Spring MVC", "MSSQL", "PostgreSQL", "JPA/Hibernate", "MongoDB", "ASP .NET", "SignalR", "Spring Boot", "Spring AI"], "workExperiences": [{"company": "FPT Software Academy", "end_date": "08/2025", "position": ".NET Developer Intern", "start_date": "05/2025", "description": "Final Training Project: Movie Theater. Role: Back-end, Leader. Developed an online movie ticketing system featuring real-time seat map visualization. Developed modules: movie management, showtimes, theaters, promotions, user accounts, and points accumulation. Authorization & Authentication (Cookie Authentication). Designed the entire database and processing flow architecture for the modules. Actively learned and mastered all modules, acted as a connection point between sections, divided tasks and guided the team to implement code according to the design. Performed work under the supervision of the mentor, ensuring project progress and quality."}]}', '{"basic_info": {"job_title": null, "industry_domain": "Công nghệ thông tin", "seniority_level": null}, "competencies": {"hard_skills": ["Java", "Spring Boot"], "soft_skills": [], "tools_and_platforms": []}, "responsibilities": []}', null, '{"domain": "IT", "language": "VI", "difficulty": "FRESHER_BASIC", "interview_mode": "STANDARD_MOCK", "duration_minutes": 15}', null),
