        (4, null, 14, null, '2026-03-15 09:35:01.807894', '2026-03-15 12:51:00.251128', 'IT', 'CANCELLED', 'THEORY_CHECK', null, 'a5960a60-0fed-4dc4-a082-723611f59b2f', null, '{"id": 3, "user": {"id": 14, "name": "Thu Hồng", "role": "USER", "cvUrl": "https://res.cloudinary.com/dimvyno0z/raw/upload/v1773567119/my_app/docs/c81a07f2-f16a-453b-ba50-fc3a2067b85d.pdf", "email": "hong4@gmail.com", "major": "CNTT", "isActive": true, "password": "12345", "avatarUrl": null, "public_id": null, "university": "UIT", "cv_public_id": "my_app/docs/c81a07f2-f16a-453b-ba50-fc3a2067b85d.pdf"}, "tools": ["Git/GitHub", "Maven", "Trello", "Jira", "Swagger", "Postman", "JUnit", "Selenium", "k6", "Vercel", "Ngrok", "Render", "Cloudflare", "Spring Boot Actuator", "Prometheus", "Grafana", "API Gateway", "Eureka", "Config Server", "Load Balancing", "FeignClient", "RestTemplate", "WebClient"], "projects": [{"name": "Online Food Ordering App", "role": "Backend Developer & Architecture Contributor", "outcome": "Reduced email notification latency by ~40% through asynchronous processing. Delivered full-feature MVP ahead of schedule, improving booking usability and reducing internal test errors by over 25%.", "teamSize": 4, "usedTools": ["Java", "Spring Boot", "Spring Security", "Spring AI", "MSSQL", "Maven"], "description": "A microservices-based food ordering platform supporting order, payment, and inventory management with real-time communication and event-driven scalability."}, {"name": "Child Vaccine Schedule Tracking System", "role": "Backend Lead & Developer, UI Designer", "outcome": "Developed 15+ RESTful APIs with flexible booking options and asynchronous email notifications to reduce response time. Implemented OAuth2 authentication, payment workflows, cancellation tracking, and booking data validation. Integrated GPT-3.5 chatbot via Spring AI for automated customer support.", "teamSize": 3, "usedTools": ["Java", "Spring Boot", "Spring Security", "Spring AI", "MSSQL"], "description": "A web app for managing child vaccination schedules, allowing parents and health centers to book, track, and update vaccination records. Supports individual/group bookings, automated reminders, secure payments, and AI-powered customer support."}, {"name": "Development of an aviation data pipeline on AWS", "role": null, "outcome": "Successfully worked in a real-world project environment for an international client. Contributed to the release of a complex pipeline processing 4 schemas & 200+ tables on AWS. Strengthened understanding of cloud-based data processing workflows. Enhanced skills in integration testing and cross-functional team collaboration.", "teamSize": null, "usedTools": ["AWS (S3, Glue, Airflow, DynamoDB, Redshift)", "Snowflake", "JIRA"], "description": "Participated in testing a large-scale cloud-based data pipeline system for a Japanese aviation client, ensuring data integrity, reliability, and compliance with business requirements."}], "createdAt": [2026, 3, 15, 9, 31, 56, 958837000], "updatedAt": [2026, 3, 15, 9, 32, 50, 967844000], "educations": [{"gpa": "3.0", "major": "Software Engineer", "degree": null, "school": "FPT University", "end_date": "2026", "start_date": "2022"}], "softSkills": ["Fast learner", "Collaboration", "Problem-solving", "Adaptability", "English (Fluent in technical reading, conversational)"], "targetRole": "Java Backend Developer", "targetLevel": "Fresher", "achievements": [], "introduction": "Proactive and adaptable Software Engineering student passionate about Java backend development, with hands-on experience in Spring Framework, microservices architecture, and cloud deployment through academic projects and internships. Skilled in designing and deploying scalable systems using Spring Boot, RESTful APIs, and Microservices. Short-term, I aim to excel as a Junior Java Developer; long-term, to become a Software Architect. I''m committed to staying updated on emerging technologies like AI integration and cloud-native solutions to bring fresh ideas to collaborative teams.", "certifications": ["Coursera - Software Development, Java Full Stack Developer, Java Testing", "FPT Software Academy - Azure Cloud Fundamentals, Software Testing"], "technicalSkills": ["Java", "Spring Boot", "Spring Security", "Spring AI", "Spring MVC", "Spring Data JPA", "RESTful API", "Microservices Architecture", "Event-Driven Architecture (EDA)", "Saga Pattern", "RabbitMQ", "MSSQL", "PostgreSQL", "JPA/Hibernate", "Redshift", "Snowflake", "DynamoDB", "MongoDB", "Docker", "AWS", "Azure", "OAuth2", "JWT"], "workExperiences": [{"company": "FPT Software", "end_date": "08/2025", "position": "Data Quality Assurance Intern", "start_date": "05/2025", "description": "Participated in testing a large-scale cloud-based data pipeline system for a Japanese aviation client, ensuring data integrity, reliability, and compliance with business requirements."}]}', '{"basic_info": {"job_title": "Phát triển Microservice Backend", "industry_domain": "Công nghệ thông tin", "seniority_level": "Senior"}, "competencies": {"hard_skills": ["Java", "Spring framework", "Spring core", "Spring sercuity", "Spring boot", "Thiết kế API", "Phát triển API", "Bảo mật hệ thống", "OAuth2", "OpenID Connect", "JWT", "SSO", "mTLS", "MySQL", "Redis", "MongoDB", "PostgreSQL", "Kafka"], "soft_skills": ["Phân tích", "Giải quyết vấn đề", "Giao tiếp", "Làm việc nhóm", "Phối hợp", "Chủ động học hỏi"], "tools_and_platforms": ["Docker", "Kubernetes", "Jenkins", "GitLab CI", "ArgoCD", "Oracle", "Sqlserver", "PostgreSQL", "Mongodb", "Swagger", "OpenAPI"]}, "responsibilities": ["Phát triển microservice backend theo yêu cầu của BA", "Thiết kế và phát triển giải pháp tích hợp dựa trên kiến trúc microservice", "Xây dựng, tối ưu API, dịch vụ web (SOAP/REST, gRPC, GraphQL)", "Đảm bảo tính bảo mật, khả năng mở rộng và hiệu năng trong các giải pháp tích hợp", "Viết tài liệu kỹ thuật, hướng dẫn sử dụng"]}', null, '{"domain": "IT", "language": "VI", "difficulty": "FRESHER_ADVANCED", "interview_mode": "THEORY_CHECK", "duration_minutes": 15}', null),
