        (12, null, 2, null, '2026-03-19 14:51:36.465846', '2026-03-21 04:58:12.206782', 'IT', 'CANCELLED', 'STANDARD_MOCK', null, '045a9a20-55fa-4e99-ac3c-c3793af01728', null, '{"id": 1, "user": {"id": 2, "name": "THU HA NGUYEN PHAM", "role": "USER", "cvUrl": "https://res.cloudinary.com/dimvyno0z/raw/upload/v1772876158/my_app/docs/a17ef5f4-506b-4e14-a9ab-74e2a851af2d.pdf", "email": null, "major": "CNTT", "isActive": true, "password": null, "avatarUrl": "https://res.cloudinary.com/dimvyno0z/image/upload/v1772820944/my_app/images/t6hzjlhcmuj8sq7drhm4.png", "public_id": "my_app/images/t6hzjlhcmuj8sq7drhm4", "university": "fpt", "cv_public_id": "my_app/docs/a17ef5f4-506b-4e14-a9ab-74e2a851af2d.pdf"}, "tools": ["Git/GitHub/GitLab", "Maven", "Jira", "Swagger", "Postman"], "projects": [{"name": "Child Vaccine Schedule Tracking System", "role": "Leader, Back-end", "outcome": null, "teamSize": 3, "usedTools": ["Spring Boot", "React Js", "SQL Server"], "description": "Vaccination scheduling, payments, service reviews, and post-injection reaction updates. Track vaccination progress and view immunization history. Allows medical facilities to record vaccination results into a child''s profile. Dashboard & Reporting. Automated email reminders and notifications. Management of vaccine inventory, users, appointments, etc."}, {"name": "Smart Wallet", "role": "Leader, Back-end", "outcome": null, "teamSize": 3, "usedTools": ["Spring Boot", "React", "SQL Server"], "description": "Manage income and expenditure, helping users track income, expenditure and consumption appropriately. Allow users to classify income and expenditure and create budgets and track income and expenditure according to the budget. The home page is intuitive and easy to observe."}, {"name": "Product Information", "role": null, "outcome": null, "teamSize": null, "usedTools": ["MVC", "JSP", "tomcat", "session", "filterchain", "JDBC", "cookie"], "description": "Manage products by category. Add favorite products. Basic C