        (14, null, 5, null, '2026-04-09 14:39:22.858993', '2026-04-11 23:09:52.851513', 'IT', 'CANCELLED', 'STANDARD_MOCK', null, 'c9caa572-99ff-4353-ade0-aa7c0adef30c', null, '{"id": 6, "user": {"id": 5, "name": "Trần Bình An", "role": "USER", "cvUrl": "https://res.cloudinary.com/dimvyno0z/image/upload/v1775745501/my_app/docs/5cbc1648-7684-468b-a546-3719047a22bc.pdf", "email": "binhan@gmail.com", "major": "CNTT", "isActive": true, "password": "123", "avatarUrl": "https://res.cloudinary.com/dimvyno0z/image/upload/v1773564900/my_app/images/koljabyfgesxt5ptp8u5.jpg", "public_id": "my_app/images/koljabyfgesxt5ptp8u5", "university": "ĐH Bách Khoa TPHCM", "cv_public_id": "my_app/docs/5cbc1648-7684-468b-a546-3719047a22bc"}, "tools": ["Git/GitHub/GitLab", "Maven", "Jira", "Swagger", "Docker", "Postman", "JUnit", "xUnit", "Cloudinary", "Firebase Cloud Messaging"], "projects": [{"name": "CHILD VACCINE SCHEDULE TRACKING SYSTEM", "role": "Back-end, Leader", "outcome": "Schedule vaccination, payment, evaluation, update post-vaccination reactions. Track vaccination progress & vaccination history. The facility records vaccination results in the child''s records. The system automatically sends reminder and notification emails. Manage vaccines in stock, users, booking schedules, ...", "teamSize": 3, "usedTools": ["Java", "Spring Boot", "Spring Security", "Spring AI", "MSSQL", "Spring Mail"], "description": "A web application that manages children''s vaccination schedules, allowing parents and health centers to schedule, track, and update vaccination records. Supports individual/group scheduling, automatic reminders, secure payments, and AI-powered customer support."}, {"name": "BAMBI KITCHEN", "role": "Back-end, Leader", "outcome": "Authorization & Authentication ( JW, OAuth2 Google ). Manage menus & recipes. Raw material warehouse management (Inventory, Import/Export, Warning). Order (Custom dishes & available dishes) with ingredient reservation system. Multi-channel payment (Cash, Momo, VNPAY). AI intergration ( Gemini AI - Nutrition & Recommend ).", "teamSize": 6, "usedTools": ["Spring Boot", "Spring Security", "Spring AI", "MSSQL", "Cloudinary", "Firebase Cloud Messaging", "Spring Mail"], "description": "Bambi kitchen is a food chain that specializes in providing healthy dishes and customers can customize and choose personalized dish ingredients step by step, with integrated AI to evaluate orders."}], "createdAt": [2026, 4, 9, 14, 38, 18, 734762000], "updatedAt": [2026, 4, 9, 14, 38, 22, 582891000], "educations": [{"gpa": "3.2", "major": "Software Engineering", "degree": null, "school": "FPT University", "end_date": "2026", "start_date": "2022"}], "softSkills": ["Teamwork", "English", "Fast learner", "Adaptability", "Problem-solving", "Technical Reading"], "targetRole": "Java Developer", "targetLevel": "Junior", "achievements": ["HONORABLE STUDENT OF TRIMESTER Semester 1, 3, 4, 5", "Admissions Collaborator -FPT University"], "introduction": "As a Java Developer, I am eager to work in a challenging environment to develop my skills and gain practical experience. I leverage my logical thinking and passion for programming to quickly transform knowledge into practical solutions, aiming to become an effective and well-grounded software development specialist.", "certifications": ["Web Design for Everybody: Basics of Web Development & Coding", "Software Development Lifecycle", "Java FullStack Developer"], "technicalSkills": ["Java", "C#", "HTML/CSS", "Spring Security", "Spring Data JPA", "Spring MVC", "MSSQL", "PostgreSQL", "JPA/Hibernate", "MongoDB", "ASP .NET", "SignalR", "Spring Boot", "Spring AI"], "workExperiences": [{"company": "FPT Software Academy", "end_date": "08/2025", "position": ".NET Developer Intern", "start_date": "05/2025", "description": "Final Training Project: Movie Theater. Role: Back-end, Leader. Developed an online movie ticketing system featuring real-time seat map visualization. Developed modules: movie management, showt