        (51, null, 9, null, '2026-08-06 00:37:29.239745', '2026-08-08 10:09:49.995790', 'IT', 'CANCELLED', 'STANDARD_MOCK', null, 'fd7c68ac-22b9-4e38-99e9-0084fd9a01a9', null, '{"id": 24, "tools": ["Git", "GitHub", "GitLab", "Maven", "Jira", "Swagger", "Docker", "Postman", "JUnit", "xUnit"], "projects": [{"name": "Movie Theater", "role": "Back-end, Leader", "outcome": "Final score: 9.7", "teamSize": 5, "usedTools": ["ASP.NET Core", "ASP.NET MVC", "PostgreSQL", "SignalR", "GitHub"], "description": "An online movie ticketing system featuring real-time seat map visualization and modules for movie, showtimes, theaters, promotions, and user accounts."}, {"name": "CHILD VACCINE SCHEDULE TRACKING SYSTEM", "role": "Back-end, Leader", "outcome": "Supports individual/group scheduling, automatic reminders, secure payments, and AI-powered customer support.", "teamSize": 3, "usedTools": ["Java", "Spring Boot", "Spring Security", "Spring AI", "MSSQL", "Spring Mail"], "description": "A web application that manages children''s vaccination schedules, allowing parents and health centers to schedule, track, and update vaccination records."}, {"name": "BAMBI KITCHEN", "role": "Back-end, Leader", "outcome": "Implemented JWT/OAuth2 authentication, warehouse management, multi-channel payment (Cash, Momo, VNPAY) and AI integration via Gemini AI.", "teamSize": 6, "usedTools": ["Spring Boot", "Spring Security", "Spring AI", "MSSQL", "Cloudinary", "Firebase Cloud Messaging", "Spring Mail"], "description": "A healthy food chain application where customers can customize dish ingredients step by step with integrated AI for order evaluation."}], "createdAt": [2026, 8, 4, 16, 14, 33, 422891000], "updatedAt": [2026, 8, 4, 16, 14, 33, 422919000], "educations": [{"gpa": "3.2", "major": "Software Engineering", "degree": null, "school": "FPT University", "end_date": "2026", "start_date": "2022"}], "softSkills": ["Technical Reading Proficiency in English", "Fast learner", "adaptability", "problem-solving", "teamwork"], "targetRole": "Java Developer", "targetLevel": "Intern", "achievements": ["Honorable Student of Trimester (Semester 1, 3, 4, 5)", "Admissions Collaborator - FPT University"], "introduction": "As a Java Developer, I am eager to work in a challenging environment to develop my skills and gain practical experience. I leverage my logical thinking and passion for programming to quickly transform knowledge into practical solutions, aiming to become an effective and well-grounded software development specialist.", "applicationId": 115, "certifications": ["Web Design for Everybody: Basics of Web Development & Coding", "Software Development Lifecycle", "Java FullStack Developer"], "technicalSkills": ["Java", "C#", "HTML/CSS", "Spring Security", "Spring Data JPA", "Spring MVC", "Validation", "DI/IoC", "ASP .NET", "MSSQL", "PostgreSQL", "JPA/Hibernate", "MongoDB"], "workExperiences": [{"company": "FPT Software Academy", "end_date": "08/2025", "position": ".NET Developer Intern", "start_date": "05/2025", "description": "Worked as a Back-end Leader for the Movie Theater project. Developed an online movie ticketing system with real-time seat map visualization and various management modules. Designed database and processing flow architecture."}]}', '{"basic_info": {"job_title": "Junior Java Backend Developer", "industry_domain": "AI-driven platform", "seniority_level": "Junior"}, "competencies": {"hard_skills": ["Java", "Backend Development", "RESTful APIs", "Database query optimization", "Microservices"], "soft_skills": ["passionate"], "tools_and_platforms": []}, "responsibilities": ["Building scalable RESTful APIs", "Optimizing database queries", "Integrating microservices"]}', null, '{"domain": "IT", "language": "VI", "difficulty": "FRESHER_BASIC", "interview_mode": "STANDARD_MOCK", "duration_minutes": 20}', 287),
