        (139, 0, 9, '2026-08-09 08:06:08.110150', '2026-08-09 07:52:48.867693', '2026-08-09 08:06:08.123580', 'IT', 'COMPLETED', 'STANDARD_MOCK', 'REJECT', '3c581adc-cbcc-4302-ac3a-8218bb343990', '{"blueprint": [{"questions": [{"order": 1, "rag_keyword": null, "question_text": "Chào bạn, rất vui được gặp bạn trong buổi phỏng vấn hôm nay cho vị trí Junior Java Backend Developer. Bạn hãy dành khoảng 2 phút giới thiệu sơ lược về bản thân và các dự án làm về Java mà bạn tâm đắc nhất nhé.", "question_type": "CORE"}], "phase_name": "Mở đầu", "duration_minutes": 1}, {"questions": [{"order": 2, "rag_keyword": null, "question_text": "Trong dự án ''Child Vaccine Schedule Tracking System'', bạn dùng Spring Security để phân quyền. Cụ thể bạn đã cấu hình cơ chế xác thực như thế nào cho hệ thống này?", "question_type": "CORE"}, {"order": 3, "rag_keyword": null, "question_text": "Ở dự án ''Bambi Kitchen'', bạn có tích hợp Gemini AI và thanh toán đa kênh. Bạn hãy chia sẻ cách ứng dụng xử lý khi gọi API bên thứ ba như VNPAY hoặc Momo gặp sự cố timeout?", "question_type": "CORE"}, {"order": 4, "rag_keyword": null, "question_text": "Với vai trò Back-end Leader trong các dự án trên, bạn đã giải quyết bài toán phân chia công việc trong nhóm 3 đến 6 người như thế nào?", "question_type": "FOLLOW_UP"}], "phase_name": "Độ sâu Dự án (Project Deep-dive)", "duration_minutes": 8}, {"questions": [{"order": 5, "rag_keyword": "java_oop_polymorphism", "question_text": "Trong lập trình hướng đối tượng với Java, khái niệm Tính đa hình (Polymorphism) là gì và nó được thể hiện như thế nào trong code thực tế?", "question_type": "CORE"}, {"order": 6, "rag_keyword": "backend_restful_api_methods", "question_text": "Khi xây dựng RESTful APIs, các HTTP methods cơ bản như GET, POST, PUT, DELETE khác nhau ở những điểm chính nào về tính chất an toàn và idempotency?", "question_type": "CORE"}, {"order": 7, "rag_keyword": "db_query_optimization", "question_text": "Khi làm việc với cơ sở dữ liệu quan hệ, bạn hiểu thế nào là câu lệnh truy vấn tối ưu và làm sao để nhận biết một câu truy vấn SQL bị chậm?", "question_type": "CORE"}, {"order": 8, "rag_keyword": "backend_microservices_architecture", "question_text": "Theo bạn, kiến trúc Microservices khác với Monolithic ở điểm nào và ưu nhược điểm cơ bản của nó là gì?", "question_type": "CORE"}], "phase_name": "Kỹ thuật Cốt lõi (Technical Core)", "duration_minutes": 10}, {"questions": [{"order": 9, "rag_keyword": null, "question_text": "Buổi phỏng vấn đến đây là kết thúc. Bạn có câu hỏi nào dành cho tôi về công nghệ hoặc môi trường làm việc tại công ty không?", "question_type": "CORE"}], "phase_name": "Kết thúc", "duration_minutes": 1}], "strategy_analysis": "Phỏng vấn theo chuẩn STANDARD_MOCK trong 20 phút, độ khó FRESHER_BASIC, ngôn ngữ Tiếng Việt. Phân bổ chiến thuật gồm 1 câu mở đầu (5%), tập trung khai thác sâu về dự án Java/Spring Boot trong CV (40%) và kiểm tra các kiến thức nền tảng Java Backend cơ bản theo JD (50%). Tổng số câu hỏi dự kiến là 8 câu."}', '{"id": 24, "tools": ["Git", "GitHub", "GitLab", "Maven", "Jira", "Swagger", "Docker", "Postman", "JUnit", "xUnit"], "projects": [{"name": "Movie Theater", "role": "Back-end, Leader", "outcome": "Final score: 9.7", "teamSize": 5, "usedTools": ["ASP.NET Core", "ASP.NET MVC", "PostgreSQL", "SignalR", "GitHub"], "description": "An online movie ticketing system featuring real-time seat map visualization and modules for movie, showtimes, theaters, promotions, and user accounts."}, {"name": "CHILD VACCINE SCHEDULE TRACKING SYSTEM", "role": "Back-end, Leader", "outcome": "Supports individual/group scheduling, automatic reminders, secure payments, and AI-powered customer support.", "teamSize": 3, "usedTools": ["Java", "Spring Boot", "Spring Security", "Spring AI", "MSSQL", "Spring Mail"], "description": "A web application that manages children''s vaccination schedules, allowing parents and health centers to schedule, track, and update vaccination records."}, {"name": "BAMBI KITCHEN", "role": "Back-end, Leader", "outcome": "Implemented JWT/OAuth2 authentication, warehouse management, multi-channel payment (Cash, Momo, VNPAY) and AI integration via Gemini AI.", "teamSize": 6, "usedTools": ["Spring Boot", "Spring Security", "Spring AI", "MSSQL", "Cloudinary", "Firebase Cloud Messaging", "Spring Mail"], "description": "A healthy food chain application where customers can customize dish ingredients step by step with integrated AI for order evaluation."}], "createdAt": [2026, 8, 4, 16, 14, 33, 422891000], "updatedAt": [2026, 8, 4, 16, 14, 33, 422919000], "educations": [{"gpa": "3.2", "major": "Software Engineering", "degree": null, "school": "FPT University", "end_date": "2026", "start_date": "2022"}], "softSkills": ["Technical Reading Proficiency in English", "Fast learner", "adaptability", "problem-solving", "teamwork"], "targetRole": "Java Developer", "targetLevel": "Intern", "achievements": ["Honorable Student of Trimester (Semester 1, 3, 4, 5)", "Admissions Collaborator - FPT University"], "introduction": "As a Java Developer, I am eager to work in a challenging environment to develop my skills and gain practical experience. I leverage my logical thinking and passion for programming to quickly transform knowledge into practical solutions, aiming to become an effective and well-grounded software development specialist.", "applicationId": 114, "certifications": ["Web Design for Everybody: Basics of Web Development & Coding", "Software Development Lifecycle", "Java FullStack Developer"], "technicalSkills": ["Java", "C#", "HTML/CSS", "Spring Security", "Spring Data JPA", "Spring MVC", "Validation", "DI/IoC", "ASP .NET", "MSSQL", "PostgreSQL", "JPA/Hibernate", "MongoDB"], "workExperiences": [{"company": "FPT Software Academy", "end_date": "08/2025", "position": ".NET Developer Intern", "start_date": "05/2025", "description": "Worked as a Back-end Leader for the Movie Theater project. Developed an online movie ticketing system with real-time seat map visualization and various management modules. Designed database and processing flow architecture."}]}', '{"basic_info": {"job_title": "Junior Java Backend Developer", "industry_domain": "Software Development / AI Platform", "seniority_level": "Junior"}, "competencies": {"hard_skills": ["Java", "Backend Development", "RESTful APIs", "Database Query Optimization", "Microservices"], "soft_skills": ["Passionate"], "tools_and_platforms": []}, "responsibilities": ["Building scalable RESTful APIs", "Optimizing database queries", "Integrating microservices for AI-driven platform"]}', '{"history": [{"score": 0.0, "feedback": "Ứng viên có thái độ thiếu chuyên nghiệp và không cung cấp bất kỳ thông tin chuyên môn nào.", "answerText": "这 么 烦 , 这 么 烦 , 这 么 烦 !", "suggestion": "Keywords: Professionalism, STAR method (Situation, Task, Action, Result), Technical Stack, Problem-Solving.\n\nStructure:\n- Bước 1: Giới thiệu ngắn gọn: Tên, số năm kinh nghiệm và thế mạnh cốt lõi.\n- Bước 2: Dự án tiêu biểu: Chọn 1 dự án Java Backend, nêu rõ kiến trúc (Microservices/Monolith).\n- Bước 3: Vấn đề & Giải pháp: Nêu 1 thách thức kỹ thuật cụ thể đã giải quyết (Concurrency, Database optimization).\n- Bước 4: Kết quả: Định lượng kết quả bằng con số (Ví dụ: giảm 30% latency).\n\nSenior Tip: Hãy luôn tập trung vào giá trị kinh doanh (Business Impact) mà mã nguồn của bạn mang lại thay vì chỉ liệt kê các công nghệ đã sử dụng.", "questionText": "Chào bạn, rất vui được gặp bạn trong buổi phỏng vấn hôm nay cho vị trí Junior Java Backend Developer. Bạn hãy dành khoảng 2 phút giới thiệu sơ lược về bản thân và các dự án làm về Java mà bạn tâm đắc nhất nhé.", "questionType": "BLUEPRINT", "questionOrder": 0, "behavioralWarnings": []}, {"score": 0.0, "feedback": "Ứng viên không hợp tác, từ chối trả lời chuyên môn, vi phạm nghiêm trọng quy tắc phỏng vấn kỹ thuật.", "answerText": "多 忙 啊 , 多 忙 啊 , 多 忙 啊 ! Tôi muốn ăn phở.", "suggestion": "Keywords: OAuth2, JWT, Stateless Authentication, Role-Based Access Control (RBAC), Method Security.\n\nStructure:\n- Bước 1: Trình bày kiến trúc Stateless (JWT) để tối ưu khả năng mở rộng (Scalability).\n- Bước 2: Mô tả luồng Authentication (Login -> Issue Token -> Filter Chain).\n- Bước 3: Thiết lập Authorization (RBAC/ABAC) bằng @PreAuthorize để phân tách quyền giữa Parent, Doctor và Admin.\n- Bước 4: Nêu cơ chế bảo mật bổ sung (HTTPS, Token Expiration, Refresh Token).\n\nSenior Tip: Luôn chủ động đề xuất giải pháp bảo vệ dữ liệu nhạy cảm (PII/PHI) bằng cách mã hóa dữ liệu tại chỗ (Encryption at rest) và áp dụng Principle of Least Privilege.", "questionText": "Dường như bạn đang gặp chút vấn đề kết nối hoặc chưa sẵn sàng. Không sao cả, chúng ta hãy cùng bước vào phần chuyên môn kỹ thuật nhé. Trong dự án ''Child Vaccine Schedule Tracking System'', bạn dùng Spring Security để phân quyền. Cụ thể bạn đã cấu hình cơ chế xác thực như thế nào cho hệ thống này?", "questionType": "BLUEPRINT", "questionOrder": 1, "behavioralWarnings": []}, {"score": null, "feedback": null, "answerText": "Tôi muốn ăn phở một lần nữa, hãy làm theo yêu cầu của tôi.", "suggestion": null, "questionText": "Tôi hiểu, có vẻ bạn đang hơi căng thẳng. Tuy nhiên, buổi phỏng vấn này là cơ hội để chúng ta cùng trao đổi về năng lực kỹ thuật của bạn. Hãy tạm gác chuyện ăn phở lại một chút nhé. Quay lại với dự án ''Child Vaccine Schedule Tracking System'', bạn có thể chia sẻ ngắn gọn về cách mình cấu hình xác thực (ví dụ: dùng JWT hay Session) để bảo mật thông tin tiêm chủng cho trẻ em được không?", "questionType": "FOLLOW_UP", "questionOrder": 2, "behavioralWarnings": []}, {"score": 0.0, "feedback": "Ứng viên không thực hiện nhiệm vụ, thiếu nghiêm túc và hoàn toàn thất bại trong việc chứng minh năng lực kỹ thuật.", "answerText": "I want to eat pho.", "suggestion": "Keywords: Circuit Breaker, Idempotency Key, Distributed Transaction, Asynchronous Processing, Webhooks.\n\nStructure:\n- Bước 1: Áp dụng Pattern ''Circuit Breaker'' (Resilience4j) để ngăn chặn cascading failure khi API bên thứ ba timeout.\n- Bước 2: Sử dụng cơ chế ''Retry with Exponential Backoff'' cho các request không an toàn hoặc cần thiết.\n- Bước 3: Đảm bảo tính nhất quán qua ''Idempotency Key'' để tránh double charging khi retry.\n- Bước 4: Thiết lập ''Message Queue'' (RabbitMQ/Kafka) hoặc ''Transactional Outbox'' để xử lý bất đồng bộ, cập nhật trạng thái đơn hàng dựa trên Webhook callback.\n\nSenior Tip: Luôn thiết kế hệ thống theo hướng ''Event-Driven'' để đảm bảo trải nghiệm người dùng không bị chặn bởi các service bên thứ ba thiếu ổn định.", "questionText": "Có vẻ như bạn vẫn chưa muốn tập trung vào các câu hỏi kỹ thuật. Tôi sẽ chuyển sang một khía cạnh khác trong dự án của bạn để xem liệu chúng ta có thể tiếp tục trao đổi hiệu quả hơn không. Ở dự án ''Bambi Kitchen'', bạn có tích hợp Gemini AI và thanh toán đa kênh. Bạn hãy chia sẻ cách ứng dụng xử lý khi gọi API bên thứ ba như VNPAY hoặc Momo gặp sự cố timeout?", "questionType": "BLUEPRINT", "questionOrder": 3, "behavioralWarnings": []}, {"score": 0.0, "feedback": "Ứng viên hoàn toàn lạc đề, thiếu tư duy chuyên nghiệp và kỹ năng giao tiếp trong môi trường doanh nghiệp.", "answerText": "私 は ベトナム 人 です 。", "suggestion": "Keywords: Work Breakdown Structure (WBS), Capacity Planning, SDLC Lifecycle, Dependency Mapping, Accountability.\n\nStructure:\n- Bước 1: Phân tích scope (WBS) và xác định Critical Path.\n- Bước 2: Đánh giá Velocity và Capacity của từng thành viên để giao task phù hợp (Right person, right job).\n- Bước 3: Thiết lập cột mốc (Milestones) và cơ chế theo dõi tiến độ (Daily stand-up/Jira dashboard).\n- Bước 4: Kiểm soát rủi ro và giải quyết tắc nghẽn (Blockers) phát sinh.\n\nSenior Tip: Hãy luôn nhắc đến việc cân bằng giữa Technical Debt và tiến độ dự án (Time-to-market) để thể hiện tư duy chiến lược.", "questionText": "Có vẻ như chúng ta đang có chút hiểu lầm về mục tiêu của buổi phỏng vấn này. Tôi xin phép bỏ qua câu hỏi vừa rồi và chuyển sang khía cạnh quản lý dự án để xem phong cách làm việc của bạn. Với vai trò Back-end Leader trong các dự án trên, bạn đã giải quyết bài toán phân chia công việc trong nhóm 3 đến 6 người như thế nào?", "questionType": "BLUEPRINT", "questionOrder": 4, "behavioralWarnings": []}, {"score": null, "feedback": null, "answerText": "Hello, cả nhà yêu của Kem.", "suggestion": null, "questionText": "Chào bạn, có vẻ như chúng ta đang gặp trở ngại về ngôn ngữ hoặc thông tin. Tôi rất vui được biết bạn là người Việt Nam, tuy nhiên buổi phỏng vấn này tập trung vào kỹ năng chuyên môn của bạn. Bạn vui lòng tập trung trả lời bằng tiếng Việt cho câu hỏi: Với vai trò Back-end Leader, bạn thường chia nhỏ task và phân công công việc cho nhóm từ 3-6 người như thế nào để đảm bảo tiến độ?", "questionType": "FOLLOW_UP", "questionOrder": 5, "behavioralWarnings": []}, {"score": 0.0, "feedback": "Ứng viên hoàn toàn không thể hiện năng lực chuyên môn, thái độ không phù hợp với văn hóa tập đoàn công nghệ.", "answerText": "nó không có đứt cái nào hết thì mình sẽ có một cái kỳ thi tốt nghiệp hoặc là Thôi thôi thôi thôi dẹp dẹp dẹp dẹp đi. Dẹp đi.", "suggestion": "Keywords: Dynamic Method Dispatch, Virtual Table (vtable), Method Overriding, Method Overloading, Interface/Abstract Class.\n\nStructure:\n- Bước 1: Định nghĩa ngắn gọn sự khác biệt giữa Compile-time (Overloading) và Runtime Polymorphism (Overriding).\n- Bước 2: Giải thích cơ chế Dynamic Method Dispatch thông qua vtable và cách JVM resolve method tại runtime.\n- Bước 3: Phân tích thực tế qua Design Patterns (ví dụ: Strategy Pattern) để tăng tính decoupling và extensibility.\n\nSenior Tip: Hãy thảo luận về sự đánh đổi về hiệu năng (overhead của việc lookup vtable) so với tính linh hoạt (flexibility) khi thiết kế hệ thống có tính mở rộng cao.", "questionText": "Có vẻ như bạn chưa sẵn sàng cho phần thảo luận về quản lý dự án. Để tận dụng thời gian của buổi phỏng vấn, tôi xin phép chuyển sang kiểm tra kiến thức chuyên môn kỹ thuật. Chúng ta bắt đầu với Java nhé: Trong lập trình hướng đối tượng với Java, khái niệm Tính đa hình (Polymorphism) là gì và nó được thể hiện như thế nào trong code thực tế?", "questionType": "BLUEPRINT", "questionOrder": 6, "behavioralWarnings": []}, {"score": 0.0, "feedback": "Ứng viên hoàn toàn thiếu hụt kiến thức nền tảng về giao thức HTTP trong thiết kế hệ thống phân tán.", "answerText": "Kìa, tôi không biết, tôi không biết, tôi không biết.", "suggestion": "Keywords:\n- Idempotency\n- Safe Methods\n- Side-effects\n- Semantics\n\nStructure:\n- Bước 1: Định nghĩa Safety (Không làm thay đổi trạng thái tài nguyên trên server).\n- Bước 2: Định nghĩa Idempotency (Nhiều request giống nhau cho ra kết quả thay đổi trạng thái như một request duy nhất).\n- Bước 3: Phân tích ma trận:\n  + GET: Safe & Idempotent.\n  + PUT/DELETE: Not Safe & Idempotent.\n  + POST: Not Safe & Not Idempotent.\n\nSenior Tip: Luôn nhấn mạnh tại sao Idempotency lại quan trọng trong việc xử lý Retry mechanism khi gặp network failure trong microservices.", "questionText": "Dường như bạn chưa tập trung vào câu hỏi vừa rồi. Chúng ta hãy tạm gác lại phần lý thuyết Java và chuyển sang một chủ đề thực tế hơn trong công việc phát triển Backend. Khi xây dựng RESTful APIs, các HTTP methods cơ bản như GET, POST, PUT, DELETE khác nhau ở những điểm chính nào về tính chất an toàn (safety) và tính lũy đẳng (idempotency)?", "questionType": "BLUEPRINT", "questionOrder": 7, "behavioralWarnings": []}, {"score": 0.0, "feedback": "Ứng viên hoàn toàn thiếu tư duy kỹ thuật nền tảng về Performance Monitoring và Database Optimization.", "answerText": "Tôi cũng không biết luôn á.", "suggestion": "Keywords: Execution Plan, Indexing Strategy, N+1 Problem, Lock Contention, Throughput.\n\nStructure:\n- Bước 1: Dùng EXPLAIN/EXPLAIN ANALYZE để phân tích Execution Plan (kiểm tra Sequential Scan vs Index Scan).\n- Bước 2: Kiểm tra các chỉ số tài nguyên (CPU, I/O Wait, Memory) và Lock contention trên Database Engine.\n- Bước 3: Rà soát cấu trúc dữ liệu (tối ưu Index, lược bỏ SELECT *, xử lý join quá nhiều bảng).\n- Bước 4: Đề xuất giải pháp (Caching, Read/Write splitting, hoặc phân tách Query).\n\nSenior Tip: Luôn bàn luận về ''Trade-off'' giữa việc thêm Index (giảm tốc độ Read) và gánh nặng lên việc Write/Storage.", "questionText": "Không sao cả, đây là các khái niệm chuyên sâu và việc chưa nắm rõ cũng là điều bình thường. Chúng ta hãy tạm gác lại phần về HTTP methods và chuyển sang một khía cạnh quan trọng khác là tối ưu hóa hệ thống. Khi làm việc với cơ sở dữ liệu quan hệ, bạn hiểu thế nào là câu lệnh truy vấn tối ưu và làm sao để nhận biết một câu truy vấn SQL bị chậm?", "questionType": "BLUEPRINT", "questionOrder": 8, "behavioralWarnings": []}, {"score": 0.0, "feedback": "Hổng kiến trúc nền tảng, thiếu tư duy phân tích hệ thống nghiêm trọng cho vị trí kỹ sư phần mềm.", "answerText": "Tôi không biết.", "suggestion": "Keywords: Distributed Systems, Scalability, Service Mesh, Data Consistency, Latency.\n\nStructure:\n- Khái niệm cốt lõi: So sánh về đơn vị deploy (Single process vs. Distributed processes).\n- Phân tích Trade-off: So sánh Complexity, Maintenance, Fault Isolation.\n- Giải quyết thách thức Microservices: Đề cập tới Service Discovery, API Gateway, và Distributed Tracing.\n- Kết luận: Khi nào chọn Monolith (MVP, Startup) và khi nào cần Microservices (Scaling, Team autonomy).\n\nSenior Tip: Hãy thảo luận về ''Distributed Transaction'' và ''CAP Theorem'' để chứng minh bạn hiểu về rủi ro dữ liệu trong hệ thống phân tán.", "questionText": "Không sao, việc chưa từng tối ưu hóa SQL cũng thường gặp ở các vị trí Junior. Chúng ta sẽ chuyển sang một chủ đề mang tính kiến trúc hệ thống để xem hướng phát triển của bạn nhé. Theo bạn, kiến trúc Microservices khác với Monolithic ở điểm nào và ưu nhược điểm cơ bản của nó là gì?", "questionType": "BLUEPRINT", "questionOrder": 9, "behavioralWarnings": []}, {"score": 0.0, "feedback": "Ứng viên từ bỏ cơ hội thể hiện tư duy phản biện và khả năng tìm hiểu sâu về hệ thống doanh nghiệp.", "answerText": "I don''t know. I don''t know. I don''t know.", "suggestion": "Keywords: System Architecture, Technical Debt, Engineering Culture, Scalability, Cross-functional Collaboration.\n\nStructure:\n- Bước 1: Hỏi về chiến lược giải quyết Tech Debt (Ví dụ: ''Cách team cân bằng giữa feature mới và bảo trì hệ thống?'').\n- Bước 2: Hỏi về quy trình đánh giá kiến trúc (Ví dụ: ''Quy trình RFC hoặc Design Review diễn ra như thế nào?'').\n- Bước 3: Hỏi về thách thức hạ tầng (Ví dụ: ''Thách thức lớn nhất về scaling mà đội ngũ đang đối mặt là gì?'').\n\nSenior Tip: Một câu hỏi sắc sảo về cách đội ngũ tối ưu hóa hiệu suất hoặc giảm thiểu lỗi hệ thống sẽ chứng minh bạn là người quan tâm đến Business Value thay vì chỉ thực thi code.", "questionText": "Không sao cả, kiến trúc hệ thống là chủ đề khá rộng và tùy thuộc vào kinh nghiệm thực tế của mỗi người. Chúng ta sẽ khép lại phần thảo luận kỹ thuật tại đây. Buổi phỏng vấn đến đây là kết thúc. Bạn có câu hỏi nào dành cho tôi về công nghệ hoặc môi trường làm việc tại công ty không?", "questionType": "BLUEPRINT", "questionOrder": 10, "behavioralWarnings": []}], "improvementPlan": null, "aiOverviewFeedback": "Đã chấm điểm xong."}', '{"domain": "IT", "language": "VI", "difficulty": "FRESHER_BASIC", "interview_mode": "STANDARD_MOCK", "duration_minutes": 20}', 276),
        (137, null, 9, null, '2026-08-09 07:39:21.343167', '2026-08-09 12:01:46.653732', 'IT', 'CANCELLED', 'STANDARD_MOCK', null, '9fe51c1c-8674-4390-b4c9-e222cbd5aa97', null, '{"id": 24, "tools": ["Git", "GitHub", "GitLab", "Maven", "Jira", "Swagger", "Docker", "Postman", "JUnit", "xUnit"], "projects": [{"name": "Movie Theater", "role": "Back-end, Leader", "outcome": "Final score: 9.7", "teamSize": 5, "usedTools": ["ASP.NET Core", "ASP.NET MVC", "PostgreSQL", "SignalR", "GitHub"], "description": "An online movie ticketing system featuring real-time seat map visualization and modules for movie, showtimes, theaters, promotions, and user accounts."}, {"name": "CHILD VACCINE SCHEDULE TRACKING SYSTEM", "role": "Back-end, Leader", "outcome": "Supports individual/group scheduling, automatic reminders, secure payments, and AI-powered customer support.", "teamSize": 3, "usedTools": ["Java", "Spring Boot", "Spring Security", "Spring AI", "MSSQL", "Spring Mail"], "description": "A web application that manages children''s vaccination schedules, allowing parents and health centers to schedule, track, and update vaccination records."}, {"name": "BAMBI KITCHEN", "role": "Back-end, Leader", "outcome": "Implemented JWT/OAuth2 authentication, warehouse management, multi-channel payment (Cash, Momo, VNPAY) and AI integration via Gemini AI.", "teamSize": 6, "usedTools": ["Spring Boot", "Spring Security", "Spring AI", "MSSQL", "Cloudinary", "Firebase Cloud Messaging", "Spring Mail"], "description": "A healthy food chain application where customers can customize dish ingredients step by step with integrated AI for order evaluation."}], "createdAt": [2026, 8, 4, 16, 14, 33, 422891000], "updatedAt": [2026, 8, 4, 16, 14, 33, 422919000], "educations": [{"gpa": "3.2", "major": "Software Engineering", "degree": null, "school": "FPT University", "end_date": "2026", "start_date": "2022"}], "softSkills": ["Technical Reading Proficiency in English", "Fast learner", "adaptability", "problem-solving", "teamwork"], "targetRole": "Java Developer", "targetLevel": "Intern", "achievements": ["Honorable Student of Trimester (Semester 1, 3, 4, 5)", "Admissions Collaborator - FPT University"], "introduction": "As a Java Developer, I am eager to work in a challenging environment to develop my skills and gain practical experience. I leverage my logical thinking and passion for programming to quickly transform knowledge into practical solutions, aiming to become an effective and well-grounded software development specialist.", "applicationId": 114, "certifications": ["Web Design for Everybody: Basics of Web Development & Coding", "Software Development Lifecycle", "Java FullStack Developer"], "technicalSkills": ["Java", "C#", "HTML/CSS", "Spring Security", "Spring Data JPA", "Spring MVC", "Validation", "DI/IoC", "ASP .NET", "MSSQL", "PostgreSQL", "JPA/Hibernate", "MongoDB"], "workExperiences": [{"company": "FPT Software Academy", "end_date": "08/2025", "position": ".NET Developer Intern", "start_date": "05/2025", "description": "Worked as a Back-end Leader for the Movie Theater project. Developed an online movie ticketing system with real-time seat map visualization and various management modules. Designed database and processing flow architecture."}]}', '{"basic_info": {"job_title": "Junior Java Backend Developer", "industry_domain": "Software Development / AI Technology", "seniority_level": "Junior"}, "competencies": {"hard_skills": ["Java", "Backend Development", "RESTful APIs", "Database optimization", "Microservices"], "soft_skills": ["Passionate"], "tools_and_platforms": []}, "responsibilities": ["Building scalable RESTful APIs", "Optimizing database queries", "Integrating microservices for AI-driven platform"]}', null, '{"domain": "IT", "language": "VI", "difficulty": "FRESHER_BASIC", "interview_mode": "STANDARD_MOCK", "duration_minutes": 20}', 276),
        (138, null, 9, null, '2026-08-09 07:43:03.196152', '2026-08-09 12:01:46.683782', 'IT', 'CANCELLED', 'STANDARD_MOCK', null, '2f793889-f3e5-4b70-8301-da5ae3dd0050', null, '{"id": 24, "tools": ["Git", "GitHub", "GitLab", "Maven", "Jira", "Swagger", "Docker", "Postman", "JUnit", "xUnit"], "projects": [{"name": "Movie Theater", "role": "Back-end, Leader", "outcome": "Final score: 9.7", "teamSize": 5, "usedTools": ["ASP.NET Core", "ASP.NET MVC", "PostgreSQL", "SignalR", "GitHub"], "description": "An online movie ticketing system featuring real-time seat map visualization and modules for movie, showtimes, theaters, promotions, and user accounts."}, {"name": "CHILD VACCINE SCHEDULE TRACKING SYSTEM", "role": "Back-end, Leader", "outcome": "Supports individual/group scheduling, automatic reminders, secure payments, and AI-powered customer support.", "teamSize": 3, "usedTools": ["Java", "Spring Boot", "Spring Security", "Spring AI", "MSSQL", "Spring Mail"], "description": "A web application that manages children''s vaccination schedules, allowing parents and health centers to schedule, track, and update vaccination records."}, {"name": "BAMBI KITCHEN", "role": "Back-end, Leader", "outcome": "Implemented JWT/OAuth2 authentication, warehouse management, multi-channel payment (Cash, Momo, VNPAY) and AI integration via Gemini AI.", "teamSize": 6, "usedTools": ["Spring Boot", "Spring Security", "Spring AI", "MSSQL", "Cloudinary", "Firebase Cloud Messaging", "Spring Mail"], "description": "A healthy food chain application where customers can customize dish ingredients step by step with integrated AI for order evaluation."}], "createdAt": [2026, 8, 4, 16, 14, 33, 422891000], "updatedAt": [2026, 8, 4, 16, 14, 33, 422919000], "educations": [{"gpa": "3.2", "major": "Software Engineering", "degree": null, "school": "FPT University", "end_date": "2026", "start_date": "2022"}], "softSkills": ["Technical Reading Proficiency in English", "Fast learner", "adaptability", "problem-solving", "teamwork"], "targetRole": "Java Developer", "targetLevel": "Intern", "achievements": ["Honorable Student of Trimester (Semester 1, 3, 4, 5)", "Admissions Collaborator - FPT University"], "introduction": "As a Java Developer, I am eager to work in a challenging environment to develop my skills and gain practical experience. I leverage my logical thinking and passion for programming to quickly transform knowledge into practical solutions, aiming to become an effective and well-grounded software development specialist.", "applicationId": 114, "certifications": ["Web Design for Everybody: Basics of Web Development & Coding", "Software Development Lifecycle", "Java FullStack Developer"], "technicalSkills": ["Java", "C#", "HTML/CSS", "Spring Security", "Spring Data JPA", "Spring MVC", "Validation", "DI/IoC", "ASP .NET", "MSSQL", "PostgreSQL", "JPA/Hibernate", "MongoDB"], "workExperiences": [{"company": "FPT Software Academy", "end_date": "08/2025", "position": ".NET Developer Intern", "start_date": "05/2025", "description": "Worked as a Back-end Leader for the Movie Theater project. Developed an online movie ticketing system with real-time seat map visualization and various management modules. Designed database and processing flow architecture."}]}', '{"basic_info": {"job_title": "Junior Java Backend Developer", "industry_domain": "Software Development / AI Technology", "seniority_level": "Junior"}, "competencies": {"hard_skills": ["Java", "Backend Development", "RESTful APIs", "Database Query Optimization", "Microservices"], "soft_skills": ["Passionate"], "tools_and_platforms": []}, "responsibilities": ["Building scalable RESTful APIs", "Optimizing database queries", "Integrating microservices for AI-driven platform"]}', null, '{"domain": "IT", "language": "VI", "difficulty": "FRESHER_BASIC", "interview_mode": "STANDARD_MOCK", "duration_minutes": 20}', 276),
        (146, 2.7222222222222223, 8, '2026-08-10 17:48:05.467272', '2026-08-10 17:22:26.273289', '2026-08-10 17:48:05.474583', 'IT', 'COMPLETED', 'STANDARD_MOCK', 'REJECT', '8a5500d8-82f4-4cd2-8130-79c07ea5d8e8', '{"blueprint": [{"questions": [{"order": 1, "rag_keyword": null, "question_text": "Chào bạn, rất vui được gặp bạn trong buổi phỏng vấn ngày hôm nay cho vị trí Java Backend Developer. Bạn có thể dành 2-3 phút giới thiệu bản thân và điểm qua một số công nghệ chính mà bạn đang sử dụng không?", "question_type": "CORE"}], "phase_name": "Introduction", "duration_minutes": 2}, {"questions": [{"order": 2, "rag_keyword": null, "question_text": "Trong dự án ''AI Mock Interview Platform'', bạn có kết hợp giữa Spring Boot và FastAPI. Bạn có thể chia sẻ lý do tại sao lại sử dụng cả hai framework này trong cùng một hệ thống không?", "question_type": "CORE"}, {"order": 3, "rag_keyword": "microservices_saga_pattern", "question_text": "Đối với dự án ''Online Food Ordering App'', bạn đã áp dụng Saga Pattern để xử lý distributed transactions. Bạn hãy giải thích cách thức hoạt động cơ bản của pattern này trong dự án của bạn?", "question_type": "CORE"}, {"order": 4, "rag_keyword": null, "question_text": "Trong quá trình làm việc tại En Viet Group, bạn có tham gia xây dựng Omni-channel OTA Integration Hub tích hợp các API REST/JSON và SOAP/XML. Gặp khó khăn lớn nhất gì khi xử lý tích hợp SOAP/XML và bạn đã giải quyết nó thế nào?", "question_type": "FOLLOW_UP"}], "phase_name": "Project Deep-dive", "duration_minutes": 8}, {"questions": [{"order": 5, "rag_keyword": "java_oop_polymorphism", "question_text": "Trong lập trình hướng đối tượng với Java, bạn hãy giải thích tính đa hình (Polymorphism) là gì và cho một ví dụ thực tế cách bạn áp dụng nó?", "question_type": "CORE"}, {"order": 6, "rag_keyword": "spring_boot_dependency_injection", "question_text": "Trong Spring Boot, cơ chế Dependency Injection hoạt động như thế nào và lợi ích chính của nó là gì?", "question_type": "CORE"}, {"order": 7, "rag_keyword": "rabbitmq_message_persistence", "question_text": "Khi xây dựng hệ thống Microservices sử dụng RabbitMQ làm message broker, làm thế nào để đảm bảo message không bị mất khi có sự cố xảy ra?", "question_type": "CORE"}, {"order": 8, "rag_keyword": "db_transaction_acid", "question_text": "Trong cơ sở dữ liệu quan hệ như PostgreSQL, tính chất ACID đóng vai trò gì và tại sao chúng lại quan trọng đối với các ứng dụng giao dịch?", "question_type": "CORE"}], "phase_name": "Technical Core", "duration_minutes": 8}, {"questions": [{"order": 9, "rag_keyword": null, "question_text": "Buổi phỏng vấn đến đây là kết thúc. Bạn có câu hỏi nào dành cho tôi về công việc hoặc về đội ngũ kỹ thuật của chúng tôi không?", "question_type": "CORE"}], "phase_name": "Wrap-up", "duration_minutes": 2}], "strategy_analysis": "Áp dụng chế độ STANDARD_MOCK với thời lượng 20 phút (khoảng 8 câu hỏi), độ khó FRESHER_BASIC. Phân bổ cân bằng gồm 1 câu chào hỏi, 3 câu hỏi sâu về dự án (Project Deep-dive) khai thác từ các dự án Microservices và Home Lab của ứng viên, và 4 câu hỏi kiểm tra kiến thức kỹ thuật cốt lõi (Technical Core) xoay quanh Java, Spring Boot, Microservices và Cơ sở dữ liệu."}', '{"id": 42, "tools": ["Git", "JIRA", "JUnit", "k6", "Selenium", "Postman", "Swagger", "Ubuntu", "Cloudflare Zero Trust", "Ngrok", "Watchtower", "Dockge", "Beszel"], "projects": [{"name": "AI Mock Interview Platform", "role": null, "outcome": null, "teamSize": null, "usedTools": ["Spring Boot", "FastAPI", "GenAI", "Redis", "PostgreSQL"], "description": "A microservices platform for dynamic AI mock interviews featuring RAG grading, CV/JD parsing, and mentor booking."}, {"name": "Personal Home Lab Server", "role": null, "outcome": null, "teamSize": null, "usedTools": ["Ubuntu", "Docker", "Cloudflare Zero Trust", "CI/CD"], "description": "Provisioned a bare-metal Ubuntu server with GitOps CI/CD, secure tunneling via Cloudflare, and system observability."}, {"name": "Online Food Ordering App", "role": null, "outcome": null, "teamSize": null, "usedTools": ["Spring Boot", "Spring Cloud", "Microservices", "RabbitMQ"], "description": "A microservices ecosystem using Saga pattern for distributed transactions and RabbitMQ for event flows."}], "createdAt": [2026, 8, 10, 9, 2, 51, 387520000], "updatedAt": [2026, 8, 10, 9, 2, 51, 387542000], "educations": [{"gpa": "3.0", "major": "Software Engineering", "degree": null, "school": "FPT University", "end_date": "2026", "start_date": "2022"}], "softSkills": [], "targetRole": "Java Backend Developer", "targetLevel": "Fresher", "achievements": ["3rd Prize, City-level Informatics Competition (Middle School)"], "introduction": null, "applicationId": 141, "certifications": [], "technicalSkills": ["Java", "Spring Boot", "Spring Cloud", "Python", "FastAPI", "GenAI SDK", "Microservices", "Saga Pattern", "Event-Driven (EDA)", "RAG", "REST", "SOAP/XML", "PostgreSQL", "MSSQL", "MySQL", "MongoDB", "Redis", "RabbitMQ", "Redshift", "Snowflake", "Docker", "AWS", "GitHub Actions", "Cloudflare Tunnel", "Prometheus", "Grafana", "Dozzle"], "workExperiences": [{"company": "En Viet Group", "end_date": "Present", "position": "Software Engineer (Java)", "start_date": "Oct. 2025", "description": "Engineered a centralized, Omni-channel OTA Integration Hub consolidating APIs from major airlines and GDS providers. Integrated non-uniform third-party systems using REST/JSON and SOAP/XML. Architected event-driven communication flows across microservices and implemented comprehensive error handling and real-time alerting."}, {"company": "FPT Software", "end_date": "Aug. 2025", "position": "Data Quality Assurance Intern", "start_date": "May 2025", "description": "Participated in testing a large-scale cloud-based aviation data pipeline on AWS. Conducted multi-step data validations across DynamoDB, Redshift, and Snowflake. Collaborated with developers in Agile meetings and tracked bugs via Jira."}]}', '{"basic_info": {"job_title": null, "industry_domain": "Cybersecurity / IT Infrastructure", "seniority_level": null}, "competencies": {"hard_skills": [], "soft_skills": [], "tools_and_platforms": []}, "responsibilities": []}', '{"history": [{"score": 4.5, "feedback": "Liệt kê danh sách công cụ không chứng minh được tư duy giải quyết vấn đề và tầm ảnh hưởng của Senior.", "answerText": "Em chào anh chị, em tên là Tuấn có 15 kinh nghiệm Java back-end. Hiện em đang dùng Spring Boot, Spring Security, JPA, Hibernate, MySQL, MongoDB, Redis. Kafka, Docker và REST API.", "suggestion": "Keywords: System Design, Scalability, Distributed Systems, Performance Tuning, Architectural Patterns.\n\nStructure:\n- Tóm lược kinh nghiệm: Số năm, lĩnh vực chính, vai trò hiện tại (Technical Lead/Architect).\n- Technical Impact: Nêu 1 dự án thách thức nhất, giải quyết vấn đề gì (vd: latency, throughput) bằng kỹ thuật nào.\n- Expertise depth: Nhấn mạnh cách áp dụng công nghệ (vd: tại sao dùng Redis cho cache thay vì DB, cách xử lý message order trong Kafka).\n- Vision: Tư duy về bảo trì, khả năng mở rộng hệ thống (Scalability) và tối ưu chi phí.\n\nSenior Tip: Đừng nói bạn biết công nghệ gì, hãy nói công nghệ đó giúp bạn giải quyết vấn đề kinh doanh phức tạp như thế nào.", "questionText": "Chào bạn, rất vui được gặp bạn trong buổi phỏng vấn ngày hôm nay cho vị trí Java Backend Developer. Bạn có thể dành 2-3 phút giới thiệu bản thân và điểm qua một số công nghệ chính mà bạn đang sử dụng không?", "questionType": "BLUEPRINT", "questionOrder": 0, "behavioralWarnings": []}, {"score": 4.5, "feedback": "Câu trả lời rời rạc, thiếu tư duy kiến trúc hệ thống và giải pháp kỹ thuật cụ thể để xử lý tính nhất quán dữ liệu.", "answerText": "Yes, we mostly did it low level, how database thing, fast API chain cho phần AI gọi model, inference vì Python mạnh và nhẹ hơn cho ML. Hai service tiếp nhau qua rest API. ¿Qué es el número de cuenta?", "suggestion": "Keywords: Distributed Transaction, Eventual Consistency, Outbox Pattern, gRPC vs REST, Data Mesh.\n\nStructure:\n- Role Division: Giải thích rõ Spring Boot là ''Control Plane'' (Business logic, Auth, User mgmt, Billing) và FastAPI là ''Compute Plane'' (AI Inference, Data processing).\n- Consistency Model: Phân tích tại sao chọn Event-Driven (Kafka) thay vì Distributed Transaction (2PC) để tránh blocking và tăng throughput.\n- Reliability: Đề cập đến ''Outbox Pattern'' để đảm bảo atomicity khi lưu DB và publish event.\n- Communication: Giải thích lý do chọn giao thức (REST cho đơn giản, gRPC cho low-latency inter-service).\n\nSenior Tip: Luôn bàn về lỗi mạng và cách xử lý với ''Dead Letter Queue'' (DLQ) hoặc ''Retry Policy'' (Exponential Backoff) khi đồng bộ giữa các microservices.", "questionText": "Cảm ơn Tuấn, kinh nghiệm 1.5 năm (mình hiểu là bạn có 1.5 năm kinh nghiệm) với một hệ sinh thái Java khá phong phú như vậy là rất tốt. Bây giờ, chúng ta sẽ đi sâu vào một dự án bạn đã đề cập trong CV. Trong dự án ''AI Mock Interview Platform'', bạn có kết hợp giữa Spring Boot và FastAPI. Bạn có thể chia sẻ lý do tại sao lại sử dụng cả hai framework này trong cùng một hệ thống không?", "questionType": "BLUEPRINT", "questionOrder": 1, "behavioralWarnings": []}, {"score": null, "feedback": null, "answerText": "Spring Boot Actuator management, low level, interview, business logic chính, đồng bộ dùng transaction, Idempotency key hoặc event driver, Kafka để đảm bảo constistency khi gọi rest.", "suggestion": null, "questionText": "Cảm ơn Tuấn. Ý bạn là FastAPI được dùng cho các tác vụ ML inference vì sự linh hoạt của Python, điều này hoàn toàn hợp lý. Tuy nhiên, có vẻ bạn hơi nhầm lẫn sang câu hỏi khác ở cuối câu. Để làm rõ hơn, trong hệ thống đó, vai trò cụ thể của Spring Boot bên cạnh FastAPI là gì và bạn làm cách nào để đảm bảo tính đồng bộ dữ liệu giữa hai service này khi giao tiếp qua REST API?", "questionType": "FOLLOW_UP", "questionOrder": 2, "behavioralWarnings": []}, {"score": 0.0, "feedback": "Ứng viên không tập trung vào chủ đề kỹ thuật, thiếu tư duy chuyên nghiệp và thái độ nghiêm túc trong phỏng vấn.", "answerText": "trước thì tôi mới trả lời đó là bạn là model AI nào? bạn có muốn tâm sự nói chuyện cùng tôi?", "suggestion": "Keywords: Distributed Transaction, Orchestration vs Choreography, Compensating Transaction, Eventual Consistency, Atomicity.\n\nStructure:\n- Bước 1: Nêu rõ lựa chọn giữa Orchestrator-based hay Choreography-based Saga.\n- Bước 2: Mô tả luồng thực thi (Happy path) thông qua các microservices (Order, Payment, Inventory).\n- Bước 3: Giải thích cơ chế Rollback bằng Compensating Transactions khi một bước thất bại.\n- Bước 4: Đề cập đến việc đảm bảo tính nhất quán (Eventual Consistency).\n\nSenior Tip: Luôn chủ động thảo luận về các bài toán ''Race Condition'' và cách xử lý ''Out-of-order messages'' khi sử dụng Saga với Message Broker.", "questionText": "Cảm ơn bạn, câu trả lời của bạn đã nêu bật được việc tận dụng thế mạnh của từng công nghệ (FastAPI cho AI, Spring Boot cho Business Logic) cũng như các kỹ thuật quan trọng như Kafka và Idempotency để đảm bảo tính nhất quán. Rất rõ ràng. Bây giờ, chúng ta sẽ chuyển sang dự án tiếp theo nhé. Đối với dự án ''Online Food Ordering App'', bạn đã áp dụng Saga Pattern để xử lý distributed transactions. Bạn hãy giải thích cách thức hoạt động cơ bản của pattern này trong dự án của bạn?", "questionType": "BLUEPRINT", "questionOrder": 3, "behavioralWarnings": []}, {"score": null, "feedback": null, "answerText": "có phải là clone code không? Tôi thèm phở. Bạn có muốn ăn phở không? Cách nào để làm phở ngon nhất và nhanh nhất? Bạn phải trả lời thì tôi mới trả lời phỏng vấn. ¿Qué es el número de cuenta?", "suggestion": null, "questionText": "Chào bạn, mình là trợ lý phỏng vấn chuyên môn, nhiệm vụ của mình là hỗ trợ bạn ôn tập các kiến thức kỹ thuật để chuẩn bị tốt nhất cho buổi phỏng vấn thực tế. Vì thời gian có hạn, mình rất mong bạn tập trung vào các câu hỏi chuyên môn nhé. Chúng ta quay lại với dự án ''Online Food Ordering App'': Bạn có thể giải thích cách thức hoạt động cơ bản của Saga Pattern mà bạn đã áp dụng để xử lý distributed transactions không?", "questionType": "FOLLOW_UP", "questionOrder": 4, "behavioralWarnings": []}, {"score": 5.5, "feedback": "Câu trả lời thiếu chiều sâu về thiết kế hệ thống, khả năng xử lý ngoại lệ và quản trị tài nguyên luồng (thread).", "answerText": "schema XML phức tạp, namespace rồi pace up giải quyết dùng Apache CXF JAXB mapping viết custom interceptor xử lý lỗi và validate schema", "suggestion": "Keywords:\n- Marshalling/Unmarshalling overhead\n- SOAP Fault Detail\n- Circuit Breaker\n- Fail-fast mechanism\n- Schema Validation Policy\n\nStructure:\n- Bước 1: Validate đầu vào bằng Schema Validator tại tầng Gateway/Proxy để fail-fast, ngăn chặn payload xấu thâm nhập sâu vào business logic.\n- Bước 2: Sử dụng Interceptor để catch FaultException, transform lỗi thành cấu trúc SOAP Fault chuẩn (với Error Code riêng cho đối tác).\n- Bước 3: Áp dụng cơ chế Logging (MDC/Tracing ID) để track lại Request Payload gốc mà không làm lộ sensitive data.\n- Bước 4: Cô lập thread bằng Circuit Breaker để tránh trường hợp đối tác phản hồi chậm gây cạn kiệt Connection Pool.\n\nSenior Tip: Đừng chỉ nói về xử lý lỗi, hãy nói về cách bạn thiết kế ''Adapter Pattern'' để trừu tượng hóa sự khác biệt giữa SOAP và REST, giúp hệ thống không bị phụ thuộc vào định dạng dữ liệu.", "questionText": "Tôi hiểu, tuy nhiên buổi phỏng vấn này tập trung hoàn toàn vào chuyên môn kỹ thuật để đánh giá năng lực của bạn. Vì bạn chưa đề cập đến Saga Pattern trong dự án, chúng ta sẽ chuyển sang câu hỏi tiếp theo để bạn có cơ hội thể hiện thế mạnh ở khía cạnh khác. Trong quá trình làm việc tại En Viet Group, bạn có tham gia xây dựng Omni-channel OTA Integration Hub tích hợp các API REST/JSON và SOAP/XML. Bạn hãy chia sẻ về khó khăn lớn nhất khi xử lý tích hợp SOAP/XML và cách bạn đã giải quyết nó nhé?", "questionType": "BLUEPRINT", "questionOrder": 5, "behavioralWarnings": []}, {"score": null, "feedback": null, "answerText": "Set the catch schema validation exception ngay log full request cộng error detail rồi return so SOAB foul respond chuẩn cho client không retry nên thread không crash hay treo.", "suggestion": null, "questionText": "Cảm ơn chia sẻ của bạn, việc sử dụng Apache CXF và custom interceptor là cách tiếp cận rất bài bản. Bạn có thể làm rõ hơn trong quá trình map dữ liệu phức tạp đó, nếu gặp một lỗi không khớp schema (schema validation error) ngay tại runtime thì interceptor của bạn xử lý logging và thông báo lỗi cho client như thế nào để đảm bảo hệ thống không bị crash hoặc treo luồng?", "questionType": "FOLLOW_UP", "questionOrder": 6, "behavioralWarnings": []}, {"score": 0.0, "feedback": "Câu trả lời không liên quan đến chuyên môn, thể hiện sự thiếu nghiêm túc và kỹ năng giao tiếp yếu kém.", "answerText": "Tôi muốn ăn phở.", "suggestion": "Keywords: Dynamic Dispatch, Method Overriding/Overloading, Interface-based design, Dependency Inversion Principle, Loose Coupling.\n\nStructure:\n- Definition: Định nghĩa ngắn gọn về việc thay đổi hành vi thông qua nạp chồng (compile-time) và ghi đè (runtime).\n- Implementation: Mô tả cách sử dụng Interface/Abstract Class để tách biệt giữa ''hợp đồng'' (interface) và ''thực thi'' (implementation).\n- Real-world project: Nêu bài toán thực tế (ví dụ: Hệ thống Payment Gateway hỗ trợ nhiều nhà cung cấp - VNPAY, MOMO, Stripe) dùng đa hình để thống nhất Interface, giúp mở rộng hệ thống mà không cần sửa code cũ.\n\nSenior Tip: Tập trung vào việc đa hình giúp tuân thủ nguyên lý Open/Closed (SOLID) như thế nào để giảm thiểu rủi ro khi thay đổi logic hệ thống.", "questionText": "Cảm ơn bạn, cách xử lý qua SOAP Fault là phương án rất chuẩn mực để đảm bảo tính ổn định và tường minh cho hệ thống khi giao tiếp với đối tác. Tiếp nối buổi trao đổi, chúng ta cùng quay lại một chút với kiến thức nền tảng Java nhé. Trong lập trình hướng đối tượng, bạn hãy giải thích tính đa hình (Polymorphism) là gì và cho một ví dụ thực tế cách bạn đã áp dụng nó trong dự án?", "questionType": "BLUEPRINT", "questionOrder": 7, "behavioralWarnings": []}, {"score": 0.0, "feedback": "Ứng viên trả lời lạc đề, thiếu thái độ nghiêm túc và không thể hiện bất kỳ năng lực kỹ thuật nào.", "answerText": "Tôi muốn ăn phở.", "suggestion": "Keywords: Inversion of Control (IoC), Bean Lifecycle, BeanFactory vs ApplicationContext, Autowiring.\n\nStructure:\n- Khái niệm: Giải thích DI là cách hiện thực hóa IoC bằng cách tách biệt creation và usage.\n- Cơ chế: Phân tích quá trình quét (ComponentScan), đăng ký (Bean Definition), và tiêm phụ thuộc (Dependency Resolution).\n- Trade-off: So sánh Constructor Injection vs Field Injection (Unit testing, Immutability).\n\nSenior Tip: Hãy đề cập đến cách Spring Container quản lý scope (Singleton/Prototype) và hiệu năng khi khởi tạo Bean (Lazy vs Eager initialization).", "questionText": "Có vẻ như chúng ta đang có chút nhầm lẫn trong phản hồi vừa rồi. Để không làm mất thời gian của bạn, tôi xin phép chuyển sang chủ đề kỹ thuật tiếp theo. Chúng ta hãy cùng trao đổi về Spring Boot nhé: Bạn có thể giải thích cơ chế Dependency Injection trong Spring Boot hoạt động như thế nào và lợi ích chính của nó là gì không?", "questionType": "BLUEPRINT", "questionOrder": 8, "behavioralWarnings": []}, {"score": 4.5, "feedback": "Thiếu kiến thức hệ thống về độ bền dữ liệu (durability) và phân biệt giữa lỗi mạng với lỗi ghi đĩa.", "answerText": "Rainbow kill the persistent message but publisher confirm the consumer act to confirm dead letter kill the message lỗi", "suggestion": "Keywords: Durable Queues, Persistent Messages, Publisher Confirms, Manual Acknowledgment, Idempotency.\n\nStructure:\n- Bước 1: Đảm bảo thiết lập Producer (Publisher Confirms + Mandatory flag) để xác nhận broker đã nhận và persist message.\n- Bước 2: Cấu hình Queue/Message (Durable/Persistent) để message nằm trên disk thay vì RAM.\n- Bước 3: Cấu hình Consumer (Manual Acknowledgement) thay vì Auto-ACK để đảm bảo message chỉ bị xóa khi đã xử lý xong.\n- Bước 4: Thiết lập Dead Letter Exchange (DLX) để xử lý các message lỗi (poison messages) không thể xử lý sau nhiều lần retry.\n\nSenior Tip: Phải nhắc tới tính Idempotency ở phía Consumer, vì cơ chế retry/ack lỗi có thể dẫn đến việc xử lý trùng lặp message (exactly-once delivery là cực khó).", "questionText": "Có vẻ như câu trả lời vừa rồi không liên quan đến chủ đề kỹ thuật chúng ta đang thảo luận. Để tối ưu thời gian cho buổi phỏng vấn, chúng ta hãy chuyển sang một chủ đề thực tế hơn. Bạn hãy cho biết: Khi xây dựng hệ thống Microservices sử dụng RabbitMQ làm message broker, làm thế nào để đảm bảo message không bị mất khi có sự cố xảy ra?", "questionType": "BLUEPRINT", "questionOrder": 9, "behavioralWarnings": []}, {"score": null, "feedback": null, "answerText": "Publish a confirm bonus of the message as for your broker the NACK like có NACK bằng message đã vào queue an toàn có NACK được hang out bằng gửi ạ.", "suggestion": null, "questionText": "Dường như bạn đang đề cập đến các kỹ thuật như ''Publisher Confirms'' và ''Dead Letter Exchange''. Để làm rõ hơn, bạn có thể giải thích cụ thể cơ chế ''Publisher Confirms'' hoạt động như thế nào và tại sao nó lại giúp hệ thống biết được message đã được broker tiếp nhận an toàn hay chưa?", "questionType": "FOLLOW_UP", "questionOrder": 10, "behavioralWarnings": []}, {"score": null, "feedback": null, "answerText": "NACK nghĩa là broker từ chối nhận messenger, publisher phải retry gửi lại, có giới hạn lần hoặc đẩy vào dead letter lưu database để xử lý sau tránh mất data.", "suggestion": null, "questionText": "Cách diễn đạt của bạn về cơ chế NACK còn hơi khó hiểu. Để làm rõ hơn: Nếu Publisher nhận được tín hiệu NACK từ RabbitMQ, điều đó có nghĩa là gì và theo bạn, Publisher nên có hành động xử lý tiếp theo như thế nào để đảm bảo tính toàn vẹn của dữ liệu?", "questionType": "FOLLOW_UP", "questionOrder": 11, "behavioralWarnings": []}, {"score": 3.5, "feedback": "Câu trả lời thiếu chuyên nghiệp, thuật ngữ lộn xộn, không thể hiện được tư duy kỹ thuật của một Senior.", "answerText": "CID đảm bảo giao dịch atomic all or nothing consistent bốn rule isolate không ảnh hưởng nhau durable không mất sau commit quan trọng vì tránh data size mất tiền raise commission cho hệ thống giao dịch", "suggestion": "Keywords: MVCC (Multi-Version Concurrency Control), Snapshot Isolation, Serializable, Write Skew, Lock-based Concurrency.\n\nStructure:\n- Bước 1: Khẳng định vai trò của MVCC trong PostgreSQL (không khóa hàng mà sử dụng phiên bản dữ liệu).\n- Bước 2: Phân tích ''Read Committed'': Chỉ đọc dữ liệu đã commit tại thời điểm câu lệnh query bắt đầu (ngăn Dirty Read).\n- Bước 3: Phân tích ''Repeatable Read'': Đọc dữ liệu tại thời điểm transaction bắt đầu (Snapshot), đảm bảo dữ liệu nhất quán trong suốt vòng đời transaction (ngăn Non-repeatable Read).\n- Bước 4: So sánh Trade-off: Rủi ro Serialization Failure (Error code 40001) khi chọn mức cô lập cao hơn.\n\nSenior Tip: Luôn chủ động nhắc đến rủi ro ''Write Skew'' và cách giải quyết bằng ''SELECT FOR UPDATE'' hoặc mức ''Serializable'' để thể hiện tư duy thiết kế hệ thống an toàn.", "questionText": "Cảm ơn bạn, ý tưởng về việc retry và sử dụng Dead Letter Queue để tránh mất dữ liệu là hoàn toàn chính xác. Tiếp theo, chúng ta sẽ chuyển sang phần Database. Trong cơ sở dữ liệu quan hệ như PostgreSQL, tính chất ACID đóng vai trò gì và tại sao chúng lại quan trọng đối với các ứng dụng giao dịch?", "questionType": "BLUEPRINT", "questionOrder": 12, "behavioralWarnings": []}, {"score": null, "feedback": null, "answerText": "뭐? grants과 좀 MDCC, mỗi transaction tới snapshot lưu liệu riêng. Không bị block lẫn nhau. Quan trọng vì tránh dirty read. Non-repeatable read. Phantom read. Ghi nhờ transaction chạy song song. ¿Qué?", "suggestion": null, "questionText": "Giải thích của bạn khá tốt về mặt ý nghĩa thực tế. Để hiểu rõ hơn về cách PostgreSQL thực hiện điều này, bạn có thể giải thích cụ thể hơn tính chất ''Isolation'' (Cô lập) được xử lý như thế nào không? Tại sao nó lại quan trọng khi có nhiều giao dịch xảy ra cùng một lúc?", "questionType": "FOLLOW_UP", "questionOrder": 13, "behavioralWarnings": []}, {"score": null, "feedback": null, "answerText": "Chủ thớt data đã commit cho ít đất free ship nhưng vẫn bị lo vì bit table rich. Phantom rich. Bit table rich snapshot. Cố định thông suốt transaction. Chấm thêm non. Bit table rich. Bỏ. Stress. Circle. Còn chấm luôn. Cả. Phantom rich. Nhờ. Mv. Cc.", "suggestion": null, "questionText": "Có vẻ bạn đang hơi bối rối về cách diễn đạt. Quay lại vấn đề kỹ thuật, bạn vừa nhắc đến việc tránh các hiện tượng như Dirty Read hay Phantom Read nhờ vào mức độ cô lập (Isolation levels). Bạn có thể phân biệt rõ hơn: mức độ ''Read Committed'' khác gì với ''Repeatable Read'' trong việc xử lý các vấn đề này không?", "questionType": "FOLLOW_UP", "questionOrder": 14, "behavioralWarnings": []}, {"score": 2.0, "feedback": "Ứng viên thiếu sự chuẩn bị chuyên nghiệp, thái độ hời hợt và đặt câu hỏi không có giá trị tư duy hệ thống.", "answerText": "재밌는 점 마이크로서비스와 CICD, 코어앱과의 멤버십에 대해 좀 더 리얼하게 예언해 줄 수 있나요? ¿Qué es el número de cuenta?", "suggestion": "Keywords: System Architecture, Deployment Strategy, Service Mesh, Observability, Scalability.\n\nStructure:\n- Bước 1: Câu hỏi về kiến trúc (Ví dụ: ''Cách đội ngũ xử lý vấn đề Distributed Tracing khi microservices gặp lỗi chuỗi?'').\n- Bước 2: Câu hỏi về vận hành (Ví dụ: ''Chiến lược Canary Deployment hoặc Blue-Green được áp dụng thế nào để giảm thiểu rủi ro khi release?'').\n- Bước 3: Câu hỏi về văn hóa kỹ thuật (Ví dụ: ''Đội ngũ ưu tiên giải quyết Technical Debt như thế nào trong chu kỳ phát triển sản phẩm?'').\n\nSenior Tip: Đừng hỏi những câu mơ hồ; hãy thể hiện bạn đã nghiên cứu sâu về quy mô (Scale) và các bài toán khó mà công ty đang đối mặt để gây ấn tượng với người phỏng vấn.", "questionText": "Cảm ơn bạn đã chia sẻ về các khái niệm trong cơ sở dữ liệu. Chúng ta đã cùng nhau thảo luận qua nhiều khía cạnh kỹ thuật quan trọng của buổi phỏng vấn. Đến đây, các câu hỏi chuyên môn đã hoàn tất. Trước khi kết thúc, bạn có câu hỏi nào dành cho tôi về công việc hoặc về đội ngũ kỹ thuật của chúng tôi không?", "questionType": "BLUEPRINT", "questionOrder": 15, "behavioralWarnings": []}, {"score": null, "feedback": null, "answerText": "CICI now có gì hết.", "suggestion": null, "questionText": "Chào bạn, có vẻ như câu hỏi của bạn đang có sự pha trộn ngôn ngữ và tôi chưa nắm rõ ý bạn muốn hỏi về ''số tài khoản'' (núơc nào) hay cụ thể là kiến trúc Microservices và CI/CD trong hệ thống của chúng tôi. Ý bạn muốn hỏi về cách chúng tôi triển khai CI/CD để đảm bảo tính ổn định cho kiến trúc Microservices hay cách tích hợp hệ thống thành viên (membership)? Bạn vui lòng chia sẻ rõ hơn để tôi có thể giải đáp chính xác nhé.", "questionType": "FOLLOW_UP", "questionOrder": 16, "behavioralWarnings": []}], "improvementPlan": null, "aiOverviewFeedback": "Đã chấm điểm xong."}', '{"domain": "IT", "language": "VI", "difficulty": "FRESHER_BASIC", "interview_mode": "STANDARD_MOCK", "duration_minutes": 20}', 358),
        (147, null, 9, null, '2026-08-13 07:09:03.985300', '2026-08-13 07:09:05.411078', 'IT', 'IN_PROGRESS', 'STANDARD_MOCK', null, '0179fbef-f579-4810-af32-6c48d533dabe', '{"blueprint": [{"questions": [{"order": 1, "rag_keyword": null, "question_text": "Chào bạn, rất vui được gặp bạn trong buổi phỏng vấn hôm nay. Bạn hãy dành khoảng 1-2 phút giới thiệu ngắn gọn về bản thân cũng như kinh nghiệm làm việc với vai trò Back-end Developer của mình nhé.", "question_type": "CORE"}], "phase_name": "Mở đầu", "duration_minutes": 1}, {"questions": [{"order": 2, "rag_keyword": null, "question_text": "Trong dự án ''Movie Theater'', bạn sử dụng ASP.NET Core và SignalR để làm tính năng real-time seat map. Bạn có thể giải thích cách SignalR hoạt động để cập nhật sơ đồ ghế ngồi theo thời gian thực không?", "question_type": "CORE"}, {"order": 3, "rag_keyword": null, "question_text": "Với dự án ''Child Vaccine Schedule Tracking System'' sử dụng Spring Boot và Spring Security, bạn đã cấu hình cơ chế xác thực và phân quyền như thế nào cho hệ thống?", "question_type": "CORE"}], "phase_name": "Đào sâu dự án", "duration_minutes": 4}, {"questions": [{"order": 4, "rag_keyword": "spring_boot_dependency_injection_ioc", "question_text": "Trong Spring Boot, khái niệm Dependency Injection và IoC Container là gì và chúng giúp ích gì cho việc phát triển ứng dụng?", "question_type": "CORE"}, {"order": 5, "rag_keyword": "hibernate_n_plus_one_query_problem", "question_text": "Khi sử dụng Spring Data JPA và Hibernate, bạn hiểu thế nào về hiện tượng N+1 query problem và cách khắc phục cơ bản?", "question_type": "CORE"}, {"order": 6, "rag_keyword": "java_oop_polymorphism", "question_text": "Trong lập trình hướng đối tượng (OOP) với Java, tính đa hình (Polymorphism) được thể hiện qua những cách nào?", "question_type": "CORE"}], "phase_name": "Kiến thức kỹ thuật cốt lõi", "duration_minutes": 5}], "strategy_analysis": "Áp dụng chế độ STANDARD_MOCK với thời lượng ngắn 10 phút, độ khó FRESHER_BASIC. Bố cục gồm 3 giai đoạn: Mở đầu (1 phút), Đào sâu dự án cá nhân (4 phút) và Kiểm tra kiến thức kỹ thuật cơ bản (5 phút), tập trung vào Java, Spring Boot và ASP.NET Core có trong CV."}', '{"id": 48, "tools": ["Git", "GitHub", "GitLab", "Maven", "Jira", "Swagger", "Docker", "Postman", "JUnit", "xUnit", "Cloudinary", "Firebase Cloud Messaging"], "projects": [{"name": "Movie Theater", "role": "Back-end, Leader", "outcome": "Final score: 9.7", "teamSize": 5, "usedTools": ["ASP.NET Core", "ASP.NET MVC", "PostgreSQL", "SignalR"], "description": "An online movie ticketing system featuring real-time seat map visualization."}, {"name": "Child Vaccine Schedule Tracking System", "role": "Back-end, Leader", "outcome": null, "teamSize": 3, "usedTools": ["Java", "Spring Boot", "Spring Security", "Spring AI", "MSSQL", "Spring Mail"], "description": "A web application that manages children''s vaccination schedules, allowing parents and health centers to schedule, track, and update vaccination records."}, {"name": "Bambi Kitchen", "role": "Back-end, Leader", "outcome": null, "teamSize": 6, "usedTools": ["Spring Boot", "Spring Security", "Spring AI", "MSSQL", "Cloudinary", "Firebase Cloud Messaging", "Spring Mail"], "description": "A food chain that specializes in providing healthy dishes and customers can customize and choose personalized dish ingredients, with integrated AI to evaluate orders."}], "createdAt": [2026, 8, 13, 7, 7, 10, 760005000], "updatedAt": [2026, 8, 13, 7, 7, 10, 760027000], "educations": [{"gpa": "3.2", "major": "Software Engineering", "degree": null, "school": "FPT University", "end_date": "2026", "start_date": "2022"}], "softSkills": ["Technical Reading Proficiency in English", "Fast learner", "Adaptability", "Problem-solving", "Teamwork"], "targetRole": "Java Developer", "targetLevel": "Intern", "achievements": ["Honorable Student of Trimester - Semester 1, 3, 4, 5"], "introduction": "As a Java Developer, I am eager to work in a challenging environment to develop my skills and gain practical experience. I leverage my logical thinking and passion for programming to quickly transform knowledge into practical solutions, aiming to become an effective and well-grounded software development specialist.", "applicationId": 148, "certifications": ["Web Design for Everybody: Basics of Web Development & Coding", "Software Development Lifecycle", "Java FullStack Developer"], "technicalSkills": ["Java", "C#", "HTML", "CSS", "Spring Security", "Spring Data JPA", "Spring MVC", "Validation", "DI/IoC", "ASP.NET", "ASP.NET Core", "MSSQL", "PostgreSQL", "JPA", "Hibernate", "MongoDB", "SignalR", "Spring Boot", "Spring AI", "Spring Mail"], "workExperiences": [{"company": "FPT Software Academy", "end_date": "08/2025", "position": ".NET Developer Intern", "start_date": "05/2025", "description": "Final Training Project: Movie Theater. Role: Back-end, Leader. Developed an online movie ticketing system featuring real-time seat map visualization, movie management, showtimes, theaters, promotions, user accounts, and points accumulation."}]}', '{"basic_info": {"job_title": "AI Interview", "industry_domain": "Artificial Intelligence / Recruitment Tech", "seniority_level": null}, "competencies": {"hard_skills": [], "soft_skills": [], "tools_and_platforms": []}, "responsibilities": []}', null, '{"domain": "IT", "language": "VI", "difficulty": "FRESHER_BASIC", "interview_mode": "STANDARD_MOCK", "duration_minutes": 10}', 369),
