        (453, '{"maxScore": 100, "instruction": "Take the theory multiple-choice test.", "quizQuestions": [{"points": 10, "options": ["\"number\"", "\"NaN\"", "\"undefined\"", "\"object\""], "questionText": "In JavaScript, what is the result of the expression console.log(typeof NaN)?", "correctAnswer": "\"number\""}, {"points": 10, "options": ["3", "4", "5", "Undefined"], "questionText": "What is the correct result of the following code snippet:\n```javascript\nconst a = [1, 2, 3];\nconst b = a;\nb.push(4);\nconsole.log(a.length);\n```", "correctAnswer": "4"}], "aiSystemPrompt": "", "codingProblems": [], "mentorInterview": null, "submissionFormat": "", "timeLimitMinutes": 20, "codeReviewProblems": [], "evaluationCriteria": ""}', '2026-07-26 13:53:43.827294', false, 'Quiz', 80, 3, 'QUIZ', '2026-07-26 13:53:43.827316', 39, false, null),
        (455, '{"maxScore": 100, "instruction": "Review the following source code and point out areas for optimization.", "quizQuestions": [], "aiSystemPrompt": "", "codingProblems": [], "mentorInterview": null, "submissionFormat": "", "timeLimitMinutes": 30, "codeReviewProblems": [{"files": [{"content": "package com.example.dto;\n\nimport com.fasterxml.jackson.annotation.JsonIgnore;\n\npublic class UserDto {\n    private Long id;\n    private String username;\n    private String password; // BUG: password should be ignored in JSON responses\n    private String email;\n\n    public Long getId() { return id; }\n    public void setId(Long id) { this.id = id; }\n\n    public String getUsername() { return username; }\n    public void setUsername(String username) { this.username = username; }\n\n    public String getPassword() { return password; }\n    public void setPassword(String password) { this.password = password; }\n\n    public String getEmail() { return email; }\n    public void setEmail(String email) { this.email = email; }\n}\n", "filename": "src/main/java/com/example/dto/UserDto.java", "language": "java"}, {"content": "package com.example.service;\n\nimport com.example.dto.UserDto;\nimport java.util.ArrayList;\nimport java.util.List;\n\npublic class UserService {\n    public List<UserDto> getAllUsers() {\n        // In a real app this would query a DB\n        List<UserDto> users = new ArrayList<>();\n        UserDto u = new UserDto();\n        u.setId(1L);\n        u.setUsername(\"alice\");\n        u.setPassword(\"secret123\"); // password stored in plain text\n        u.setEmail(\"alice@example.com\");\n        users.add(u);\n        return users;\n    }\n}\n", "filename": "src/main/java/com/example/service/UserService.java", "language": "java"}, {"content": "package com.example.controller;\n\nimport com.example.dto.UserDto;\nimport com.example.service.UserService;\nimport org.springframework.web.bind.annotation.GetMapping;\nimport org.springframework.web.bind.annotation.RestController;\nimport java.util.List;\n\n@RestController\npublic class UserController {\n    private final UserService userService = new UserService();\n\n    @GetMapping(\"/users\")\n    public List<UserDto> listUsers() {\n        return userService.getAllUsers();\n    }\n}\n", "filename": "src/main/java/com/example/controller/UserController.java", "language": "java"}, {"content": "package com.example.config;\n\nimport org.springframework.context.annotation.Configuration;\nimport org.springframework.security.config.annotation.web.builders.HttpSecurity;\nimport org.springframework.security.config.annotation.web.configuration.EnableWebSecurity;\nimport org.springframework.security.config.annotation.web.configuration.WebSecurityConfigurerAdapter;\n\n@Configuration\n@EnableWebSecurity\npublic class SecurityConfig extends WebSecurityConfigurerAdapter {\n    @Override\n    protected void configure(HttpSecurity http) throws Exception {\n        http\n            .csrf().disable()\n            .authorizeRequests()\n                .anyRequest().permitAll(); // BUG: all endpoints are publicly accessible\n    }\n}\n", "filename": "src/main/java/com/example/config/SecurityConfig.java", "language": "java"}], "title": "Sensitive Information Leakage via API", "language": "Java", "problemId": 2, "difficulty": "HARD", "expectedIssues": [{"filename": "src/main/java/com/example/dto/UserDto.java", "severity": "CRITICAL", "lineNumber": 8, "description": "The password field is included in the DTO without @JsonIgnore, causing credentials to be serialized and sent to clients. This leaks sensitive information. Fix by adding @JsonIgnore to the password field or removing it from the response model."}, {"filename": "src/main/java/com/example/config/SecurityConfig.java", "severity": "CRITICAL", "lineNumber": 16, "description": "Security configuration uses anyRequest().permitAll(), which disables authentication and authorization for all endpoints, exposing the API to unauthenticated access. Restrict access by defining proper antMatchers and requiring authentication."}], "problemStatement": "A small Spring Boot style service exposes a REST endpoint that returns a list of users. The project consists of four source files: UserController.java, UserService.java, UserDto.java, and SecurityConfig.java. The code contains two critical security flaws: (1) the UserDto includes the password field in JSON responses, leaking credentials; (2) the security configuration permits all requests without authentication. The candidate must review the code, identify the exact locations of these issues, assess their severity, and propose proper fixes (e.g., adding @JsonIgnore to the password field and restricting endpoint access)."}, {"files": [{"content": "", "filename": "Solution.java", "language": "java"}], "title": "N+1", "language": "C#", "problemId": 7, "difficulty": "HARD", "expectedIssues": null, "problemStatement": "N+1 cho bài toán 1 lớp học có nhiều sutdent, 3 file controller - service - repo"}], "evaluationCriteria": ""}', '2026-07-26 13:53:43.833478', false, 'Code Review', 80, 5, 'CODE_REVIEW', '2026-07-26 13:53:43.833502', 39, false, null),
