        (223, null, null, 107, null, '2026-07-28 17:34:07.938060', 'FAILED', 0, null, null, 725, '2026-07-28 17:34:07.938087', 'COMPLETED', '{"fileUrl": null, "quizAnswers": [{"isCorrect": false, "questionText": "Câu lệnh SQL nào dùng để đếm số dòng có giá trị khác NULL trong một cột?", "selectedAnswer": "A"}, {"isCorrect": false, "questionText": "Trong lập trình hướng đối tượng (OOP), tính chất nào cho phép các lớp con định nghĩa lại một phương thức đã có ở lớp cha?", "selectedAnswer": "A"}], "textContent": null, "codeSubmissions": null, "emailSubmissionId": null, "codeReviewSubmissions": null}', '2026-07-28 17:34:07.938097', null, null, null, null, null, null),
        (224, null, null, 107, null, '2026-07-28 17:35:26.607230', 'PASSED', 180, null, null, 726, '2026-07-28 17:35:26.607304', 'COMPLETED', '{"fileUrl": null, "quizAnswers": null, "textContent": "// --- Problem 4 ---\nclass Solution {\n    public int[] solution(int[] nums,int target) {\n        java.util.Map<Integer,Integer> map = new java.util.HashMap<>();\n        for (int i = 0; i < nums.length; i++) {\n            int complement = target - nums[i];\n            if (map.containsKey(complement)) {\n                return new int[] { map.get(complement),i };\n            }\n            map.put(nums[i],i);\n        }\n        return new int[] {};\n    }\n}\n\n// --- Problem 21 ---\nclass Solution {\n    public String solution(String s) {\n        return new StringBuilder(s).reverse().toString();\n    }\n}", "codeSubmissions": [{"testCases": {"status": "ERROR", "testCases": [{"index": 0, "input": ", ", "status": "ERROR", "actualOutput": null, "errorMessage": "RUNTIME_ERROR: Exception in thread \"main\" java.lang.StringIndexOutOfBoundsException: begin 1, end -1, length 0\n\tat java.base/java.lang.String.checkBoundsBeginEnd(String.java:4606)\n\tat java.base/java.lang.String.substring(String.java:2709)\n\tat TypeParser.parseIntArray(Solution.java:50)\n\tat Solution.main(Solution.java:20)", "expectedOutput": "", "executionTimeMs": 133}, {"index": 1, "input": "[3,2,4], 6", "status": "PASSED", "actualOutput": "[1,2]", "errorMessage": null, "expectedOutput": "[1,2]", "executionTimeMs": 168}, {"index": 2, "input": "[3,3], 6", "status": "PASSED", "actualOutput": "[0,1]", "errorMessage": null, "expectedOutput": "[0,1]", "executionTimeMs": 174}, {"index": 3, "input": "[-1,-2,-3,-4,-5], -8", "status": "PASSED", "actualOutput": "[2,4]", "errorMessage": null, "expectedOutput": "[2,4]", "executionTimeMs": 149}, {"index": 4, "input": "[1000000000,1,1000000000,2], 3", "status": "PASSED", "actualOutput": "[1,3]", "errorMessage": null, "expectedOutput": "[1,3]", "executionTimeMs": 175}, {"index": 5, "input": "[-1,0,1,2,-2], 0", "status": "PASSED", "actualOutput": "[0,2]", "errorMessage": null, "expectedOutput": "[0,2]", "executionTimeMs": 181}], "errorMessage": null, "totalTestCases": 6, "executionTimeMs": 163, "passedTestCases": 5}, "sourceCode": ["class Solution {", "    public int[] solution(int[] nums,int target) {", "        java.util.Map<Integer,Integer> map = new java.util.HashMap<>();", "        for (int i = 0; i < nums.length; i++) {", "            int complement = target - nums[i];", "            if (map.containsKey(complement)) {", "                return new int[] { map.get(complement),i };", "            }", "            map.put(nums[i],i);", "        }", "        return new int[] {};", "    }", "}"]}, {"testCases": {"status": "PASSED", "testCases": [{"index": 0, "input": "\"world\"", "status": "PASSED", "actualOutput": "\"dlrow\"", "errorMessage": null, "expectedOutput": "\"dlrow\"", "executionTimeMs": 189}, {"index": 1, "input": "\"\"", "status": "PASSED", "actualOutput": "\"\"", "errorMessage": null, "expectedOutput": "\"\"", "executionTimeMs": 141}, {"index": 2, "input": "\"a\"", "status": "PASSED", "actualOutput": "\"a\"", "errorMessage": null, "expectedOutput": "\"a\"", "executionTimeMs": 185}, {"index": 3, "input": "\"racecar\"", "status": "PASSED", "actualOutput": "\"racecar\"", "errorMessage": null, "expectedOutput": "\"racecar\"", "executionTimeMs": 189}], "errorMessage": null, "totalTestCases": 4, "executionTimeMs": 176, "passedTestCases": 4}, "sourceCode": ["class Solution {", "    public String solution(String s) {", "        return new StringBuilder(s).reverse().toString();", "    }", "}"]}], "emailSubmissionId": null, "codeReviewSubmissions": null}', '2026-07-28 17:35:26.607323', null, null, null, null, null, null),
        (226, '{"strengths": ["Ứng viên nhận diện chính xác vấn đề N+1 query và đề xuất giải pháp tối ưu hóa (batch query/JOIN FETCH) rất chuyên nghiệp. Ngoài ra, ứng viên còn chủ động phát hiện thêm lỗi bảo mật liên quan đến PII (Personally Identifiable Information) trong log, cho thấy tư duy phản biện tốt."], "weaknesses": ["Ứng viên review một file không tồn tại trong đề bài (StudentService), điều này cho thấy sự thiếu tập trung vào phạm vi (scope) của bài kiểm tra."], "extraMetrics": {"Bug Detection": 10, "Missed Issues": "Không bỏ sót lỗi nào trong danh sách expectedIssues.", "Solution Quality": 9, "Security Awareness": 9, "Clean Code Awareness": 8, "Code Smell Detection": 8, "Performance Analysis": 10}, "generalComment": "Ứng viên có trình độ kỹ thuật vững vàng, hiểu sâu về hiệu năng hệ thống và bảo mật. Nếu chú ý hơn vào phạm vi yêu cầu của đề bài, đây sẽ là một ứng viên xuất sắc cho vị trí Senior."}', 90, 107, null, '2026-07-28 17:43:02.160583', 'PASSED', 90, null, null, 727, '2026-07-28 17:43:02.160602', 'AI_EVALUATED', '{"fileUrl": null, "quizAnswers": null, "textContent": null, "codeSubmissions": null, "emailSubmissionId": null, "codeReviewSubmissions": [{"filename": "src/main/java/com/example/service/UserOrderService.java", "severity": "WARNING", "lineNumber": 31, "description": "Fetching orders inside a loop for every user causes an N+1 query problem, which will severely degrade performance. Please optimize this by fetching all orders for the given list of users in a single batch query (e.g., using an `IN` clause or `JOIN FETCH`), and then group them in memory."}, {"filename": "StudentService", "severity": "WARNING", "lineNumber": 21, "description": "Logging the entire `Student` object at the `INFO` level may expose sensitive personal information (PII) such as ID card numbers or addresses to log monitoring systems. You should only log non-sensitive identifiers (like `student.getId()`) or remove this log statement in production."}]}', '2026-07-28 17:43:02.160609', null, null, null, null, null, null),
        (228, '{"strengths": ["Nền tảng học vấn tốt về Kỹ thuật Phần mềm tại FPT University với GPA khá cao, cho thấy khả năng tiếp thu kiến thức tốt.", "Có kiến thức lý thuyết vững chắc và lộ trình phát triển rõ ràng với hệ sinh thái Java Backend: Spring Boot, Spring Security, Spring Data JPA, JPA/Hibernate, các cơ sở dữ liệu (MSSQL, PostgreSQL, MongoDB) và công cụ (Git, Maven, Docker, Jira, JUnit).", "Thể hiện tinh thần chủ động học hỏi và áp dụng các công nghệ mới (Spring AI, Gemini AI) cũng như khả năng lãnh đạo (Leader trong các dự án)."], "weaknesses": ["Thiếu kinh nghiệm làm việc thực tế, đã hoàn thành và có thể kiểm chứng, do tất cả các mục kinh nghiệm/dự án đều có ngày bắt đầu trong tương lai.", "Hoàn toàn không đáp ứng yêu cầu \"4+ years of hands-on experience in Java development\" được liệt kê trong mô tả công việc.", "Kinh nghiệm với Kubernetes, CI/CD pipelines và các design patterns còn hạn chế hoặc chưa được thể hiện rõ ràng."], "extraMetrics": {"Keyword Density": {"SQL": 5, "Java": 5, "Docker": 1, "Kubernetes": 0, "Spring Boot": 3, "CI/CD pipelines": 0, "NoSQL databases": 1, "design patterns": 0, "RESTful API design": 0, "proactive attitude": 0, "problem-solving skills": 1, "microservices architecture": 3, "technical English proficiency": 1, "Object-Oriented Programming (OOP)": 0}, "Overall CV Match": 10, "Skills Match Score": 60, "Potential Red Flags": ["Có sự mâu thuẫn nghiêm trọng giữa cấp độ vị trí (New Java Fresher) và các yêu cầu kinh nghiệm (4+ năm kinh nghiệm Java và Spring Boot). Nếu xét theo yêu cầu kinh nghiệm, ứng viên không phù hợp. Nếu xét theo cấp độ Fresher, các yêu cầu lại quá cao và không thực tế.", "Tất cả kinh nghiệm làm việc (internship) và các dự án lớn đều được ghi với ngày tháng trong tương lai (2025-2026). Điều này gây nghi ngờ về tính xác thực của kinh nghiệm thực tế đã hoàn thành và cho thấy ứng viên hiện tại chưa có kinh nghiệm làm việc chính thức.", "Ứng viên đang là sinh viên, chưa tốt nghiệp đại học (dự kiến 2026), nên chưa có bằng cấp cử nhân/thạc sĩ theo yêu cầu.", "Thiếu kinh nghiệm cụ thể với một số công nghệ được yêu cầu như Kubernetes, CI/CD pipelines và các design patterns."], "CV Readability Score": 90, "Education Match Score": 60, "Experience Match Score": 0}, "generalComment": "Ứng viên là một sinh viên có tiềm năng với nền tảng học vấn tốt và kiến thức lý thuyết vững chắc về Java Backend cùng các công nghệ hiện đại. Tuy nhiên, hồ sơ này không phù hợp với vị trí do thiếu hụt nghiêm trọng kinh nghiệm làm việc thực tế, đã hoàn thành và có thể kiểm chứng. Đặc biệt, có sự mâu thuẫn lớn giữa cấp độ \"Fresher\" trong tiêu đề và yêu cầu \"4+ năm kinh nghiệm\" trong mô tả công việc. Nếu công ty thực sự tìm kiếm một Fresher, yêu cầu công việc cần được điều chỉnh. Ứng viên này có thể là một ứng cử viên phù hợp hơn cho các vị trí thực tập sinh (internship) bắt đầu từ năm 2025 sau khi hoàn thành các kinh nghiệm đã liệt kê."}', 17.5, 110, '2026-07-29 01:37:43.531307', '2026-07-29 01:34:40.962260', 'PASSED', 50, '', 50, 384, '2026-07-29 01:34:40.962304', 'COMPLETED', '{"fileUrl": "https://res.cloudinary.com/dimvyno0z/image/upload/v1785288880/my_app/docs/ab558f25-b7ce-45eb-a58e-65cb3c149790.pdf", "quizAnswers": null, "textContent": null, "codeSubmissions": null, "emailSubmissionId": null, "codeReviewSubmissions": null}', '2026-07-29 01:37:43.640318', null, null, null, null, null, null),
