        (308, null, null, 133, null, '2026-08-06 16:37:40.943087', 'PASSED', 12, null, null, 742, '2026-08-06 16:37:40.943103', 'COMPLETED', '{"fileUrl": null, "quizAnswers": [{"isCorrect": false, "questionText": "In JavaScript, what is the result of the expression console.log(typeof NaN)?", "selectedAnswer": "\"NaN\""}, {"isCorrect": true, "questionText": "What is the correct result of the following code snippet:\n```javascript\nconst a = [1, 2, 3];\nconst b = a;\nb.push(4);\nconsole.log(a.length);\n```", "selectedAnswer": "4"}, {"isCorrect": false, "questionText": "In CSS, which property is used to center an absolutely positioned child element both vertically and horizontally?", "selectedAnswer": "vertical-align: middle;"}, {"isCorrect": false, "questionText": "In React, when does the `useEffect` Hook with an empty dependency array `[]` execute?", "selectedAnswer": "Runs before the component unmounts"}, {"isCorrect": false, "questionText": "Given the following SQL snippet:\n```sql\nSELECT name, salary \nFROM employees \nWHERE salary > (SELECT AVG(salary) FROM employees);\n```\nWhat is this subquery called?", "selectedAnswer": "Correlated Subquery"}, {"isCorrect": false, "questionText": "Which SQL statement is used to count the number of rows with non-NULL values in a column?", "selectedAnswer": "COUNT(*)"}, {"isCorrect": false, "questionText": "In Object-Oriented Programming (OOP), which property allows child classes to redefine a method already present in the parent class?", "selectedAnswer": "Encapsulation"}], "textContent": null, "codeSubmissions": null, "emailSubmissionId": null, "codeReviewSubmissions": null}', '2026-08-06 16:37:40.943109', null, null, null, null, null, null),
        (438, '{"strengths": ["Nền tảng học vấn vững chắc chuyên ngành Kỹ thuật Phần mềm tại FPT University.", "Thành thạo hệ sinh thái Java Backend (Spring Boot, Hibernate) và cơ sở dữ liệu quan hệ (MS SQL Server, MySQL).", "Có kinh nghiệm thực tế qua các dự án cá nhân và đồ án nhóm (E-commerce), thể hiện rõ kỹ năng lập trình cả Front-end lẫn Back-end."], "weaknesses": ["Kinh nghiệm làm việc thực tế trong môi trường doanh nghiệp còn ngắn (các dự án mang tính chất học tập và thực tập ngắn hạn).", "Chưa làm nổi bật kinh nghiệm tối ưu hóa câu lệnh SQL (SQL optimization) và các phiên bản Java mới."], "extraMetrics": {"Keyword Density": {"Git": 1, "Java": 5, "Maven": 1, "Docker": 1, "PostgreSQL": 3, "Spring Boot": 3, "Spring Data JPA": 1}, "Overall CV Match": 88, "Skills Match Score": 90, "Potential Red Flags": [], "CV Readability Score": 90, "Education Match Score": 90, "Experience Match Score": 78}, "generalComment": "Ứng viên có nền tảng kỹ thuật tốt và các dự án thực tế phù hợp với định hướng Java Backend Developer. Mặc dù còn là sinh viên và kinh nghiệm doanh nghiệp chưa nhiều, hồ sơ thể hiện rõ sự chủ động và tiềm năng phát triển rất lớn."}', 85, 176, null, '2026-08-15 18:32:17.266434', null, null, null, null, 678, '2026-08-15 18:32:17.266462', 'AI_EVALUATED', '{"fileUrl": "https://res.cloudinary.com/dimvyno0z/image/upload/v1786818736/my_app/docs/2ce6e77e-5f10-4a5d-8e9d-c4e707dad352.pdf", "quizAnswers": null, "textContent": null, "codeSubmissions": null, "emailSubmissionId": null, "codeReviewSubmissions": null}', '2026-08-15 18:32:17.266473', null, null, null, null, null, null),
