    "SWIFT": "class Solution {\n    func solution(_ L: Int, _ R: Int, _ K: Int) -> Int {\n        return 0\n    }\n}",
    "SCALA": "class Solution {\n    def solution(L: Long, R: Long, K: Int): Int = {\n        0\n    }\n}"
  },
  "paramTypes": ["integer", "integer", "integer"],
  "returnType": "integer",
  "hiddenTestCases": [
    {
      "inputs": ["1", "10", "1"],
      "expectedOutput": "7",
      "weightPoints": 20
    },
